-- Descricoes das empresas importadas das planilhas
INSERT INTO empresa_infos (empresa_id, descricao) VALUES
(3, 'Empresa CodeGO - Líder em desenvolvimento econômico.'),
(4, 'Empresa ABC - Soluções inovadoras.'),
(5, 'A empresa Sun Foods Agroindustrial Centro Oeste LTDA de CNPJ 03.620.558/0001-68, foi fundada em 28/01/2000 na cidade Inhumas no estado Goiás. Sua atividade principal, conforme a Receita Federal, é 10.95-3-00 - Fabricação de especiarias, molhos, temperos e condimentos, atividades relacionadas com a pecuária realizadas sob contrato, não especificadas anteriormente. Sua situação cadastral até o momento é Ativa.'),
(7, 'A Indústria e Comércio Café Goianésia Ltda atua no segmento alimentício, especializada no beneficiamento, industrialização, torrefação, moagem e comercialização de café e produtos relacionados. A empresa desenvolve atividades voltadas à produção de cafés de qualidade para abastecimento do mercado varejista, atacadista e institucional.

Entre suas principais atividades estão a seleção e processamento de grãos de café, torrefação, moagem, empacotamento, comercialização e distribuição de café torrado e moído, além do fornecimento de produtos destinados ao consumo doméstico e comercial. A empresa atua com foco em qualidade, padronização dos processos, sabor, segurança alimentar, eficiência produtiva e satisfação de seus clientes e consumidores.'),
(9, 'A GSV Montagens Indústria Ltda atua no segmento industrial, especializada na fabricação, montagem e instalação de estruturas, equipamentos e sistemas destinados a aplicações industriais. A empresa desenvolve soluções voltadas à implantação, manutenção e modernização de unidades produtivas, atendendo diversos setores com foco em eficiência operacional, segurança e qualidade técnica.

Entre suas principais atividades estão a montagem eletromecânica, fabricação e montagem de estruturas metálicas, instalação de equipamentos industriais, tubulações, caldeiraria, soldagem, manutenção industrial e apoio à execução de projetos de engenharia. A empresa atua com foco em qualidade dos serviços, cumprimento de prazos, segurança do trabalho, inovação e atendimento às necessidades específicas de seus clientes e parceiros.'),
(11, 'Sua atividade principal é a fabricação de sisdemas de despoiramento, silos de armazenamento de farinha e cauderaria industrial pesada. Aplicáveis em diversas obras de engenharia possui 21 anos, 8 meses e 28 dias e foi fundada em 14/09/2004'),
(12, 'A Greca Distribuidora de Asfaltos Ltda. atua no segmento de infraestrutura e pavimentação, especializada na produção, distribuição e comercialização de produtos asfálticos destinados à construção, conservação e recuperação de rodovias, vias urbanas e obras de infraestrutura. A empresa integra o grupo Greca Asfaltos e é referência nacional no fornecimento de soluções para pavimentação e engenharia rodoviária.

Entre suas principais atividades estão a produção e distribuição de cimento asfáltico de petróleo (CAP), emulsões asfálticas, asfaltos modificados por polímeros, ligantes especiais, produtos para impermeabilização e insumos destinados à pavimentação. A empresa também oferece suporte técnico para aplicação de seus produtos e desenvolvimento de soluções voltadas à durabilidade e ao desempenho das obras viárias.

A Greca atua com foco em inovação tecnológica, qualidade, sustentabilidade, eficiência logística e desenvolvimento de soluções que contribuam para a segurança, a mobilidade e a modernização da infraestrutura de transportes no Brasil.'),
(14, 'A Solve Engenharia e Soluções Ltda é uma empresa comprometida com a transparência e a honestidade em suas relações com clientes e fornecedores. Ela atua na fabricação de obras de caldeiraria pesada e busca constantemente melhorar seus produtos e serviços para atender às necessidades dos clientes. A empresa valoriza a satisfação do cliente e oferece serviços personalizados, garantindo altos padrões de qualidade e inovação. Além disso, a Solve é reconhecida por sua dedicação à excelência e pela qualidade em todos os projetos que empreende'),
(18, 'A JM Paletes Empreendimentos de Madeira Ltda atua no segmento madeireiro e de logística, especializada na fabricação, recuperação e comercialização de paletes, embalagens de madeira e estruturas utilizadas para armazenamento, movimentação e transporte de mercadorias. A empresa atende clientes dos setores industrial, comercial, agrícola e de distribuição, oferecendo soluções voltadas à eficiência logística e à proteção de cargas.

Entre suas principais atividades estão a produção de paletes de madeira, caixas, engradados, estrados e embalagens industriais, além da recuperação, manutenção e reutilização de paletes. A empresa também pode fornecer soluções personalizadas para acondicionamento e transporte de produtos, adequadas às necessidades específicas de cada cliente.

A JM Paletes atua com foco em qualidade dos materiais, resistência, sustentabilidade, eficiência operacional, aproveitamento de recursos e atendimento às demandas logísticas de seus clientes e parceiros comerciais.'),
(19, 'Talisma Colors Ltda é uma empresa de Goianésia (GO) especializada em montagem industrial, serviços de engenharia e manutenção para os setores industrial e da construção civil.

A companhia também atua em instalações elétricas e hidráulicas, pintura industrial, tratamento e revestimento de metais, locação de equipamentos e administração de obras, oferecendo soluções integradas para projetos industriais e de infraestrutura.'),
(36, 'Fundada em 16/02/2004 e com razão social Sc Industria de Bolsas LTDA, está localizada na cidade Goianira do estado Goiás. Sua atividade principal, conforme a Receita Federal, é 15.21-1-00 - Fabricação de artigos para viagem, bolsas e semelhantes de qualquer material. Sua situação cadastral até o momento é Ativa'),
(37, 'A Alumínios Kelly é uma empresa goiana especializada na fabricação de utensílios e artigos de alumínio para uso doméstico, com atuação desde 1998. Localizada em Goianira (GO), a empresa produz itens metálicos voltados para cozinha e uso residencial, atendendo o mercado regional com foco em qualidade e durabilidade.

Com mais de duas décadas de atuação, a Alumínios Kelly se destaca no segmento de transformação de alumínio e fabricação de produtos metálicos para o dia a dia.'),
(39, 'Fundada em 17/05/2021 e com razão social Prosorvt Industria e Comercio LTDA, Sua situação cadastral até o momento é Ativa e  Sua atividade principal é de Fabricação de pós-alimentícios, de acordo com o código CNAE C-1099-6/02'),
(41, 'A Líder Botas Ltda atua no segmento calçadista, especializada na fabricação, industrialização e comercialização de botas e calçados destinados aos setores de segurança, trabalho, agronegócio, indústria, construção civil e uso cotidiano. A empresa desenvolve produtos que aliam conforto, resistência, durabilidade e proteção, atendendo às exigências de diferentes atividades profissionais e condições de uso.

Entre suas principais atividades estão a fabricação de botas de segurança, botas de PVC, calçados ocupacionais, calçados impermeáveis e outros equipamentos de proteção para os pés, além da comercialização e distribuição de seus produtos para revendedores, distribuidores, empresas e consumidores finais. A empresa atua em conformidade com normas técnicas e de segurança aplicáveis ao setor.

A Líder Botas atua com foco em qualidade, inovação, segurança, eficiência produtiva, conforto e satisfação de seus clientes, oferecendo soluções que contribuem para a proteção dos trabalhadores e o desempenho das atividades profissionais em diversos segmentos da economia.'),
(44, 'A Selecta Plasticos, cuja razão social é Selecta Plasticos Industria e Comercio LTDA, é uma empresa de CNPJ 09.153.157/0001-21 com sede na cidade de Goianira no estado Goiás, constituída em 22/10/2007. Atua principalmente em 22.29-3-01 - Fabricação de artefatos de material plástico para uso pessoal e doméstico. Enquadrada como Micro Empresa, natureza jurídica Sociedade Empresária Limitada. Encontra-se atualmente com situação Ativa na Receita Federal.'),
(45, 'Tamben conhecida comercialmente como Sacarias Jotaplastico é uma indústria sediada na região de Goianira/Goiânia especializada na fabricação e comercialização de embalagens e sacarias de ráfia'),
(47, 'A Jairo Xavier da Costa – JM Alumínios EIRELI atua no segmento de esquadrias e produtos de alumínio, especializada na fabricação, montagem e comercialização de estruturas e componentes destinados à construção civil. A empresa desenvolve soluções que combinam resistência, durabilidade, funcionalidade e acabamento, atendendo obras residenciais, comerciais e industriais.

Entre suas principais atividades estão a fabricação e instalação de portas, janelas, fachadas, divisórias, portões, guarda-corpos, esquadrias e demais estruturas em alumínio, além da comercialização de acessórios e componentes relacionados ao setor. A empresa também presta serviços de medição, montagem e acabamento para projetos sob medida.

A JM Alumínios atua com foco em qualidade dos materiais, precisão na execução, inovação, atendimento personalizado e satisfação de seus clientes, oferecendo soluções que contribuem para a valorização e funcionalidade dos empreendimentos.'),
(48, 'Também conhecida pelo nome fantasia Incinera Tratamento de Resíduo é uma empresa especializada em gestão integrada e incineração de resíduos (Classe I e II): Segregação, armazenamento temporário e logística, garantindo rastreabilidade e compliance ambiental , A sua planta industrial está localizada no Distrito Agroindustrial de Senador Canedo, na Região Metropolitana de Goiânia, GO'),
(49, 'A Indústria de Alumínios Progresso Ltda atua no segmento metalúrgico, especializada na fabricação, industrialização e comercialização de produtos e artefatos em alumínio destinados aos setores da construção civil, industrial, comercial e residencial. A empresa desenvolve soluções que combinam resistência, leveza, durabilidade e acabamento de qualidade.

Entre suas principais atividades estão a produção de esquadrias de alumínio, portas, janelas, perfis, estruturas metálicas leves, componentes para construção civil e outros artefatos fabricados em alumínio, além da comercialização e distribuição desses produtos. A empresa atua com foco em qualidade dos materiais, inovação, eficiência produtiva, precisão nos acabamentos e atendimento às necessidades específicas de seus clientes e parceiros comerciais.'),
(50, 'A Carboquima é uma empresa brasileira especializada na produção e comercialização de carvão vegetal, biomassa e soluções energéticas para a indústria.

A companhia atua no fornecimento de insumos energéticos para setores como siderurgia, metalurgia e indústrias em geral, com foco em eficiência produtiva e sustentabilidade. Seus processos buscam aliar desempenho energético à responsabilidade ambiental.

Com experiência no setor, a Carboquima contribui para a cadeia industrial por meio de produtos voltados à geração de energia térmica e redução de impactos ambientais.'),
(51, 'A Alumínio W. Nissei Ltda é uma empresa brasileira localizada em Senador Canedo (GO), especializada na fabricação e comercialização de esquadrias, estruturas e produtos de alumínio.

A companhia atende os setores da construção civil e industrial, oferecendo soluções em alumínio para projetos residenciais, comerciais e corporativos. Seu foco está na qualidade dos produtos, durabilidade e atendimento às necessidades de cada projeto.'),
(53, 'A Calçados Aryetta Ltda é uma empresa brasileira especializada na fabricação de calçados femininos, atuando no desenvolvimento e produção de produtos voltados para moda, conforto e estilo.

A companhia atende o mercado de vestuário e acessórios, produzindo calçados para diferentes perfis de consumidoras e acompanhando tendências do setor. Seu foco está na qualidade dos materiais, acabamento e design dos produtos.

Com atuação no segmento calçadista, a Aryetta contribui para a indústria da moda nacional por meio da fabricação e comercialização de calçados.'),
(54, 'A Goyazes Indústria e Comércio de Calçados EIRELI atua no segmento calçadista, especializada na fabricação e comercialização de botas, calçados e acessórios voltados principalmente para os setores agropecuário, country e de moda. A empresa desenvolve produtos que combinam conforto, durabilidade, qualidade artesanal e design, atendendo consumidores em todo o território nacional.

Entre suas principais atividades estão a produção de botas de couro, calçados masculinos e femininos, acessórios e artigos relacionados ao vestuário country, além da comercialização e distribuição de seus produtos para lojas, revendedores e consumidores finais. A empresa atua com foco em qualidade dos materiais, acabamento, inovação, tradição artesanal e satisfação de seus clientes, consolidando sua presença no mercado de calçados e artigos country.'),
(55, 'A Alta Cosmética Indústria, Comércio, Importação e Exportação Ltda é uma empresa brasileira especializada na fabricação de cosméticos, produtos de higiene pessoal e perfumaria.

Localizada em Goiás, a companhia atua no desenvolvimento, produção e comercialização de produtos voltados aos cuidados pessoais, beleza e bem-estar, atendendo o mercado nacional com soluções para diferentes segmentos do setor cosmético.

A empresa também realiza atividades de importação e exportação, ampliando sua atuação no mercado de cosméticos e produtos de higiene.'),
(56, 'A Maqna Misturadores Ltda atua no segmento de máquinas e equipamentos industriais, especializada no desenvolvimento, fabricação e comercialização de misturadores e equipamentos para processos produtivos. A empresa atende indústrias de diversos segmentos, oferecendo soluções voltadas à mistura, homogeneização e processamento de matérias-primas com eficiência, precisão e confiabilidade.

Entre suas principais atividades estão a fabricação de misturadores industriais, agitadores, sistemas de dosagem, tanques de processamento e outros equipamentos destinados às indústrias alimentícia, química, farmacêutica, cosmética, de mineração, de fertilizantes e de outros setores produtivos. A empresa também desenvolve projetos personalizados, presta assistência técnica, manutenção e suporte aos seus clientes.

A Maqna Misturadores atua com foco em inovação, qualidade, tecnologia, eficiência operacional, segurança e atendimento especializado, desenvolvendo equipamentos que contribuem para a produtividade, a padronização dos processos industriais e a competitividade de seus clientes.'),
(57, 'Fundada em 12/11/2007 e com razão social Stampo Metalurgica LTDA, está localizada na cidade Goianira do estado Goiás. Sua atividade principal, conforme a Receita Federal, é 25.32-2-01 - Produção de artefatos estampados de metal,fabricação de máquinas para agricultura e fabricação de máquinas e equipamentos para a indústria da madeira'),
(58, 'A Eletro Quadros Metalúrgica Ltda atua no segmento metalúrgico, especializada na fabricação de artefatos metálicos, estruturas metálicas e equipamentos destinados a aplicações industriais. A empresa desenvolve soluções voltadas à produção de componentes metálicos e equipamentos sob medida, atendendo às necessidades de diferentes setores produtivos com foco em qualidade, resistência e eficiência operacional. Sua atividade principal é a produção de artefatos estampados de metal.

Entre suas principais atividades estão a fabricação de artefatos estampados de metal, estruturas metálicas para uso industrial e construtivo, peças e componentes metálicos, máquinas e equipamentos para aplicações específicas, além da montagem de estruturas e fornecimento de soluções industriais personalizadas. A empresa atua com foco em inovação, precisão técnica, qualidade dos processos produtivos e atendimento às demandas do setor industrial.'),
(59, 'D & R Indústria de Produtos de Limpeza Ltda é uma empresa de Goianira (GO) especializada na fabricação de sabões, detergentes sintéticos e produtos de limpeza destinados aos mercados doméstico e institucional.

A companhia também produz desinfetantes e aditivos industriais, além de atuar na distribuição atacadista de produtos de higiene e conservação, oferecendo soluções para limpeza e manutenção em diversos segmentos.'),
(60, 'A JR. Fox Tendas Ltda atua no segmento de fabricação e comercialização de estruturas para eventos e coberturas, especializada no desenvolvimento de tendas, galpões, coberturas e estruturas metálicas para aplicações temporárias e permanentes. A empresa atende clientes dos setores de eventos, agronegócio, indústria, comércio e construção civil, oferecendo soluções que aliam praticidade, resistência e versatilidade.
Entre suas principais atividades estão a fabricação, venda, locação, montagem e manutenção de tendas, galpões lonados, coberturas, estruturas metálicas e acessórios, além do desenvolvimento de projetos personalizados para eventos, armazenagem, feiras, exposições e instalações industriais. A empresa atua com foco em qualidade dos materiais, segurança estrutural, inovação, agilidade na execução e atendimento às necessidades específicas de seus clientes e parceiros comerciais.'),
(61, 'A Asa do Brasil é uma empresa brasileira especializada na fabricação de suplementos minerais, núcleos nutricionais e soluções para nutrição animal.

A companhia atende principalmente os setores de pecuária de corte e leite, oferecendo produtos voltados à suplementação e ao aumento da produtividade dos rebanhos. Seu foco está em desenvolver tecnologias e soluções nutricionais que contribuam para o desempenho e a saúde animal.

Com atuação no agronegócio, a Asa do Brasil se destaca pelo suporte técnico aos produtores rurais e pela oferta de produtos destinados à eficiência da produção pecuária.'),
(62, 'A Imprensa Bíblica Cristã Ltda atua no segmento editorial e gráfico, especializada na produção, publicação, impressão e comercialização de materiais religiosos, educacionais e de conteúdo cristão. A empresa desenvolve produtos voltados à divulgação de ensinamentos bíblicos, formação espiritual e apoio às atividades de igrejas, instituições religiosas e leitores em geral.

Entre suas principais atividades estão a edição e publicação de livros, bíblias, revistas, estudos, materiais didáticos, devocionais e demais conteúdos impressos ou digitais de temática cristã, além da impressão, distribuição e comercialização dessas publicações. A empresa atua com foco em qualidade editorial, disseminação do conhecimento bíblico, excelência gráfica e atendimento às necessidades de instituições religiosas, educadores e leitores.'),
(63, 'A Laticínio Asahi Ltda atua no segmento de laticínios, especializada na captação, processamento, industrialização e comercialização de leite e seus derivados. A empresa atende o mercado alimentício com produtos voltados ao consumo doméstico e comercial, priorizando qualidade, segurança dos alimentos e eficiência em seus processos produtivos.

Entre suas principais atividades estão o beneficiamento de leite, fabricação de queijos, manteiga, requeijão, creme de leite, bebidas lácteas, leite pasteurizado e outros derivados, além da embalagem, distribuição e comercialização desses produtos para supermercados, atacadistas, varejistas, estabelecimentos de alimentação e distribuidores.

A Laticínio Asahi atua com foco em qualidade, boas práticas de fabricação, conformidade com as normas sanitárias, inovação, sustentabilidade e satisfação de seus clientes, contribuindo para o fortalecimento da cadeia produtiva do leite e o fornecimento de alimentos seguros e de alto padrão ao mercado.'),
(64, 'Eletrometa (Danfer Metalúrgica Ltda) é uma empresa de Goianira (GO) especializada na produção de artefatos estampados de metal, atendendo demandas dos setores industrial, elétrico e da construção civil.

Além da atividade metalúrgica, a companhia atua no comércio atacadista e varejista de materiais elétricos, oferecendo produtos e soluções voltadas para instalações elétricas e aplicações industriais.'),
(65, 'A José Alves & Magaine Ltda – Tecnox atua no segmento metalúrgico e industrial, especializada na fabricação, montagem e comercialização de equipamentos, estruturas e produtos metálicos destinados aos setores industrial, agropecuário, comercial e da construção civil. A empresa desenvolve soluções voltadas à produtividade, resistência e eficiência operacional, atendendo às necessidades específicas de seus clientes.

Entre suas principais atividades estão a fabricação de estruturas metálicas, equipamentos industriais, peças e componentes sob medida, serviços de corte, dobra, soldagem, usinagem e montagem, além da comercialização de produtos metalúrgicos e prestação de suporte técnico. A empresa também pode atuar no desenvolvimento de projetos personalizados para diferentes aplicações industriais.

A Tecnox atua com foco em qualidade dos materiais, inovação, precisão nos processos produtivos, segurança, cumprimento de prazos e atendimento especializado, oferecendo soluções que contribuem para o desempenho e o crescimento das operações de seus clientes e parceiros.'),
(66, 'A Manos Química EIRELI atua no segmento da indústria química, especializada no desenvolvimento, fabricação e comercialização de produtos químicos destinados a aplicações industriais, institucionais e comerciais. A empresa oferece soluções voltadas à eficiência dos processos produtivos, limpeza, tratamento e manutenção, atendendo às necessidades de diversos setores da economia.

Entre suas principais atividades estão a produção e comercialização de produtos químicos, saneantes, detergentes, desengraxantes, desinfetantes, produtos para tratamento de água, limpeza industrial e institucional, além de formulações específicas para diferentes aplicações. A empresa também pode prestar suporte técnico e desenvolver soluções personalizadas conforme as necessidades de seus clientes.

A Manos Química atua com foco em qualidade, inovação, segurança, conformidade com as normas ambientais e sanitárias, eficiência operacional e atendimento especializado, buscando fornecer produtos confiáveis que contribuam para o desempenho e a sustentabilidade das operações de seus clientes.'),
(67, 'A Centro Sul Indústria e Comércio de Portas e Janelas Ltda é uma empresa especializada na fabricação e comercialização de portas, janelas e esquadrias para a construção civil.

A companhia atende obras residenciais, comerciais e industriais, oferecendo produtos voltados à segurança, funcionalidade e acabamento de edificações. Seu foco está na produção de soluções que agregam qualidade, durabilidade e eficiência aos projetos construtivos.

Com atuação no setor de materiais para construção, a empresa contribui para o fornecimento de componentes essenciais para obras e reformas.'),
(68, 'A Brasmom Indústria Metalúrgica Ltda é uma empresa especializada na fabricação de estruturas metálicas, peças industriais e serviços de metalurgia, atendendo os setores industrial, agrícola e da construção civil.

A companhia atua no desenvolvimento, montagem e manutenção de equipamentos e estruturas metálicas, oferecendo soluções sob medida para diferentes projetos. Seu foco está na qualidade, resistência e eficiência dos produtos e serviços fornecidos.

Com experiência no segmento metalúrgico, a Brasmom contribui para a execução de obras e processos industriais por meio de soluções em aço e metalurgia.'),
(71, 'A Ferreira e Santos Indústria e Comércio de Produtos Ltda atua no segmento industrial e comercial, especializada na fabricação, beneficiamento e comercialização de produtos destinados a diferentes setores do mercado. A empresa desenvolve soluções voltadas à qualidade, eficiência produtiva e atendimento às necessidades de clientes comerciais, industriais e corporativos.

Entre suas principais atividades estão a produção, industrialização, distribuição e comercialização de produtos, além do desenvolvimento de soluções alinhadas às demandas específicas de seus clientes e mercados de atuação. A empresa atua com foco em qualidade, inovação, eficiência operacional, padronização de processos e excelência no fornecimento de produtos e serviços.'),
(72, 'Com sede em GOIANIRA, GO, possui 13 anos, 9 meses e 20 dias e foi fundada em 22/08/2012. A sua situação cadastral é ativa e sua principal atividade econômica é Fabricação de impermeabilizantes, solventes e produtos afins'),
(73, 'A Indústria Nacional de Asfaltos S/A (em Recuperação Judicial) atua no segmento de infraestrutura e pavimentação, especializada na produção, industrialização e comercialização de produtos asfálticos destinados à construção, manutenção e recuperação de rodovias, vias urbanas, aeroportos e obras de infraestrutura. A empresa desenvolve soluções voltadas à mobilidade, durabilidade dos pavimentos e desenvolvimento da infraestrutura de transportes.

Entre suas principais atividades estão a fabricação e distribuição de cimento asfáltico de petróleo (CAP), emulsões asfálticas, asfaltos modificados, ligantes especiais e outros insumos utilizados em obras de pavimentação e impermeabilização, além do suporte técnico para aplicação de seus produtos. A empresa atende construtoras, concessionárias, órgãos públicos e empresas de engenharia em diferentes regiões do país.

Mesmo em processo de recuperação judicial, a empresa mantém atuação voltada à qualidade dos produtos, eficiência operacional, atendimento ao mercado de infraestrutura e desenvolvimento de soluções para o setor rodoviário e de obras públicas.'),
(76, 'A Goiás Indústria de Pré-Moldados Ltda – ME atua no segmento da construção civil, especializada na fabricação e comercialização de estruturas e artefatos pré-moldados de concreto para obras residenciais, comerciais, industriais e de infraestrutura. A empresa desenvolve soluções construtivas que proporcionam maior agilidade na execução de projetos, resistência estrutural e eficiência operacional.

Entre suas principais atividades estão a produção de vigas, pilares, lajes, painéis, blocos, tubos, meios-fios e demais peças pré-moldadas de concreto, além do fornecimento e suporte técnico para obras de diferentes portes. A empresa atua com foco em qualidade dos produtos, padronização de processos, durabilidade, inovação e atendimento às necessidades do mercado da construção civil e infraestrutura.'),
(79, 'A Major Nutrição Animal Ltda atua no segmento de nutrição animal, especializada no desenvolvimento, fabricação e comercialização de produtos destinados à alimentação e suplementação de animais de produção. A empresa oferece soluções voltadas ao aumento da produtividade, desempenho, saúde e bem-estar animal, atendendo às necessidades do setor agropecuário.

Entre suas principais atividades estão a fabricação de rações, suplementos minerais, núcleos nutricionais, premixes, aditivos e concentrados para bovinos, suínos, aves e outras espécies, além da prestação de assistência técnica e orientação nutricional aos produtores rurais. A empresa desenvolve produtos formulados para atender diferentes fases de crescimento, reprodução e produção animal.

A Major Nutrição Animal atua com foco em qualidade, inovação, pesquisa, eficiência produtiva, sustentabilidade e excelência no atendimento, contribuindo para o fortalecimento da pecuária e para a melhoria dos resultados dos produtores e parceiros comerciais.'),
(81, 'A Galvafer Ltda atua no segmento metalúrgico, especializada na fabricação, beneficiamento e comercialização de produtos metálicos destinados aos setores industrial, agrícola, da construção civil e de infraestrutura. A empresa desenvolve soluções voltadas à resistência, durabilidade e eficiência operacional, atendendo às necessidades de diferentes segmentos do mercado.

Entre suas principais atividades estão a fabricação de estruturas metálicas, peças e componentes em aço, serviços de corte, dobra, soldagem e tratamento de superfícies metálicas, além da comercialização e distribuição de produtos metalúrgicos. A empresa atua com foco em qualidade dos processos produtivos, inovação, precisão técnica, segurança e excelência no atendimento aos seus clientes e parceiros comerciais.'),
(86, 'A Goiânia Postes e Torres para Telecomunicação Ltda atua no segmento de infraestrutura para telecomunicações e construção metálica, especializada na fabricação, montagem e comercialização de postes, torres e estruturas destinadas aos setores de telecomunicações, energia e transmissão de dados. A empresa desenvolve soluções voltadas à segurança, resistência estrutural e confiabilidade operacional.

Entre suas principais atividades estão a fabricação de torres metálicas, postes para telecomunicações, estruturas para antenas, suportes metálicos, sistemas de sustentação para redes de comunicação e energia, além da montagem, instalação e manutenção dessas estruturas. A empresa atua com foco em qualidade dos materiais, engenharia especializada, conformidade técnica, inovação e atendimento às necessidades de projetos de infraestrutura e conectividade.'),
(89, 'Costa & Andrade Cerâmica e Premoldados Ltda foi uma empresa de Orizona (GO) especializada na fabricação de produtos cerâmicos e artefatos de cimento para a construção civil, atendendo obras residenciais, comerciais e de infraestrutura.

Além da produção de materiais para construção, a empresa também atuava no comércio varejista de materiais de construção. Atualmente, a companhia encontra-se com situação cadastral baixada por encerramento voluntário de suas atividades.'),
(91, 'Sua atividade principal, conforme a Receita Federal, é 10.66-0-00 - Fabricação de alimentos para animais, aluguel e leasing operacional de máquinas e equipamentos agrícolas sem operador, comércio varejista de medicamentos para uso veterinário, inclusive vacinas, fundada em 15/05/2007,  Sua situação cadastral até o momento é ativa'),
(92, 'Serralheria Medeiros (Clodovil Martins Medeiros e Cia Ltda) é uma empresa de Porangatu (GO) especializada na fabricação de artigos de serralheria, estruturas metálicas, esquadrias e serviços de solda e usinagem.

A companhia também atua na produção de estruturas pré-moldadas de concreto, ferramentas e equipamentos para os setores agrícola, pecuário e da construção civil, oferecendo soluções industriais e metalúrgicas para diversos segmentos.'),
(94, 'A Cerâmica Honda Ltda é uma empresa especializada na fabricação de produtos cerâmicos para a construção civil, produzindo materiais como tijolos, blocos e outros artefatos utilizados em obras residenciais, comerciais e industriais.

A companhia atende construtoras, revendedores de materiais de construção e clientes finais, oferecendo produtos com foco em qualidade, resistência e eficiência construtiva.

Com atuação no setor cerâmico, a empresa contribui para o desenvolvimento da construção civil por meio do fornecimento de materiais essenciais para obras e projetos de infraestrutura.'),
(95, 'CVM Ind. de Madeiras Ltda foi uma empresa de Inhumas (GO) especializada na fabricação de esquadrias, peças de madeira e produtos derivados para instalações industriais, comerciais e construção civil.

A companhia também atuava no beneficiamento de madeira, produção de chapas e laminados, além do comércio atacadista e varejista de madeira e materiais de construção.'),
(98, 'A Laticínio Leite Vida Ltda atua no segmento de laticínios, especializada na captação, processamento, industrialização e comercialização de leite e derivados, atendendo aos mercados varejista, atacadista e institucional. A empresa desenvolve produtos que aliam qualidade, segurança alimentar e valor nutricional, contribuindo para o abastecimento da cadeia alimentícia.

Entre suas principais atividades estão o beneficiamento de leite, fabricação de queijos, manteiga, requeijão, creme de leite, bebidas lácteas, leite pasteurizado, leite UHT e outros derivados, além da embalagem, distribuição e comercialização de seus produtos. A empresa atende supermercados, distribuidores, estabelecimentos de alimentação e consumidores, seguindo rigorosos padrões de qualidade e controle sanitário.

A Laticínio Leite Vida atua com foco em qualidade, inovação, boas práticas de fabricação, sustentabilidade, eficiência operacional e satisfação de seus clientes, buscando oferecer produtos que atendam às exigências do mercado e promovam o fortalecimento da cadeia produtiva do leite.'),
(104, 'A Ferro Norte Indústria e Comércio de Ferragens Ltda atua no segmento metalúrgico e de materiais para construção, especializada na fabricação, beneficiamento e comercialização de ferragens e produtos metálicos destinados aos setores da construção civil, indústria e infraestrutura. A empresa desenvolve soluções voltadas à qualidade, resistência e eficiência, atendendo às necessidades de diferentes segmentos do mercado.

Entre suas principais atividades estão a fabricação e comercialização de ferragens, vergalhões, telas, arames, estruturas metálicas, acessórios para construção civil e outros produtos em aço e metal, além do beneficiamento e distribuição desses materiais. A empresa atua com foco em qualidade dos produtos, eficiência operacional, atendimento especializado e suporte às demandas de seus clientes e parceiros comerciais.'),
(106, 'D+ Alimentos Ltda é uma empresa de Luziânia (GO) especializada na produção de amidos, féculas vegetais, farinha de milho e derivados, fornecendo insumos para a indústria alimentícia e outros segmentos produtivos.

A companhia atua no processamento de matérias-primas agrícolas, contribuindo para a cadeia de alimentos por meio da fabricação de ingredientes utilizados em diversos produtos industrializados, com foco em qualidade e eficiência produtiva.'),
(107, 'A Brilhax PGTU é uma empresa especializada em limpeza, conservação e manutenção de ambientes, oferecendo soluções para empresas, indústrias, condomínios e estabelecimentos comerciais.

A companhia atua com serviços de higienização, tratamento de pisos, limpeza técnica e suporte operacional, buscando garantir ambientes mais organizados, seguros e adequados às necessidades dos clientes.

Com foco em qualidade e eficiência, a Brilhax PGTU atende diferentes segmentos, contribuindo para a conservação e valorização de espaços corporativos e industriais.'),
(110, 'A Five Participações e Investimentos Ltda atua no segmento de participações societárias e investimentos empresariais, especializada na administração de ativos, gestão de participações em empresas e desenvolvimento de estratégias voltadas à valorização patrimonial e expansão de negócios. Dependendo de sua estrutura societária, a empresa pode atuar como holding de investimentos, concentrando a gestão de participações em diferentes empreendimentos e setores econômicos.

Entre suas principais atividades estão a administração de participações societárias, gestão de investimentos, planejamento patrimonial, aquisição e administração de ativos, suporte à governança corporativa e desenvolvimento de estratégias empresariais voltadas à geração de valor e crescimento sustentável dos negócios. A empresa atua com foco em eficiência administrativa, segurança patrimonial, gestão estratégica e fortalecimento de seus investimentos e operações.'),
(111, 'A J B Lajes PGTU Ltda atua no segmento da construção civil, especializada na fabricação e comercialização de lajes e artefatos pré-moldados de concreto destinados a obras residenciais, comerciais, industriais e de infraestrutura. A empresa desenvolve soluções construtivas que proporcionam agilidade na execução das obras, resistência estrutural e otimização de custos.

Entre suas principais atividades estão a produção de lajes pré-moldadas, vigotas, treliças, painéis e outros elementos estruturais de concreto, além do fornecimento de materiais e suporte técnico para projetos de construção. A empresa atende construtoras, empreiteiras, profissionais da construção civil e consumidores finais.

A empresa atua com foco em qualidade dos produtos, conformidade técnica, durabilidade, eficiência produtiva, segurança estrutural e atendimento às necessidades específicas de seus clientes e parceiros comerciais.'),
(112, 'A Goiás Torneadora e Transportes Ltda atua nos segmentos de serviços mecânicos, usinagem e transporte, especializada na fabricação e recuperação de peças por meio de tornearia, manutenção de equipamentos e prestação de serviços de transporte de cargas. A empresa oferece soluções voltadas ao atendimento das demandas dos setores industrial, agrícola, automotivo e de logística.

Entre suas principais atividades estão os serviços de tornearia, usinagem, soldagem, fabricação e recuperação de componentes mecânicos, manutenção de máquinas e equipamentos, além do transporte rodoviário de cargas e apoio logístico. A empresa atua com foco em qualidade técnica, eficiência operacional, confiabilidade, cumprimento de prazos e atendimento às necessidades específicas de seus clientes.'),
(113, 'Coopermel (Cooperativa dos Apicultores e Meliponicultores da Agricultura Familiar de Goiás) é uma cooperativa goiana voltada à produção, beneficiamento e comercialização de mel, própolis e outros produtos apícolas. A organização reúne produtores da agricultura familiar, promovendo o fortalecimento da apicultura e da meliponicultura no estado.

A cooperativa atua no apoio técnico e comercial aos seus cooperados, buscando agregar valor à produção, ampliar o acesso a mercados e incentivar práticas sustentáveis. Seu trabalho contribui para a geração de renda no meio rural e para o desenvolvimento da cadeia produtiva do mel em Goiás.'),
(115, 'A E.M. da Silva Serviços Ltda – ME (Emar Torneadora e Solda) atua no segmento de serviços mecânicos e industriais, especializada em manutenção, reparação, usinagem, tornearia e soldagem para veículos, máquinas e equipamentos. A empresa oferece soluções voltadas à recuperação, fabricação e adaptação de componentes mecânicos, atendendo os setores automotivo, industrial e de transporte.

Entre suas principais atividades estão os serviços de tornearia, usinagem, soldagem, manutenção mecânica e elétrica de veículos, alinhamento e balanceamento, fabricação de peças metálicas, manutenção de equipamentos industriais e comercialização de peças, acessórios e insumos automotivos. A empresa atua com foco em qualidade técnica, eficiência operacional, confiabilidade e atendimento às necessidades específicas de seus clientes. ([CNPJ.biz][1])'),
(116, 'A Lajes Plann Ltda atua no segmento da construção civil, especializada na fabricação e comercialização de lajes e artefatos pré-moldados de concreto destinados a obras residenciais, comerciais, industriais e de infraestrutura. A empresa desenvolve soluções construtivas que proporcionam maior rapidez na execução das obras, resistência estrutural e eficiência na utilização dos materiais.

Entre suas principais atividades estão a produção de lajes pré-moldadas, vigotas treliçadas, painéis, blocos de enchimento, pilares, vigas e outros elementos estruturais de concreto, além do fornecimento de materiais e suporte técnico para projetos de construção. A empresa atende construtoras, empreiteiras, profissionais da construção civil e consumidores finais.

A Lajes Plann atua com foco em qualidade, conformidade técnica, durabilidade, segurança estrutural, eficiência produtiva e atendimento especializado, oferecendo soluções que contribuem para o desenvolvimento de obras com maior agilidade, confiabilidade e desempenho.'),
(117, 'A Ferraço Comércio e Indústria de Ferro e Aço Ltda atua no segmento metalúrgico e siderúrgico, especializada na comercialização, beneficiamento e industrialização de produtos de ferro e aço destinados aos setores da construção civil, indústria, agronegócio e infraestrutura. A empresa desenvolve soluções voltadas ao fornecimento de materiais metálicos com qualidade, resistência e eficiência para diferentes aplicações.

Entre suas principais atividades estão a comercialização de chapas, perfis, tubos, barras, vigas e demais produtos siderúrgicos, além do corte, dobra, beneficiamento e distribuição de materiais em ferro e aço. A empresa atua com foco em qualidade dos produtos, agilidade logística, atendimento especializado e suporte às necessidades de seus clientes e parceiros comerciais.'),
(122, 'A Charque Duty Indústria e Comércio de Charque e Derivados de Carne Ltda é uma empresa especializada na produção e comercialização de charque, carnes processadas e derivados cárneos.

A companhia atua no processamento, conservação e distribuição de produtos alimentícios de origem bovina, atendendo mercados, distribuidores, atacadistas e estabelecimentos do setor alimentício.

Com foco em qualidade, segurança alimentar e eficiência produtiva, a empresa contribui para a cadeia de alimentos por meio do fornecimento de produtos cárneos destinados ao mercado regional e nacional.'),
(123, 'A Eco Projeto Ltda atua no segmento de gestão ambiental e tratamento de resíduos, especializada na coleta, processamento, recuperação e destinação adequada de resíduos industriais e urbanos. A empresa desenvolve soluções voltadas à sustentabilidade, ao reaproveitamento de materiais e à redução dos impactos ambientais, atendendo às necessidades de empresas, indústrias e órgãos públicos. Sua atividade principal está relacionada ao tratamento e disposição de resíduos não perigosos, além de atuar em atividades complementares de coleta, recuperação e comercialização de materiais recicláveis. 

Entre suas principais atividades estão a coleta de resíduos não perigosos e perigosos, operação de sistemas de tratamento e disposição de resíduos, recuperação e reciclagem de materiais, comercialização de sucatas e recicláveis, descontaminação ambiental, além da fabricação, manutenção e fornecimento de equipamentos utilizados em processos de gestão de resíduos e saneamento ambiental. A empresa atua com foco em sustentabilidade, eficiência operacional, responsabilidade ambiental e conformidade com as normas do setor.'),
(125, 'A Ecopetro Soluções Ambientais Ltda atua no segmento de gestão ambiental, especializada na coleta, transporte, tratamento e destinação de resíduos sólidos e líquidos provenientes de atividades industriais, comerciais e automotivas. A empresa desenvolve soluções voltadas à conformidade ambiental, sustentabilidade e gerenciamento adequado de resíduos, atendendo diversos setores produtivos com segurança e responsabilidade ambiental.

Entre suas principais atividades estão a coleta de resíduos perigosos e não perigosos, tratamento de efluentes, gerenciamento e armazenamento de resíduos, transporte especializado, limpeza de caixas separadoras de água e óleo, hidrojateamento, processamento de lâmpadas, desmontagem e remoção de tanques, triagem de materiais recicláveis, consultoria técnica ambiental e destinação final ambientalmente adequada de resíduos. A empresa atua com foco em sustentabilidade, conformidade legal, eficiência operacional e proteção ao meio ambiente.'),
(133, 'A Bio Projetos é uma empresa especializada em consultoria ambiental, licenciamento e gestão de projetos sustentáveis, atendendo empresas de diversos segmentos.

A companhia atua na elaboração de estudos ambientais, processos de licenciamento, monitoramento e regularização junto aos órgãos competentes, auxiliando seus clientes no cumprimento da legislação ambiental.

Com foco em sustentabilidade e responsabilidade socioambiental, a Bio Projetos oferece soluções técnicas que contribuem para o desenvolvimento de empreendimentos de forma segura e ambientalmente adequada.'),
(136, 'A empresa Sol Industria e Comercio de Colchoes e Estofados LTDA de CNPJ 41.766.058/0001-28, foi fundada em 30/04/2021 na cidade Rubiataba no estado Goiás. Sua atividade principal, conforme a Receita Federal, é 31.04-7-00 - Fabricação de colchões. Sua situação cadastral até o momento é Ativa.'),
(150, 'A Indústria Goiana de Containers atua no segmento metalúrgico e de construção modular, especializada na fabricação, adaptação e comercialização de containers e estruturas metálicas destinadas a aplicações industriais, comerciais, logísticas e habitacionais. A empresa desenvolve soluções versáteis que atendem às necessidades de armazenamento, transporte e implantação de espaços modulares.

Entre suas principais atividades estão a fabricação e customização de containers, produção de módulos habitacionais, escritórios, alojamentos, guaritas, depósitos, unidades comerciais e estruturas metálicas sob medida, além da manutenção e adaptação de containers para diferentes finalidades. A empresa atua com foco em qualidade, durabilidade, inovação, sustentabilidade, eficiência construtiva e atendimento às demandas específicas de seus clientes e parceiros.'),
(151, 'A LM Construtora atua no segmento da construção civil, especializada na execução de obras residenciais, comerciais, industriais e de infraestrutura. A empresa desenvolve soluções construtivas voltadas à qualidade, segurança, eficiência e cumprimento de prazos, atendendo clientes públicos e privados em diferentes tipos de empreendimentos.

Entre suas principais atividades estão a construção e reforma de edificações, execução de obras de infraestrutura, terraplenagem, pavimentação, fundações, instalações prediais, gerenciamento e fiscalização de obras, além da elaboração e execução de projetos de engenharia. A empresa também pode prestar serviços de manutenção civil e desenvolvimento de soluções construtivas personalizadas.

A LM Construtora atua com foco em qualidade técnica, inovação, sustentabilidade, eficiência operacional, segurança no trabalho e satisfação de seus clientes, contribuindo para o desenvolvimento de empreendimentos que atendem aos padrões de desempenho e às exigências da construção civil.'),
(152, 'A Goianésia Temper Comércio Varejista de Vidros e Representações Ltda atua no segmento vidreiro e da construção civil, especializada na comercialização, beneficiamento e distribuição de vidros para aplicações residenciais, comerciais e industriais. A empresa oferece soluções voltadas ao acabamento, segurança, funcionalidade e valorização de ambientes e projetos arquitetônicos.

Entre suas principais atividades estão a venda de vidros temperados, laminados, comuns e espelhos, além da fabricação sob medida, instalação, representação comercial de produtos do setor vidreiro e fornecimento de soluções para esquadrias, fachadas, divisórias, boxes, portas e projetos especiais. A empresa atua com foco em qualidade dos materiais, precisão nos acabamentos, atendimento especializado, inovação e satisfação de seus clientes e parceiros comerciais.'),
(153, 'A AGT Log (Agromil Transportes Indústria e Comércio de Nutrição Animal e Fertilizantes Ltda.) é uma empresa goiana fundada em 2002, especializada em logística e transporte rodoviário de cargas. Com sede em Uruaçu (GO), atua no transporte intermunicipal, interestadual e nacional, atendendo diferentes segmentos do mercado.

A empresa iniciou suas atividades no setor de nutrição animal e, ao longo do tempo, expandiu sua atuação para a logística, investindo em frota, estrutura operacional e gestão de transporte. Hoje, destaca-se pelo foco em segurança, agilidade e eficiência no transporte de cargas.'),
(154, 'A Giacomelli e De Paula Indústria e Comércio de Embalagens Ltda atua no segmento de embalagens, especializada na fabricação, industrialização e comercialização de soluções para acondicionamento, armazenamento e transporte de produtos destinados a diversos setores da economia. A empresa desenvolve embalagens voltadas à proteção, praticidade e eficiência logística, atendendo clientes dos segmentos industrial, comercial, alimentício e agroindustrial.

Entre suas principais atividades estão a produção de embalagens plásticas, flexíveis, industriais ou personalizadas, além da comercialização e distribuição de materiais para acondicionamento e transporte de mercadorias. A empresa atua com foco em qualidade, inovação, eficiência produtiva, sustentabilidade e desenvolvimento de soluções que atendam às necessidades específicas de seus clientes e mercados de atuação.'),
(155, 'Empresa brasileira fundada em 30/06/1994. Desde então  sua principal atividade econômica, registrada como 4520001 - Serviços de manutenção e reparação mecânica de veículos automotores. Essa atividade representa o foco principal de sua atuação, sendo o pilar que sustenta seus produtos, serviços e soluções entregues ao mercado.'),
(156, 'A GRECG Indústria e Comércio de Bicicletas Ltda atua no segmento de mobilidade e bens de consumo, especializada na fabricação, montagem, comercialização e distribuição de bicicletas e acessórios relacionados. A empresa desenvolve soluções voltadas ao transporte, lazer, esporte e mobilidade sustentável, atendendo consumidores, lojistas e distribuidores em diferentes regiões do país.

Entre suas principais atividades estão a fabricação e montagem de bicicletas para uso urbano, recreativo e esportivo, além da comercialização de peças, componentes, acessórios e equipamentos relacionados ao ciclismo. A empresa atua com foco em qualidade dos produtos, inovação, segurança, durabilidade e atendimento às necessidades de seus clientes e parceiros comerciais.'),
(158, 'A Rodocon Construções Rodoviárias é uma empresa familiar brasileira, privada, que atua há mais de 60 anos em âmbito nacional, nos segmentos de construção, manutenção e restauração de rodovias; de conservação de áreas verdes, e de coleta, transporte e tratamento de resíduos'),
(161, 'A Cerâmica Goianésia Ltda é uma empresa especializada na fabricação de produtos cerâmicos para a construção civil, atuando na produção de tijolos, blocos e outros materiais utilizados em obras residenciais, comerciais e industriais.

A companhia atende construtoras, revendas de materiais de construção e consumidores finais, oferecendo produtos voltados à qualidade, resistência e eficiência construtiva.

Com atuação consolidada no setor cerâmico, a empresa contribui para o desenvolvimento da construção civil por meio do fornecimento de materiais essenciais para obras e infraestrutura.'),
(164, 'A Anhanguera Indústria e Comércio de Cabos Ltda (ME) é uma empresa goiana especializada na fabricação de cabos, fios e componentes para instalações elétricas e industriais.

Localizada em Goiás, a companhia atua no fornecimento de soluções para os setores de construção civil, energia e indústria, oferecendo produtos voltados à condução e distribuição de energia elétrica.

Seu foco está na produção de materiais elétricos com qualidade e segurança, atendendo demandas de empresas, distribuidores e projetos de infraestrutura.'),
(165, 'A L J Pré-Mold e Materiais de Construção Ltda atua no segmento da construção civil, especializada na fabricação e comercialização de artefatos pré-moldados de concreto e no fornecimento de materiais de construção para obras residenciais, comerciais, industriais e de infraestrutura. A empresa oferece soluções que contribuem para a agilidade, qualidade e eficiência na execução de projetos construtivos.

Entre suas principais atividades estão a produção de lajes, vigotas, blocos, mourões, meios-fios, tubos, pilares e outros pré-moldados de concreto, além da comercialização de cimento, areia, brita, ferragens, argamassas e demais materiais utilizados na construção civil. A empresa atende construtoras, empreiteiras, profissionais da construção e consumidores em geral.

A L J Pré-Mold e Materiais de Construção atua com foco em qualidade dos produtos, resistência, conformidade técnica, eficiência logística, atendimento especializado e compromisso com as necessidades de seus clientes e parceiros comerciais.'),
(166, 'A Auto Socorro Lago Azul Ltda é uma empresa especializada em serviços de guincho, reboque e assistência veicular, atendendo veículos leves e pesados.

A companhia atua no suporte a motoristas em situações de pane, acidentes e transporte de veículos, oferecendo soluções de remoção e socorro rodoviário. Seu foco está na agilidade, segurança e atendimento para clientes particulares, empresas e frotas.'),
(167, 'A empresa com a razão social Transportadora do Vale Ltda, tem o nome fantasia Do Valle, opera com o CNPJ 01.329.621/0001-86 (01329621000186) e foi fundada em 24/07/1996. O endereço de sua sede está localizada na Avenida Perimetral Norte, 2869 - Fazenda Caveiras, Goiania - GO, 74.445-360. Sua atividade principal é de Transporte rodoviário de carga, exceto produtos perigosos e mudanças, intermunicipal, interestadual e internacional, de acordo com o código CNAE H-4930-2/02.'),
(168, 'A Bruno Francisco de Oliveira ME é uma empresa brasileira que atua no segmento de comércio e prestação de serviços, atendendo clientes da região de Goiás.

A companhia desenvolve atividades voltadas ao atendimento de demandas empresariais e comerciais, buscando oferecer soluções com agilidade e qualidade. Seu foco está na prestação de serviços especializados e no suporte às necessidades de seus clientes.

Com atuação regional, a empresa contribui para o desenvolvimento econômico local por meio de suas operações comerciais e de serviços.'),
(169, 'Fundada em 03/04/2014 e com razão social Sc Moveis e Eletrodomesticos Goianesia LTDA, está localizada na cidade Goianésia do estado Goiás. Sua atividade principal, conforme a Receita Federal, é 47.54-7-01 - Comércio varejista de móveis. Sua situação cadastral até o momento é Ativa'),
(171, 'Registrada sob o CNPJ 08.730.313/0001-07 e razão social SORVETES BEIJO MIX LTDA, foi fundada em 28/03/2007. Está sediada na cidade de URUACU, no estado de GO , atuando principalmente no segmento de Fabricação de sorvetes e outros gelados comestíveis, de acordo com o código CNAE 1053800 registrado na Receita Federal.'),
(172, 'A Ângelo & Ângela Agropecuária e Transportes Ltda é uma empresa goiana que atua nos setores de agropecuária e transporte de cargas, oferecendo suporte às atividades do agronegócio.

A companhia desenvolve operações ligadas à produção rural, criação de animais e logística, contribuindo para o escoamento de produtos agrícolas e pecuários. Seu foco está em integrar atividades do campo com soluções de transporte, atendendo às demandas do setor agropecuário.'),
(173, 'ATTOS ETIQUETA (razão social H.A.R.D Indústria e Comércio de Etiquetas Ltda) é uma empresa especializada na fabricação e personalização de etiquetas, rótulos e adesivos técnicos. A companhia desenvolve soluções de identificação e comunicação visual sob medida para diversos setores do mercado.'),
(174, 'A empresa Rw Negocios Imobiliarios LTDA de CNPJ 37.884.713/0001-75, foi fundada em 28/07/2020 na cidade Goiânia no estado Goiás. Sua atividade principal, conforme a Receita Federal, é 68.21-8-01 - Corretagem na compra e venda e avaliação de imóveis. Sua situação cadastral até o momento é Ativa'),
(176, 'JR INDUSTRIA COMERCIO E SERVICOS LTDA - ME JR INDUSTRIA COMERCIO E SERVIOS é 10.624.467/0001-66. Com sede em APARECIDA DE GOIANIA, GO, possui 17 anos, 4 meses e 22 dias e foi fundada em 21/01/2009. A sua situação cadastral é INAPTA e sua principal atividade econômica é Fabricação de esquadrias de metal.'),
(177, 'A Flex Indústria e Comércio de Revestimentos Ltda – EPP atua no segmento industrial de revestimentos, especializada na fabricação, beneficiamento e comercialização de materiais destinados ao acabamento e à proteção de superfícies em obras residenciais, comerciais e industriais. A empresa desenvolve soluções voltadas à durabilidade, estética e desempenho técnico, atendendo às necessidades do mercado da construção civil e de aplicações industriais.

Entre suas principais atividades estão a produção e comercialização de revestimentos, acabamentos, materiais para proteção de superfícies e produtos destinados à construção civil, além do fornecimento de soluções técnicas para projetos de diferentes portes. A empresa atua com foco em qualidade, inovação, eficiência produtiva, padronização de processos e satisfação de seus clientes e parceiros comerciais.'),
(178, 'A Hidráulica Brasil Ltda atua no segmento de sistemas hidráulicos e equipamentos industriais, especializada na fabricação, manutenção, comercialização e assistência técnica de componentes e soluções hidráulicas utilizadas em máquinas e equipamentos dos setores industrial, agrícola, rodoviário e de construção civil.

Entre suas principais atividades estão a fabricação e recuperação de cilindros hidráulicos, bombas hidráulicas, comandos, mangueiras, conexões e componentes para sistemas de transmissão de força, além da manutenção de equipamentos hidráulicos, prestação de assistência técnica e fornecimento de peças e acessórios. A empresa atua com foco em qualidade técnica, confiabilidade, segurança operacional, agilidade no atendimento e desenvolvimento de soluções que contribuam para o desempenho e a produtividade de seus clientes.'),
(179, 'A Indústria e Comércio Centro Frios – EIRELI ME atua no segmento alimentício, especializada na industrialização, comercialização e distribuição de produtos refrigerados e congelados destinados ao consumo humano. A empresa atende estabelecimentos comerciais, distribuidores, supermercados, restaurantes e consumidores, oferecendo soluções voltadas à qualidade, conservação e segurança alimentar.

Entre suas principais atividades estão o processamento, armazenamento, comercialização e distribuição de alimentos refrigerados e congelados, como carnes, embutidos, laticínios, frios e produtos alimentícios em geral, além de serviços de logística e conservação em cadeia de frio. A empresa atua com foco em qualidade dos produtos, controle sanitário, eficiência operacional, cumprimento das normas de segurança alimentar e satisfação de seus clientes e parceiros comerciais.'),
(180, 'A JL Indústria de Couros e Representações Comerciais Ltda atua no segmento coureiro, especializada no beneficiamento, industrialização e comercialização de couros destinados a diversos setores da economia, como calçadista, moveleiro, automotivo e de artefatos de couro. A empresa também desenvolve atividades de representação comercial, promovendo produtos e soluções para clientes e parceiros do mercado.

Entre suas principais atividades estão o processamento e acabamento de couros, comercialização de matérias-primas e produtos derivados do couro, representação de marcas e fornecedores do setor, além da intermediação de negócios e suporte comercial. A empresa atua com foco em qualidade, padronização dos processos, valorização da matéria-prima, eficiência comercial e atendimento às necessidades de seus clientes.

A JL Indústria de Couros e Representações Comerciais busca oferecer produtos e serviços que contribuam para a competitividade da cadeia coureira, mantendo compromisso com a qualidade, a confiabilidade e o desenvolvimento de parcerias comerciais duradouras.'),
(181, 'A GR Montagens Industriais Ltda atua no segmento de engenharia e serviços industriais, especializada na montagem, instalação e manutenção de estruturas, equipamentos e sistemas utilizados em processos industriais. A empresa desenvolve soluções voltadas à implantação, ampliação e modernização de unidades produtivas, atendendo diversos setores da indústria com foco em segurança, eficiência e qualidade técnica.

Entre suas principais atividades estão a montagem eletromecânica, instalação de equipamentos industriais, fabricação e montagem de estruturas metálicas, tubulações industriais, manutenção mecânica e industrial, soldagem, caldeiraria e apoio a projetos de engenharia. A empresa atua com foco em excelência operacional, cumprimento de prazos, segurança do trabalho, qualidade dos serviços e atendimento às necessidades específicas de seus clientes.'),
(183, 'A Carlos Eder Santos ME é uma empresa brasileira que atua no segmento de comércio e prestação de serviços, atendendo clientes da região de Goiás.

A companhia desenvolve atividades voltadas ao suporte operacional e comercial de empresas e consumidores, buscando oferecer soluções com qualidade, eficiência e atendimento personalizado.

Com atuação regional, a empresa contribui para o desenvolvimento econômico local por meio de suas atividades comerciais e de serviços.'),
(184, 'A Indústria e Comércio Fosforte de Nutrição Animal Ltda atua no segmento de nutrição animal, especializada na fabricação e comercialização de produtos destinados à alimentação e suplementação de animais de produção. A empresa desenvolve soluções nutricionais voltadas ao aumento da produtividade, desempenho zootécnico, saúde e bem-estar animal, atendendo principalmente os setores pecuário e agroindustrial.

Entre suas principais atividades estão a produção de suplementos minerais, núcleos nutricionais, concentrados, aditivos e produtos para alimentação animal, além da comercialização e distribuição desses insumos para produtores rurais, cooperativas e empresas do agronegócio. A empresa atua com foco em qualidade, inovação, pesquisa nutricional, eficiência produtiva e desenvolvimento de soluções que contribuam para o fortalecimento da cadeia pecuária e agropecuária.'),
(187, 'O CNPJ da empresa THIAGO SILVA CORTOPASSI LTDA - ME TOP DIGITAL é 13.701.553/0001-13. Com sede em CATALAO, GO, possui 15 anos, 1 mês e 8 dias e foi fundada em 16/05/2011. A sua situação cadastral é ATIVA e sua principal atividade econômica é Impressão de material para uso publicitário.'),
(188, 'Fundada em 17/07/2013. A sua situação cadastral encontra-se Ativo. O negócio está cadastrado na atividade econômica Comércio atacadista de móveis e artigos de colchoaria'),
(190, 'A CCL Insumos Agropecuários Ltda é uma empresa especializada na comercialização de insumos e produtos para o agronegócio, atendendo produtores rurais e empresas do setor agropecuário.

A companhia oferece soluções voltadas à agricultura e pecuária, incluindo fertilizantes, defensivos, sementes, suplementos e outros insumos essenciais para a produção rural.

Com foco em qualidade e suporte ao produtor, a CCL atua contribuindo para o aumento da produtividade e o desenvolvimento das atividades agropecuárias da região.'),
(191, 'Fundada em 31/01/2012 e com razão social Fjp Comercio LTDA em Recuperacao Judicial, está localizada na cidade Aparecida de Goiânia do estado Goiás. Sua atividade principal, conforme a Receita Federal, é 10.53-8-00 - Fabricação de sorvetes e outros gelados comestíveis. Sua situação cadastral até o momento é Ativa'),
(192, 'Fundada em 25/11/2008 e com razão social Urugelo Industria e Comercio de Gelo LTDA, está localizada na cidade Uruaçu do estado Goiás. Sua atividade principal, conforme a Receita Federal, é 10.99-6-04 - Fabricação de gelo comum apenas. Sua situação cadastral até o momento é Ativa.'),
(193, 'Empresa especializada no setor de fabricação e fornecimento de artefatos de cimento e infraestrutur tais como com o orçamentos para pisos, blocos, mourões, tubos ou projetos estruturaiscom mais de 600 itens em sua produção. Com atendimento em toda Goiânia conta com ótimas alternativas consolidadas no mercado para comparação de preços e prazos'),
(195, 'É uma empresa ativa, com sede em Bela Vista de Goiás (região metropolitana de Goiânia) e mais de 30 anos de atuação, operando principalmente com o comércio varejista e atacadista de tecidos e malhas de acordo com o código CNAE C-1330-8/00'),
(196, 'Concret Net Indústria, Comércio e Importação Ltda é uma empresa de Bela Vista de Goiás (GO) especializada na produção de concreto, argamassa e artefatos de cimento para a construção civil.

A companhia também atua na fabricação de estruturas pré-moldadas de concreto e na comercialização de materiais de construção, oferecendo soluções para obras residenciais, comerciais e industriais com foco em qualidade e eficiência construtiva.'),
(197, 'A Ecoflor Reciclagem Ltda atua no segmento de reciclagem e recuperação de materiais, especializada na coleta, triagem, processamento e comercialização de resíduos recicláveis. A empresa desenvolve soluções voltadas à sustentabilidade ambiental e ao reaproveitamento de materiais, contribuindo para a redução de impactos ambientais e para o fortalecimento da economia circular. 

Entre suas principais atividades estão a coleta de resíduos não perigosos, recuperação de materiais recicláveis, processamento de sucatas e resíduos industriais, triagem e comercialização de materiais recicláveis, além da destinação ambientalmente adequada de resíduos. A empresa atua com foco em responsabilidade ambiental, eficiência operacional, sustentabilidade e desenvolvimento de soluções para gestão e reaproveitamento de materiais.'),
(201, 'A Laticínios Bela Vista Ltda atua no segmento de laticínios, sendo uma das principais indústrias de alimentos do Brasil, especializada na captação, processamento, industrialização e comercialização de leite e derivados. A empresa é reconhecida nacionalmente por produzir os produtos da marca Piracanjuba, além de outras marcas de seu portfólio, atendendo o mercado nacional e internacional.

Entre suas principais atividades estão a produção de leite UHT, leite em pó, leite condensado, creme de leite, manteiga, queijos, bebidas lácteas, iogurtes, compostos lácteos, bebidas proteicas e outros alimentos derivados do leite, além da distribuição, importação e exportação de produtos alimentícios. A empresa abastece supermercados, atacadistas, distribuidores, estabelecimentos de alimentação e consumidores em todo o país.

A Laticínios Bela Vista atua com foco em inovação, qualidade, segurança dos alimentos, sustentabilidade, desenvolvimento da cadeia leiteira e eficiência operacional. A empresa investe continuamente em tecnologia, pesquisa e boas práticas de fabricação, contribuindo para o fortalecimento da indústria de alimentos e para a oferta de produtos que atendem aos mais elevados padrões de qualidade.'),
(206, 'A empresa Tec Solda de CNPJ 01.733.037/0001-91, fundada em 31/03/1997 e com razão social V. Carneiro Servicos de Soldas LTDA, está localizada na cidade Goianésia do estado Goiás. Sua atividade principal, conforme a Receita Federal, é 33.14-7-12 - Manutenção e reparação de tratores agrícolas, comércio varejista de equipamentos de telefonia e comunicação: telefones, reparação e manutenção de máquinas e aparelhos eletrodomésticos, Sua situação cadastral até o momento é Ativa'),
(207, 'A sua situação cadastral é ATIVA e sua principal atividade econômica é Fabricação de medicamentos alopáticos para uso humano'),
(208, 'Com sede em DIVINOPOLIS, MG, possui 11 anos, 4 meses e 23 dias e foi fundada em 23/10/2014.  ATIVA e sua principal atividade econômica é Holdings de instituições não-financeiras possui sede em Divinópolis, MG'),
(209, 'Geradores possui experiência em fabricação e instalação de Grupos Geradores e também no desenvolvimento de soluções para todos aqueles que necessitam de energia elétrica no horário de ponta e em situações de interrupção de fornecimento'),
(210, 'A Greenpharma, indústria farmacêutica fundada em 1989, iniciou suas atividades no mercado de medicamentos em 1993 e desde o início mantém como objetivos'),
(211, 'A Greenpharma, indústria farmacêutica fundada em 1989, iniciou suas atividades no mercado de medicamentos em 1993 e desde o início mantém como objetivos'),
(212, 'Uma empresa de capital 100% nacional que atua a mais de 25 anos produzindo cabos especiais de alta qualidade para as mais diversas aplicações dos mercados como Cabos de Rede U/UTP e F/UTP para certificação de Rede Estruturada, CFTV, CATV, Telecomunicações, Energia, Fotovoltaicos e Informática'),
(213, 'A A.C Comercial de Produtos Agropecuários Ltda é uma empresa goiana fundada em 2001 e conhecida pelo nome fantasia Armazém do Criador. Localizada em Luziânia (GO), atua principalmente na fabricação de alimentos para animais e no comércio de produtos agropecuários.
Além da produção de rações, a empresa comercializa insumos agrícolas, alimentos para animais, medicamentos veterinários e artigos voltados ao setor agropecuário, atendendo produtores rurais e o mercado regional.'),
(214, 'A Gonzaga Importação e Comércio de Máquinas e Equipamentos Ltda atua no segmento de comércio e distribuição de máquinas e equipamentos, especializada na importação, comercialização e fornecimento de soluções para os setores industrial, agrícola, comercial e de serviços. A empresa desenvolve atividades voltadas ao abastecimento do mercado com equipamentos que contribuem para a produtividade, eficiência operacional e modernização dos processos produtivos.

Entre suas principais atividades estão a importação, venda e distribuição de máquinas, equipamentos, peças, acessórios e componentes técnicos, além da prestação de suporte comercial e atendimento especializado para diferentes segmentos econômicos. A empresa atua com foco em qualidade dos produtos, inovação tecnológica, eficiência logística, confiabilidade e satisfação de seus clientes e parceiros comerciais.'),
(216, 'Fundada em 08/11/2004 e com razão social Uilma Ribeiro dos Santos Sorvetes Saborizze, está localizada na cidade Luziânia do estado Goiás. Sua atividade principal, conforme a Receita Federal, é 10.53-8-00 - Fabricação de sorvetes e outros gelados comestíveis, fabricação de gelo comum e comércio varejista especializado na revenda de artigos não especificados nas classes anteriores. Sua situação cadastral até o momento é Ativa.'),
(217, 'Fundada em 21/05/2004 e com razão social Sx Infraestrutura LTDA, está localizada na cidade Brasília do estado Distrito Federal. Sua atividade principal, conforme a Receita Federal, é 23.30-3-05 - Preparação de massa de concreto e argamassa para construção. Sua situação'),
(218, 'A Fertilizantes Foleares Bio Nano Tech Ltda (Bio Nano Tech) atua no segmento do agronegócio, especializada na fabricação e comercialização de fertilizantes organominerais e soluções para nutrição vegetal. A empresa desenvolve produtos voltados ao aumento da produtividade agrícola, ao equilíbrio nutricional das culturas e à melhoria do desempenho das lavouras, atendendo produtores rurais e empresas do setor agropecuário. Sua atividade principal é a fabricação de adubos e fertilizantes organominerais.

Entre suas principais atividades estão a produção de fertilizantes organominerais, fertilizantes foliares, corretivos e insumos para nutrição vegetal, além da comercialização de adubos, fertilizantes e produtos destinados ao manejo agrícola. A empresa atua com foco em inovação tecnológica, eficiência agronômica, sustentabilidade, qualidade dos produtos e desenvolvimento de soluções que contribuam para o aumento da produtividade e rentabilidade no campo.'),
(226, 'Fundada em 1985 a Santa Apolônia esta a mais de 40 anos no mercado. Especializada na fabricação de máquinas em vários seguimentos, principalmente para a indústria cerâmica vermelha, branca e de pisos (via úmida e seca), se destaca na produção de estampos para a telha cerâmica nos mais variados tipos e modelos como também em exaustores, ventiladores, máquinas de queima, vagonetas, vagão para forno túnel, entre outros equipamentos e produtos.'),
(227, 'Também conhecida pelo nome fantasia Tintas Mil Cores foi uma empresa voltada à fabricação de tintas, vernizes, esmaltes e lacas, Fundação: 21/02/2008'),
(229, 'Sua atividade principal é de Comércio atacadista de defensivos agrícolas, adubos, fertilizantes e corretivos do solo empresa com a razão social Adubos Moema Industria e Comercio Ltda'),
(230, 'A Amor à Vida Produtos Naturais Ltda é uma empresa brasileira especializada na comercialização de produtos naturais, suplementos alimentares e itens voltados à saúde e bem-estar.

A companhia atua oferecendo produtos para alimentação saudável, nutrição e qualidade de vida, atendendo consumidores que buscam alternativas naturais para o dia a dia.

Com foco no segmento de produtos naturais, a empresa contribui para a promoção de hábitos mais saudáveis e bem-estar dos seus clientes.'),
(231, '(conhecida comercialmente como Teggomax) é uma empresa especializada na fabricação de artefatos de cimento para a construção civil. Com mais de 14 anos de mercado, ela produz telhas de concreto com tecnologia de ponta e design europeu e sua adividade principal e a fabricação de telhas e artefatos de cimento'),
(232, 'Geradores possui experiência em fabricação e instalação de Grupos Geradores e também no desenvolvimento de soluções para todos aqueles que necessitam de energia elétrica no horário de ponta e em situações de interrupção de fornecimento'),
(235, 'Sua atividade principal é de Construção de edifícios, Unidades Armazenadoras de Grãos e estruturas metálicas'),
(236, 'A Calçados Primus AP Artefatos de Couro Ltda é uma empresa brasileira especializada na fabricação de calçados e artefatos de couro, atendendo o mercado de moda e vestuário.

A companhia atua no desenvolvimento e produção de calçados com foco em qualidade, conforto e durabilidade, utilizando couro e outros materiais para atender diferentes segmentos de consumidores.

Com experiência no setor calçadista, a empresa contribui para a indústria nacional por meio da fabricação e comercialização de produtos voltados ao mercado de calçados.'),
(237, 'A sua situação cadastral é ATIVA e sua principal atividade econômica é Comércio atacadista especializado de materiais de construção não especificados anteriormente (. O nome fantasia, Isofrio Isolamentos Térmicos, sugere especialização em soluções de isolamento industrial e controle de temperatura)'),
(239, 'Sua principal atividade econômica é Fabricação de cosméticos, produtos de perfumaria e de higiene pessoal'),
(240, 'A Ki Vita – Indústria e Comércio de Alimentos Ltda atua no segmento alimentício, especializada na fabricação, industrialização e comercialização de alimentos destinados ao mercado consumidor. A empresa desenvolve produtos voltados à alimentação, buscando aliar qualidade, segurança alimentar e eficiência produtiva para atender consumidores, distribuidores e estabelecimentos comerciais.

Entre suas principais atividades estão a produção, processamento, embalagem e comercialização de alimentos, além da distribuição de seus produtos para supermercados, atacadistas, varejistas, restaurantes e outros estabelecimentos do setor alimentício. A empresa atua em conformidade com as normas sanitárias e de controle de qualidade, garantindo a segurança e a padronização de seus produtos.

A Ki Vita atua com foco em qualidade, inovação, boas práticas de fabricação, eficiência operacional, atendimento às necessidades do mercado e satisfação de seus clientes e consumidores.'),
(242, '(CNPJ 11.017.406/0001-01) é uma empresa fundada em 2009 com sede em Luziânia, GO. Sua atividade econômica principal registrada é a fabricação de estruturas pré-moldadas de concreto armado, operando na produção em série e sob encomenda'),
(244, 'A empresa com a razão social Wto Ambiental Ltda, tem o nome fantasia Wto Ambiental, opera com o CNPJ 20.203.173/0001-14 (20203173000114) e foi fundada em 06/05/2014. O endereço de sua sede está localizada na Distrito Industrial de Luziania - Distrito Industrial de Luziania (Dial) Luziania - GO, 72.832-000. Sua atividade principal é de Recuperação de materiais não especificados anteriormente, de acordo com o código CNAE E-3839-4/99.'),
(246, 'A Bauminas é uma empresa brasileira especializada na produção de soluções químicas para tratamento de água, saneamento e processos industriais.

A companhia atua no desenvolvimento e fornecimento de produtos como coagulantes, polímeros e outras soluções químicas utilizadas em estações de tratamento de água e efluentes, atendendo indústrias, concessionárias de saneamento e o setor público.

Com forte atuação no mercado nacional, a Bauminas se destaca pela inovação, sustentabilidade e compromisso com a eficiência dos processos de tratamento de água e preservação ambiental.'),
(248, 'Chlorum Goiás Indústria e Comércio de Cloro e Álcalis Ltda é uma empresa especializada na produção e comercialização de produtos químicos industriais, com foco em cloro, álcalis e insumos utilizados em processos de tratamento de água, saneamento e aplicações industriais.

A companhia atende indústrias e empresas de diversos segmentos, fornecendo soluções químicas voltadas à eficiência operacional, qualidade e conformidade ambiental.'),
(253, 'É uma empresa que ganhou destaque em notícias regionais devido a investigações sobre irregularidades em contratos de compra de áreas no Distrito Agroindustrial de Anápolis'),
(254, 'Sua atividade principal é de Fabricação de embalagens de papel, CARTUCHOS - EMBALAGEM etc...'),
(256, 'A Granol Indústria, Comércio e Exportação S.A. atua no segmento do agronegócio, sendo uma das principais empresas brasileiras no processamento de soja e na produção de derivados vegetais. Fundada em 1964, a companhia desenvolve atividades de industrialização, comercialização e exportação de produtos agroindustriais, atendendo os mercados nacional e internacional.

Entre suas principais atividades estão o esmagamento de soja, a produção de farelo de soja, óleo de soja bruto e refinado, biodiesel, glicerina, lecitina de soja e outros derivados, além da armazenagem, comercialização e exportação de commodities agrícolas. A empresa também atua na logística e no abastecimento da cadeia agroindustrial, contribuindo para os setores de alimentação animal, indústria alimentícia, química e de biocombustíveis. A Granol atua com foco em qualidade, sustentabilidade, eficiência operacional, inovação e fortalecimento do agronegócio brasileiro'),
(258, 'Sua atividade principal é de Comércio atacadista de produtos alimentícios em geral empresa brasileira com o maior portfólio de alimentos sem adição de açúcares do país'),
(260, 'Atividade principal é de Recuperação de materiais não especificados (Coleta de Resíduos Não-Perigosos) e (Tratamento e Disposição de Resíduos Não-Perigosos)'),
(262, 'Empresa de destaque na fabricação de suplementos alimentares e produtos de baixo teor calórico, com presença nacional e internacional desde 1991. A empresa também é conhecida como Midway Labs USA, focada em nutrição'),
(264, 'Fundada em 2006 um nome que carrega toda a tradição em excelência no atendimento, tecnologia e pioneirismo nos processos produtivos, eficiência logística Com ampla linha de produtos em aço, atuamos em todo o território nacional'),
(265, 'A Thunder Bolt Indústria de Alimentos Ltda, associada à Midway International Labs, é uma empresa de suplementos alimentícios localizada no DAIA (Distrito Agroindustrial de Anápolis)'),
(266, 'Principal atividade econômica é Fabricação de esquadrias de madeira e de peças de madeira para instalações industriais e comerciais (Fechado permanentemente)'),
(267, '(também relacionada à Midway International Labs e Thunder Bolt Indústria de Alimentos) é uma empresa com atuação no ramo de suplementos alimentares e produtos de baixo teor calórico (Fechado permanentemente)'),
(268, 'Profissionais com mais de 40 anos de experiência no mercado, sempre focados em oferecer uma Vasta Linha de Mármores e Granitos Nacionais e Importados'),
(269, 'Principal atividade econômica é Comércio atacadista de produtos de higiene, limpeza e conservação, possui 21 anos, 7 meses e 16 dias e foi fundada em 11/08/2004 domiciliar'),
(270, 'Sua atividade principal é de Fabricação de alimentos e pratos prontos, de acordo com o código CNAE C-1096-1/00.'),
(271, 'Sua atividade principal é de Comércio varejista de combustíveis para veículos automotores e restaurante de comida caseira'),
(272, 'É uma lavanderia industrial de grande porte situada no Distrito Agroindustrial de Anápolis (DAIA), Goiás, fundada em 2011. Especializada na gestão têxtil, oferece serviços de higienização e aluguel de uniformes, roupas de cama/mesa e banho para hotéis, hospitais e indústrias.'),
(273, 'Especializada na fabricação de medicamentos fitoterápicos para uso humano. Fundada em 1977, sua atividade principal é a produção de medicamentos fitoterápicos'),
(274, 'A Calcário Metago atua há mais de 40 anos na produção e comercialização de calcário, britas e agregados, sempre visando oferecer serviços e produtos com qualidade e eficiência'),
(275, 'Sua atividade principa disponibilizar produtos químicos para o tratamento da água e esgoto e através deles ser cada dia mais essencial para a vida, para o meio ambiente e para a sociedade.'),
(276, 'Indústria farmacêutica 100% brasileira, sediada no DAIA em Anápolis (GO), o maior polo farmoquímico da América Latina, e está entre as empresas que mais crescem no mercado de genéricos e similares.'),
(277, 'Especializada na fabricação de produtos farmacêuticos, a empresa atua na produção, focada no desenvolvimento e controle de qualidade de medicamentos. É associada a grupos internacionais, incluindo a Qualicaps.'),
(278, 'É um destacado grupo metalúrgico brasileiro, fundado em 1961, com forte atuação no Centro-Oeste e unidade produtiva em Anápolis, GO. Especializada em soluções em aço e alumínio, a empresa produz esquadrias, perfis e estruturas, atendendo à construção civil e ao agronegócio com produtos de qualidade certificada e alta tecnologia'),
(279, 'Parte do grupo Gravia, uma das maiores forças metalúrgicas do Centro-Oeste, fundada em 1961. A empresa atua na produção de perfis de aço e esquadrias, tendo passado por processo de recuperação judicial'),
(280, 'Um posto de combustíveis localizado no Distrito Agroindustrial de Anápolis (DAIA), Anápolis-GO, especializado no comércio varejista de combustíveis. Atualmente em recuperação judicial'),
(281, 'Grande indústria alimentícia fundada em 1985, reconhecida pela produção de cafés (torrado, moído, cápsulas) e uma linha diversificada de biscoitos, incluindo rosquinhas, cookies e crackers. Com tecnologia avançada e foco em produtos 100% vegetais, a marca expandiu sua presença nacional.'),
(285, 'A Roan Bonomilho passou a fazer parte da vida dos brasileiros em 1985, com o tradicional Cuscuz Bonomilho tornando-se referência no Brasil na produção e comercialização de produtos alimentícios.'),
(287, '(associada à marca KIMASSA) é uma empresa sediada em Anápolis, GO, com foco em holdings  de instituições não-financeiras e participações societárias.'),
(288, 'Empresa especializada na fabricação e comércio atacadista de instrumentos, materiais médicos, cirúrgicos, odontológicos e laboratoriais. Operando no DAIA, atua no setor da saúde'),
(289, 'Sua atividade principal, conforme a Receita Federal, é 25.11-0-00 - Fabricação de estruturas metálicas. Sua situação cadastral até o momento é Inapta.'),
(290, 'Estrutura para fabricação, venda, locação e assistência técnica de gruas. Dispomos de mais de 100 Gruas para Locação em Território Nacional Brasileiro, tendo como foco gruas torre, automontantes e ascensionais'),
(294, 'Conectar marcas e consumidores através de soluções de embalagem inovadoras e sustentáveis, pioneiros em embalagens digitais e sustentáveis'),
(295, 'Sua atividade principal é de Fabricação de medicamentos alopáticos para uso humano, é uma das cinco maiores empresas farmacêuticas do Brasil, atuando em 30 especialidades médicas e oferecendo 363 marcas em 978 apresentações de medicamentos'),
(297, 'Sua principal atividade econômica é Comércio atacadista de produtos alimentícios em geral, com atividade de fracionamento e acondicionamento associada.'),
(298, 'Oferece sabores únicos no mercado. Condimentos elaborados com ingredientes de qualidade que realçam o sabor de todas as receitas'),
(299, 'Sua atividade principal é de Serviços de usinagem, torneiria e solda com foco em atividades de manutenção industrial'),
(300, 'As maiores Empresas de Metal em Anápolis, Go de acordo com faturamento e porte são Isoeste Metalica Industria e Comercio Ltda com sede em Anápolis, GO classificamos as 10 Maiores Empresas de Metal em Anápolis'),
(301, 'Sua principal atividade econômica é Tratamento e disposição de resíduos não-perigosos, recuperação de materiais plásticos'),
(302, 'A J. Roberto Comércio Atacadista de Açúcar Ltda (JRCA), CNPJ 24.994.424/0004-20, é uma empresa com sede em Anápolis, GO, fundada em 05/08/2019, que atuava no comércio atacadista de açúcar'),
(303, 'Ua atividade principal é de Serviços de malote não realizados pelo Correio Nacional e Transporte rodoviário de mudanças e produtos perigosos'),
(304, 'Fabricação de produtos alimentícios e bebidas fornecimento de alimentos preparados preponderantemente para empresas'),
(305, 'Sua principal atividade econômica é Fabricação de tintas, vernizes, esmaltes e lacas e de secundária.	
Atividades de consultoria em gestão empresarial, exceto consultoria técnica específica'),
(307, 'Empresa ativa, fundada em 2013 . Especializada na fabricação de cabines, a empresa está localizada na Avenida Brasil Sul, 6380, Parque São João, atuando na fabricação de equipamentos rodoviário'),
(308, 'Empresa de destaque na fabricação de sorvetes artesanais e picolés. Com mais de 35 anos de mercado, a marca oferece sabores variados, focada na qualidade, frutas reais e alta rotatividade, atendendo supermercados e com sorveteria própria'),
(309, 'É uma empresa especializada na fabricação e comércio de produtos para nutrição e saúde animal (bovinos de corte, leite e equinos). Fundada em 2012, destaca-se por suplementos que dispensam manejo, visando baixo custo e alta produtividade para o pecuarista'),
(310, '(falecido em 2018) foi o fundador e presidente do grupo Carta Fabril, uma das maiores fabricantes de papel tissue (higiênico/toalha) e produtos de cuidados pessoais do país'),
(311, 'Um dos principais parques industriais do grupo, atuando no segmento de higiene pessoal e limpeza, sendo considerada uma das maiores indústrias do setor no Brasil. A empresa atua no Distrito Agroindustrial de Anápolis (DAIA) há mais de 20 anos, operando com fabricação de papel, produtos de papel (guardanapos, toalhas), fraldas descartáveis e absorventes'),
(312, 'Sua principal atividade econômica é Impressão de material de segurança. foi fundada em 12/08/1999 e Comércio Atacadista de Suprimentos para Informática'),
(313, 'A Bisnago é uma empresa brasileira especializada em soluções para o agronegócio, com atuação nas áreas de comercialização de insumos, nutrição vegetal e suporte técnico ao produtor rural.

A companhia trabalha para aumentar a produtividade e a eficiência das lavouras, oferecendo produtos e serviços voltados ao manejo agrícola e ao desenvolvimento sustentável no campo.

Com foco em inovação e proximidade com o cliente, a Bisnago atende produtores rurais e empresas do setor agropecuário, contribuindo para o fortalecimento da cadeia do agronegócio.'),
(314, 'Data de abertura é 01/10/2004 Sua atividade econômica principal é "fabricação de embalagens de material plástico", a qual corresponde ao código de Classificação Nacional de Atividades Econômicas'),
(320, 'A empresa fabrica telhas térmicas, painéis frigoríficos e fachadas que aumentam a eficiência energética e conforto térmico. É a união da brasileira Isoeste com a irlandesa'),
(324, 'Sua atividade principal é de Fabricação de produtos farmoquímicos, de acordo com o código CNAE C-2110-6/00'),
(326, 'Sua princital atividade e a fapricação de embalagens primárias de plástico  em Anápolis, Brasil, fabricamos embalagens primárias de plástico para aplicações oftálmicas,  sólidos e líquidos de uso oral, além de acessórios'),
(328, 'Empresa de destaque no ramo de Produção de forjados de aço, trabalha desde 1997 na categoria Ferros especializada em peças para caldeiras, cerâmica, engenho, engrenagem, polia industrial, construção civil, fundição em ferro cinzento, nodular, branco, alumínio, bronze e peças encomendadas'),
(330, 'Com mais de 60 anos de história  a Champion vem aprimorando suas técnicas de tratamento bovino se dedica ao tratamento animal'),
(333, 'Desde 1997, a PARAFIX se dedica à fabricação de parafusos e fixadores metálicos com alto padrão de resistência, precisão e segurança, atendendo às demandas de um mercado cada vez mais exigente.'),
(335, 'Empresa ativa desde 2007, especializada na fabricação e comércio de produtos de panificação e congelados, com destaque para hambúrgueres padronizados e congelados. A empresa atende a redes varejistas e atacadistas, focando em qualidade e conformidade com órgãos fiscalizadores'),
(338, 'Sua principal atividade econômica é Fabricação de outros brinquedos e jogos recreativos não especificados Fabricação de outras máquinas e equipamentos de uso geral não especificados anteriormente, peças e acessóriosanteriormente'),
(341, 'Sua principal atividade econômica é Gestão de ativos intangíveis não-financeiros, possui 15 anos, 6 meses e 16 dias Almoço completo com buffet À la carte caprichado Petiscos irresistíveis Tudo isso em um ambiente privilegiado, perfeito pra qualquer momento do dia'),
(346, 'Fundada em 2001 ,atividade principal é de Comércio atacadista de cimento especializada , com atuação predominante no mercado B2B'),
(348, 'Principal atividade econômica é Fabricação de embalagens de material plástico.Tamanho da empresa: 51-200 funcionários foi fundada em 09/07/1975'),
(350, 'Fundada em 1987 Sua atividade principal é o comércio varejista de combustíveis para veículos automotores e Serviços de Lavagem, Lubrificação e Polimento de Veículos Automotores,'),
(352, 'Empresa com mais de 40 anos de atuação (fundada em 1983), especializada na fabricação de artefatos de cimento e fibrocimento para a construção civil'),
(353, 'A empresa com a razão social Tubomax Pre-Moldados Industria e Comercio Ltda, tem o nome fantasia Tubomax Pre-Moldados Industria e Comercio, opera com o CNPJ 12.422.761/0001-10 (12422761000110) e foi fundada em 18/08/2010. O endereço de sua sede está localizada na Viela Vp 7-E, Modulos 3-I e 3-H - Distrito Agroindustrial de Anapolis, Anapolis - GO, 75.132-145. Sua atividade principal é de Fabricação de estruturas pré-moldadas de concreto armado, em série e sob encomenda, de acordo com o código CNAE C-2330-3/01.'),
(354, 'Empresa  de armazenagens e serviços aduaneiros do interior do Brasil,  possui um sistema global de gestão, Fundada em 02 de setembro'),
(367, 'Empresa que atuação no setor de tubos, conexões e plásticos para construção civil é listada como baixada no Bom Sucesso, enquanto há registros de operações ativas do grupo na região focadas em comércio atacadista'),
(368, 'Foi uma importante fábrica de pisos e azulejos, localizada no Distrito Agroindustrial de Anápolis (DAIA), que encerrou suas atividades em abril de 2016 após 38 anos de operação, resultando no desligamento de cerca de 150 a 180 funcionários.'),
(371, 'Fundada em dezembro de 1974 sua principal atividade e a produção de embalagens plásticas como embalagens de proditos de limpeza, cereais e popuch'),
(373, 'Indústria especializada em filmes e embalagens flexíveis desenvolvendo sob medida para diversos segmentos da indústria soluções em embalagens plásticas e foi fundada em 06/01/2005'),
(374, 'Atuação na fiscalização de instrumentos de medição (balanças), produtos pré-medidos e têxteis e inspeção veicular, garantindo a conformidade técnica e a segurança do consumidor na região'),
(375, 'Indústria especializada em embalagens para paletização sediada em Anápolis, GO, com mais de 20 anos de mercado. Produz filmes stretch, shrink e sacos PE/PP para proteção de cargas. A empresa, formalmente Goiaspack Industria e Comercio Ltda (CNPJ 05.604.243/0001-52), foca na fabricação de laminados'),
(376, 'Principal atividade econômica é Fabricação de luminárias e outros equipamentos de iluminação, arandelas, plafons, balizadores, embutidos, e diversos outros modelos'),
(377, 'Com mais de 25 anos de atuação sólida no mercado da construção de casas e apartamentos também atuando na construção de empreendimentos públicos e privados de grande porte, como indústrias, presídios e obras de infraestrutura. Projetos executados com precisão técnica'),
(387, 'Fundada em 2009, especializada na fabricação, importação e distribuição de insumos farmacêuticos e ativos para o mercado magistral, atua como importante fornecedor nacional'),
(388, 'Com 13 anos de sua existência é uma instituição focada na educação profissionalizante e tecnológica, oferecendo cursos técnicos e de qualificação. Com funcionamento de segunda a sábado, a instituição é reconhecida por cursos na área de logística e suporte a arranjos produtivos locais, incluindo TI e laboratórios de tecnologia.'),
(390, 'Fundada em 15/03/2012, sua atividade principal é de Fabricação de estruturas pré-moldadas de concreto armado, em série e sob encomenda'),
(391, 'A Guabi Nutrição e Saúde Animal atua no segmento de nutrição animal, sendo uma das principais empresas brasileiras especializadas no desenvolvimento, fabricação e comercialização de alimentos, suplementos e soluções nutricionais para diferentes espécies animais. A empresa atende os mercados de animais de produção, equinos e pets, oferecendo produtos voltados à saúde, desempenho e bem-estar animal.

Entre suas principais atividades estão a produção de rações, suplementos minerais, núcleos nutricionais, premixes, aditivos e produtos para nutrição animal, além do desenvolvimento de programas de manejo nutricional e suporte técnico especializado. A empresa atua com foco em pesquisa, inovação, qualidade, sustentabilidade e desenvolvimento de soluções que contribuam para a produtividade e a saúde dos animais.

A Guabi integra o grupo Mitsui & Co., ampliando sua capacidade de inovação e atuação no mercado nacional e internacional, com compromisso voltado à excelência nutricional e ao fortalecimento das cadeias produtivas do agronegócio e do mercado pet.'),
(393, 'É uma empresa de médio porte localizada em Anápolis, GO, especializada na metalurgia de metais não ferrosos. Fundada em agosto de 2010, opera ativamente no Distrito Agroindustrial de Anápolis (DAIA), com foco na fabricação de peças e produtos metálicos.'),
(394, 'Sua principal atividade e a  fabricante de embalagens personalizadas em diversos formatos. com grande estrutura e modernos maquinários para garantir a qualidade e máximo aproveitamento da matéria prima.'),
(395, 'A empresa é referência na produção de medicamentos acessíveis produção e comercialização'),
(399, 'Empresa ativa desde 2008 especializada na fabricação de artefatos de tanoaria e embalagens de madeira. Com atuação no setor de transformação, a empresa fabrica paletes e estruturas de madeira para suporte e movimentação de cargas'),
(400, 'Indústria farmacêutica 100% brasileira, sediada no DAIA em Anápolis (GO), o maior polo farmoquímico da América Latina, e está entre as empresas que mais crescem no mercado de genéricos e similares.'),
(408, 'Copocentro Indústria de Plásticos Ltda foi uma empresa de Anápolis (GO) especializada na fabricação de artefatos plásticos para uso pessoal e doméstico, produzindo itens destinados ao consumo cotidiano e ao mercado de utilidades.

A companhia atuava no setor de transformação de plásticos, atendendo demandas comerciais e industriais. Atualmente, a empresa encontra-se com situação cadastral baixada, não estando mais em operação.'),
(411, 'Uma das principais operadoras de telefonia fixa e móvel do Brasil, atuando na Região II (que inclui Goiás e, consequentemente, Anápolis) após a privatização do Sistema Telebrás em 1998'),
(419, 'Fundada em 17/05/1999 e operava na área de telefonia móvel celular. A empresa está atualmente com sua situação cadastral baixada, foi incorporada à TCO e depois à Vivo em 2003.'),
(422, 'Investindo sempre em aprimoramento tecnológico e apostando na extraordinária força de trabalho de sua equipe, o Teuto atravessa quase 8 décadas vencendo desafios e passando com sucesso por todas as dificuldades.

Atualmente, a companhia possui mais de 540 produtos registrados entre medicamentos de referência, genéricos, genéricos de marca (similares equivalentes – EQ’s), MIP’s (medicamentos isentos de prescrição), linha de especialidades, que incluiu os biossimilares. Além disso, temos os suplementos alimentares, cosméticos e produtos para a saúde. Nos próximos anos, está programado o lançamento de mais de 250 novas apresentações.'),
(423, 'Possui 7 anos, 2 meses e 23 dias e foi fundada em 24/01/2019 . A sua situação cadastral é BAIXADA e sua principal atividade econômica é Fabricação de fraldas descartáveis'),
(424, 'Consórcio FBM 1 foi uma associação empresarial sediada em Anápolis (GO), formada por empresas do setor farmacêutico para atuar em atividades de envase, empacotamento e distribuição de medicamentos e produtos para a saúde.

O consórcio operou entre 2017 e 2019, atendendo demandas da indústria farmacêutica por meio de serviços especializados de embalagem e apoio logístico. Atualmente, a empresa encontra-se com situação cadastral baixada por encerramento voluntário de suas atividades.'),
(425, 'E uma empresa ativa especializada em transporte rodoviário de cargas (intermunicipal, interestadual e internacional). A empresa foca no planejamento logístico, movimentação e distribuição de mercadorias'),
(426, 'Especializada em transporte rodoviário de cargas (intermunicipal, interestadual e internacional), a empresa opera focada em logística e comércio exterior'),
(427, 'Com mais de 30 anos de atividade, acabou se cosolidando como pomto de referência em soluções de aço para estruturas detalicas e sistemas de cobertura'),
(428, 'Com 54 anos de atividade, sua atividade principal é de Fabricação de artefatos de material plástico para outros usos não especificados anteriormente'),
(429, 'Com 26 anos de atividade, destaca-se na fabricação de papéis sanitários, guardanapos, toalhas e fraldas, sendo adquirida pela Softys Brasil em 2021'),
(432, 'Com mais de 60 anos de história  a Champion vem aprimorando suas técnicas de tratamento bovino se dedica ao tratamento animal'),
(433, 'A ENEL atua no setor de energia elétrica, sendo uma das principais empresas privadas do segmento no Brasil, com operações voltadas à geração, distribuição, transmissão, comercialização e soluções energéticas. A companhia desenvolve atividades em toda a cadeia do setor elétrico, com forte presença na geração de energia renovável, especialmente por meio de fontes eólica, solar e hidrelétrica.

Entre suas principais atividades estão a geração de energia elétrica a partir de fontes renováveis, distribuição de energia para consumidores residenciais, comerciais, industriais e rurais, comercialização de energia no mercado livre, transmissão de energia, desenvolvimento de projetos de eficiência energética, implantação de soluções de infraestrutura elétrica e oferta de serviços relacionados à transição energética e sustentabilidade. A empresa atua com foco em inovação tecnológica, eficiência operacional, digitalização de redes, sustentabilidade e fornecimento seguro de energia.'),
(434, 'CNPJ 05.250.358/0001-96, está localizada no Distrito Agroindustrial de Anápolis (GO). Atualmente em recuperação judicial, a instalação é conhecida por ter operado como uma usina emergencial e geradora de 44,3 MW, e Comércio atacadista de energia elétrica, Embora tenha enfrentado longos períodos de inoperância possui 23 anos, 9 meses e 29 dias e foi fundada em 27/08/2002'),
(435, 'A Ideal Farma Indústria e Comércio de Produtos Farmacêuticos Ltda atua no segmento farmacêutico, especializada na fabricação, industrialização e comercialização de produtos destinados à saúde, bem-estar e cuidados pessoais. A empresa desenvolve soluções voltadas ao atendimento das demandas do mercado farmacêutico, buscando qualidade, segurança e conformidade com as normas regulatórias do setor.

Entre suas principais atividades estão a fabricação e comercialização de produtos farmacêuticos, medicamentos, suplementos, produtos para higiene pessoal, cosméticos e itens correlatos, além da distribuição e fornecimento para farmácias, drogarias, distribuidores e estabelecimentos de saúde. A empresa atua com foco em qualidade, inovação, boas práticas de fabricação, segurança dos produtos e atendimento às necessidades de seus clientes e consumidores.'),
(437, 'A Agroindústria Canjerana Ltda é uma empresa goiana localizada em Anápolis (GO), especializada na produção de sucos concentrados, polpas e conservas de frutas. Fundada em 2021, a companhia atua no processamento de produtos agrícolas, agregando valor à produção do setor agroindustrial.

Além da industrialização de frutas, a empresa também desenvolve atividades de armazenamento, comercialização de hortifrutigranjeiros e transporte de cargas, apoiando toda a cadeia de produção e distribuição de alimentos.'),
(438, 'A Gerbrás atua no segmento industrial e empresarial, desenvolvendo soluções voltadas à fabricação, comercialização e distribuição de produtos e serviços para diferentes setores do mercado. A empresa busca atender às demandas de clientes comerciais, industriais e corporativos, com foco em qualidade, eficiência operacional e desenvolvimento sustentável de seus negócios.

Entre suas principais atividades estão a produção, beneficiamento, comercialização e distribuição de produtos, além da prestação de serviços especializados e suporte às operações de seus clientes. A empresa atua com compromisso em inovação, melhoria contínua, excelência operacional, atendimento de qualidade e geração de valor para seus parceiros e clientes.'),
(439, 'A C. Gabriela de Castro Lopes – Premoldados é uma empresa especializada na fabricação de artefatos de concreto e estruturas pré-moldadas para a construção civil.

A companhia atua na produção de peças como blocos, mourões, tubos, pisos e outros elementos pré-moldados utilizados em obras residenciais, comerciais e de infraestrutura. Seu foco está em oferecer soluções que proporcionem agilidade, resistência e eficiência aos projetos de construção.

Com atuação no setor de materiais para construção, a empresa atende às demandas de construtoras, empreiteiras e clientes particulares da região.'),
(440, 'Competec Máquinas Indústria e Comércio Ltda é uma empresa de Anápolis (GO) especializada na fabricação de máquinas e equipamentos para uso industrial, além de peças e acessórios destinados a processos produtivos de diversos setores.

A companhia também atua no desenvolvimento tecnológico, manutenção de equipamentos industriais, fabricação de estufas, fornos, sistemas de refrigeração e ventilação industrial, oferecendo soluções voltadas à eficiência e inovação para a indústria.'),
(441, 'Tintas Colatex é uma indústria química sediada em Anápolis (GO), especializada na fabricação de tintas imobiliárias, esmaltes, vernizes, texturas, grafiatos e solventes. Com mais de 20 anos de atuação no mercado, a empresa distribui seus produtos para milhares de pontos de venda em todo o Brasil.

A companhia possui certificação ISO 9001 e mantém foco na qualidade, inovação e sustentabilidade, buscando oferecer soluções para o setor da construção civil por meio de produtos de baixo impacto ambiental e melhoria contínua de seus processos.'),
(442, 'A JRA Logística Ltda atua no segmento de logística e transporte rodoviário de cargas, especializada na movimentação, armazenagem, distribuição e gerenciamento logístico de mercadorias para diversos setores da economia. A empresa desenvolve soluções integradas que visam otimizar a cadeia de suprimentos, garantindo eficiência operacional, segurança e agilidade nas operações.

Entre suas principais atividades estão o transporte rodoviário de cargas, logística de distribuição, armazenagem, movimentação de mercadorias, gestão de frotas, coleta e entrega, além da prestação de serviços de apoio logístico e gerenciamento da cadeia de abastecimento. A empresa atende clientes dos segmentos industrial, comercial, agropecuário e de serviços, oferecendo soluções adaptadas às necessidades de cada operação.

A JRA Logística atua com foco em qualidade, pontualidade, segurança, rastreabilidade, eficiência operacional e satisfação de seus clientes, contribuindo para a otimização dos processos logísticos e o fortalecimento das operações de seus parceiros comerciais.'),
(443, 'Fundada em 27/05/2025 e com razão social Softech S.a, está localizada na cidade Uccle do estado Bruxelas. Sua atividade principal, conforme a Receita Federal, é 64.62-0-00 - Holdings de instituições não-financeiras. Sua situação cadastral até o momento é Ativa'),
(444, 'Copalimpa Indústria Têxtil Ltda é uma empresa de Anápolis (GO) especializada na fabricação de tecidos e artigos de limpeza, produzindo itens como flanelas, panos de limpeza, panos de prato, sacarias de algodão, toalhas e outros produtos têxteis para uso doméstico e comercial. A empresa atua há mais de três décadas no mercado e está instalada no Distrito Agroindustrial de Anápolis (DAIA).

Reconhecida como uma das principais indústrias têxteis do Centro-Oeste nesse segmento, a Copalimpa atende clientes em todo o país, mantendo foco na qualidade dos produtos, inovação e responsabilidade socioambiental.'),
(447, 'A Galgane Construtora Ltda atua no segmento da construção civil, especializada na execução de obras, reformas e projetos de engenharia voltados aos setores residencial, comercial, industrial e de infraestrutura. A empresa desenvolve soluções construtivas com foco em qualidade, segurança, eficiência operacional e atendimento às necessidades específicas de cada empreendimento.

Entre suas principais atividades estão a construção de edificações, execução de obras civis, reformas, terraplanagem, infraestrutura urbana, gerenciamento de obras e prestação de serviços de engenharia. A empresa atua com compromisso em responsabilidade técnica, cumprimento de prazos, inovação nos processos construtivos e excelência na entrega de seus projetos, contribuindo para o desenvolvimento de empreendimentos sustentáveis e de alto padrão de qualidade.'),
(448, 'A Indústria e Comércio de Conexões Catarinense Ltda atua no segmento industrial e metalúrgico, especializada na fabricação e comercialização de conexões, componentes e acessórios utilizados em sistemas de tubulação para aplicações industriais, hidráulicas, sanitárias e de infraestrutura. A empresa desenvolve soluções voltadas à segurança, vedação, resistência e eficiência operacional dos sistemas onde seus produtos são aplicados.

Entre suas principais atividades estão a fabricação de conexões, flanges, uniões, adaptadores, curvas, tees, reduções e demais componentes para redes de condução de líquidos, gases e outros fluidos, além da comercialização e distribuição desses produtos para indústrias, construtoras, empresas de saneamento e comércio especializado. A empresa atua com foco em qualidade, conformidade técnica, durabilidade, inovação e atendimento às necessidades de seus clientes e parceiros comerciais.'),
(449, 'Possui 10 anos, 5 meses e 13 dias e foi fundada em 11/01/2016. A sua situação cadastral é ATIVA e sua principal atividade econômica é Transporte rodoviário de carga, exceto produtos perigosos e mudanças, intermunicipal, interestadual e internacional.'),
(457, 'A Goiarte Soluções Construtivas em Concreto Ltda atua no segmento da construção civil, especializada na fabricação e fornecimento de soluções em concreto para obras residenciais, comerciais, industriais e de infraestrutura. A empresa desenvolve produtos e serviços voltados à eficiência construtiva, resistência estrutural e qualidade técnica, atendendo às demandas de diferentes tipos de empreendimentos.

Entre suas principais atividades estão a produção de concreto usinado, artefatos de concreto, peças pré-moldadas e soluções construtivas para fundações, estruturas e pavimentação, além do suporte técnico e logístico para abastecimento de obras. A empresa atua com foco em inovação, controle de qualidade, produtividade, segurança e atendimento às necessidades específicas de seus clientes e projetos.'),
(466, 'A Fortaleza Rações Ltda atua no segmento de nutrição animal, especializada na fabricação, comercialização e distribuição de rações e suplementos destinados à alimentação de animais. A empresa desenvolve soluções nutricionais voltadas ao desempenho produtivo, à saúde e ao bem-estar animal, atendendo produtores rurais, pecuaristas e empresas do setor agropecuário.

Entre suas principais atividades estão a produção de rações balanceadas, suplementos minerais, concentrados, núcleos nutricionais e outros produtos para alimentação animal, além da distribuição e comercialização de insumos destinados à pecuária e demais atividades agropecuárias. A empresa atua com foco em qualidade nutricional, eficiência produtiva, inovação e desenvolvimento de soluções que contribuam para a produtividade e sustentabilidade das operações rurais.'),
(467, 'A Auto Reformadora JD Ltda é uma empresa de Senador Canedo (GO) especializada em serviços de reforma, manutenção e recuperação de veículos automotores.

A companhia atua com reparos mecânicos, serviços de funilaria e recuperação de componentes automotivos, atendendo veículos leves e pesados. Seu foco está em oferecer soluções para conservação, reparação e prolongamento da vida útil da frota de seus clientes.'),
(468, 'A Cerâmica Progresso é uma empresa especializada na fabricação e comercialização de materiais cerâmicos para a construção civil, atendendo obras residenciais, comerciais e de infraestrutura.

A companhia produz e fornece itens como tijolos, blocos e outros artefatos cerâmicos, além de atuar no segmento de materiais para construção, oferecendo soluções voltadas à qualidade, resistência e durabilidade das edificações.

Com atuação em Mineiros (GO), a empresa contribui para o desenvolvimento da construção civil regional por meio do fornecimento de produtos essenciais para obras e reformas.'),
(472, 'A Indústria e Comércio de Móveis Michels Ltda atua no segmento moveleiro, especializada na fabricação, industrialização e comercialização de móveis para ambientes residenciais, comerciais e corporativos. A empresa desenvolve produtos que combinam funcionalidade, conforto, durabilidade e design, atendendo às demandas de diferentes perfis de consumidores e mercados.

Entre suas principais atividades estão a produção de móveis em madeira, MDF e materiais derivados, fabricação de móveis planejados ou seriados, desenvolvimento de soluções para dormitórios, salas, cozinhas, escritórios e ambientes comerciais, além da comercialização e distribuição de seus produtos. A empresa atua com foco em qualidade dos materiais, inovação, eficiência produtiva, acabamento de excelência e satisfação de seus clientes e parceiros comerciais.'),
(475, 'Empresa está empenhada em oferecer o pré-moldado que você precisa para utilizar em sua fazenda. Produzimos desde cochos e bebedouros para seus animais até a montagem de galpões e reservatórios oferecendo tubos, aduelas, postes e vigas para postes. A Tenax tem participação em diversas construções voltadas para vários segmentos.Conheça alguns dos projetos desenvolvidos utilizando nossos pré-moldados e outros produtos,  possui 26 anos, 3 meses e 14 dias e foi fundada em 10/03/2000'),
(482, 'A Laticínio São Francisco Ltda atua no segmento de laticínios, especializada na captação, processamento, industrialização e comercialização de leite e derivados, atendendo aos mercados varejista, atacadista e institucional. A empresa desenvolve produtos alimentícios com foco em qualidade, segurança dos alimentos e valorização da produção leiteira.

Entre suas principais atividades estão o beneficiamento de leite, fabricação de queijos, manteiga, requeijão, creme de leite, leite pasteurizado, bebidas lácteas, iogurtes e outros derivados, além da embalagem, distribuição e comercialização de seus produtos para supermercados, distribuidores, estabelecimentos de alimentação e consumidores finais. A empresa atua em conformidade com as normas sanitárias e as boas práticas de fabricação.

O Laticínio São Francisco atua com foco em qualidade, inovação, eficiência produtiva, sustentabilidade, controle de qualidade e satisfação de seus clientes, contribuindo para o fortalecimento da cadeia de laticínios e para o fornecimento de alimentos seguros e de alto padrão ao mercado.'),
(486, 'A R. G. R. Pré Moldados e Construções Ltda foi uma empresa brasileira focada na fabricação de artefatos de cimento para uso na construção civil, Encontra-se com o CNPJ baixado (empresa inativa)'),
(489, 'A Indústria e Comércio de Café Mineirense Ltda atua no segmento alimentício, especializada no beneficiamento, torrefação, moagem, industrialização e comercialização de café. A empresa desenvolve atividades voltadas à produção e distribuição de cafés destinados ao mercado consumidor, buscando oferecer produtos com qualidade, sabor e padronização.

Entre suas principais atividades estão a seleção e processamento de grãos de café, torrefação, moagem, empacotamento, comercialização e distribuição de café torrado e moído, além do fornecimento de produtos para supermercados, atacadistas, estabelecimentos comerciais e consumidores finais. A empresa atua com foco em qualidade, segurança alimentar, eficiência produtiva, tradição no setor cafeeiro e satisfação de seus clientes e consumidores.'),
(492, 'E uma empresa que opera sob o nome fantasia RIT CEREAIS sediada em Mineiros, Goiás. Fundada em janeiro de 2017, sua principal atividade econômica é a operação de armazéns gerais com atividades econômicas secundaeías sendo fabricação de alimentos para animais, Comércio atacadista de cereais, representação comercial e transporte rodoviário de cargas'),
(496, 'A empresa Tupa de CNPJ 09.308.951/0001-05, fundada em 16/01/2008 e com razão social Tupa Penas LTDA, está localizada na cidade Guatambú do estado Santa Catarina. Sua atividade principal, conforme a Receita Federal, é 13.40-5-99 - Outros serviços de acabamento em fios, tecidos, artefatos têxteis e peças do vestuário. Sua situação cadastral até o momento é Ativa.'),
(497, 'A H & JK Ltda atua no segmento empresarial e comercial, desenvolvendo atividades voltadas à fabricação, comercialização, distribuição de produtos e prestação de serviços para diferentes setores da economia. A empresa busca oferecer soluções que atendam às necessidades de seus clientes com foco em qualidade, eficiência operacional e excelência no atendimento.

Entre suas principais atividades estão a industrialização, comercialização e distribuição de produtos, além da prestação de serviços especializados e suporte às operações de empresas e consumidores. A empresa atua com compromisso em inovação, organização, melhoria contínua dos processos, confiabilidade e geração de valor para seus clientes e parceiros comerciais.'),
(500, 'A Implementos Bela Vista Ltda – ME atua no segmento metalúrgico e de implementos, especializada na fabricação, montagem e comercialização de equipamentos e implementos destinados principalmente aos setores agrícola, pecuário, industrial e de transporte. A empresa desenvolve soluções voltadas ao aumento da produtividade, eficiência operacional e suporte às atividades do campo e da indústria.

Entre suas principais atividades estão a fabricação de implementos agrícolas, estruturas metálicas, carrocerias, reboques, equipamentos de apoio à produção rural e peças sob medida, além da prestação de serviços de manutenção e adaptação de equipamentos. A empresa atua com foco em qualidade, resistência, inovação, atendimento personalizado e desenvolvimento de soluções adequadas às necessidades de seus clientes e parceiros.'),
(501, 'A Laboratórios Raça atua no segmento de saúde animal, especializada na pesquisa, desenvolvimento, fabricação e comercialização de medicamentos e produtos veterinários destinados à prevenção, tratamento e bem-estar de animais de produção e de companhia. A empresa oferece soluções voltadas ao fortalecimento da sanidade animal e ao aumento da produtividade dos sistemas pecuários.

Entre suas principais atividades estão a produção de medicamentos veterinários, vacinas, antiparasitários, antibióticos, suplementos, produtos para reprodução, higiene e manejo animal, além da prestação de suporte técnico e orientação aos médicos-veterinários, distribuidores e produtores rurais. A empresa atende os mercados de bovinos, equinos, suínos, aves, pequenos ruminantes e animais de companhia.

Os Laboratórios Raça atuam com foco em inovação, pesquisa científica, qualidade, segurança, conformidade regulatória e desenvolvimento de soluções que contribuam para a saúde animal, a sustentabilidade da produção pecuária e a satisfação de seus clientes e parceiros.'),
(502, 'A Boutt Bebidas é uma empresa especializada na produção, distribuição e comercialização de bebidas, atendendo consumidores, estabelecimentos comerciais e eventos.

A companhia trabalha com um portfólio diversificado de bebidas, buscando oferecer qualidade, praticidade e atendimento eficiente aos seus clientes. Seu foco está na distribuição e fornecimento de produtos para o mercado regional, contribuindo para o abastecimento de bares, restaurantes, mercados e demais pontos de venda.

Com atuação no setor de bebidas, a empresa se destaca pelo compromisso com a qualidade dos produtos e o relacionamento próximo com seus clientes.'),
(503, 'Empresa que está localizada no município de Mineiros/GO e cuja data de abertura é 08/01/2014, estando atualmente com sua situação cadastral Ativa na Receita Federal. Sua atividade econômica principal é "fabricação de outros produtos de minerais não-metálicos não especificados anteriormente", a qual corresponde ao código de Classificação Nacional de Atividades Econômicas (CNAE) nº 2399-1/99.'),
(506, 'A Granol Indústria, Comércio e Exportação S.A. é um dos maiores complexos de agronegócio do Brasil, fundada em 1965, com foco na industrialização de oleaginosas, produção de farelo de soja, óleos vegetais e biocombustíveis. A empresa destaca-se pela produção de biodiesel, glicerina e produtos refinados, possuindo laboratórios acreditados e unidades industriais em diversos estados brasileiros, além de forte atuação em exportação'),
(509, 'Coopavip (Cooperativa Agropecuária Vale do Rio dos Bois) é uma cooperativa goiana voltada ao fortalecimento do agronegócio e da agricultura familiar, oferecendo suporte aos produtores rurais por meio da comercialização da produção, fornecimento de insumos e assistência técnica.

A cooperativa atua no desenvolvimento das atividades agropecuárias de seus cooperados, promovendo maior competitividade, geração de renda e crescimento sustentável no campo, além de incentivar o cooperativismo como ferramenta de desenvolvimento regional.'),
(516, 'A empresa com a razão social Sebastiao Machado da Silva Sobrinho, tem o nome fantasia Serralheria Metal Sema, opera com o CNPJ 11.821.920/0001-97(11821920000197) e foi fundada em 30/03/2010. O endereço de sua sede está localizada na Via Secundaria 4, Orizona - GO, 75.280-000. Sua atividade principal é de Fabricação de esquadrias de metal, de acordo com o código CNAE C-2512-8/00.'),
(517, 'A Saint-Gobain do Brasil Produtos Industriais e para Construção Ltda é uma subsidiária da multinacional francesa líder em construção leve e sustentável, focada no design, produção e distribuição de materiais para habitação e indústria (vidros, argamassas, abrasivos). Com presença forte no Brasil, atua com marcas renomadas como Brasilit, Placo e Quartzolit'),
(518, 'M S Indústria e Comércio de Madeiras Ltda (MS Madeiras), fundada em 1993 em Anápolis-GO, é uma empresa especializada na fabricação de artefatos de madeira, focada em produtos de alta qualidade, como tábuas e utensílios, utilizando madeira de reflorestamento'),
(519, 'A Massa Forte Ltda (Holtz e Dias) atua no segmento da construção civil, especializada na fabricação e comercialização de argamassas, massas e outros materiais destinados a obras residenciais, comerciais, industriais e de infraestrutura. A empresa desenvolve produtos que proporcionam qualidade, resistência, praticidade e desempenho nas etapas de construção e acabamento.

Entre suas principais atividades estão a fabricação de argamassas colantes, argamassas de revestimento, rebocos, massas para assentamento, produtos para regularização de superfícies e outros materiais para construção civil, além da comercialização e distribuição desses produtos para construtoras, revendedores, profissionais da construção e consumidores finais.

A Massa Forte atua com foco em qualidade, inovação, conformidade técnica, eficiência produtiva, atendimento especializado e satisfação de seus clientes, oferecendo soluções que contribuem para a durabilidade, segurança e qualidade das obras.'),
(521, 'Especializada no transporte rodoviário de cargas secas, operando ativamente no Distrito Agroindustrial de Anápolis (DAIA). Fundada em 2010, atua no transporte municipal, intermunicipal, interestadual e internacional de cargas, exceto produtos perigosos'),
(522, 'Fundada em 05/07/2000 e com razão social Sar Industria, Comercio e Servicos Eletricos LTDA, está localizada na cidade Orizona do estado Goiás. Sua atividade principal, conforme a Receita Federal, é 27.90-2-99 - Fabricação de outros equipamentos e aparelhos elétricos não especificados anteriormente. Sua situação cadastral até o momento é Ativa.'),
(523, 'A CDA Alimentos S.A, com mais de 30 anos de atuação no mercado de distribuição e produção de alimentos, concentra suas vagas em Goiás (Anápolis, Rio Verde) e Tocantins, focando em áreas comerciais e de logística'),
(524, 'Empresa com mais de 40 anos de atuação, sediada em Videira, SC. Fundada em 1981, concentra-se na fabricação de medicamentos alopáticos para uso humano. A empresa possui operação ativa, focada em produtos farmacêuticos'),
(525, 'A MASTERTUBO INDUSTRIA E COMERCIO LTDA - ME (Master Tubo), fundada em 31/08/1999, é uma empresa com CNPJ 03.385.456/0001-05 e sede em Anápolis, GO, com situação cadastral ativa. Sua principal atividade econômica é a organização logística do transporte de carga'),
(526, 'Pilar logístico estratégico, destacando-se pela conexão da Estrada de Ferro Centro-Atlântica (FCA) com a moderna Ferrovia Norte-Sul (FNS). O município, que teve seu desenvolvimento impulsionado pela estação inaugurada em 1935, hoje utiliza o DAIA (Distrito Agroindustrial) como ponto central de escoamento de cargas para os portos, integrando o sudoeste e norte do país'),
(528, 'Atua na investigação de crimes e segurança local, com delegacias especializadas, Grupo de Investigação de Homicídios (GIH) e Grupo Especial de Investigação Criminal (GEIC)'),
(530, 'Indústria brasileira familiar, fundada em 2002 e sediada em Anápolis-GO (DAIA), líder no mercado de saúde ambiental, animal e humana. Com mais de 100 soluções, incluindo inseticidas (nº 1 em líquido e top 4 em aerossol), jardinagem e produtos PET, a empresa cresce em média 25% ao ano e se destaca pela tecnologia e responsabilidade ambiental'),
(533, 'Sua atividade principal é de Comércio atacadista de medicamentos e drogas de uso humano (encerado permanentemente)'),
(535, 'Um posto de combustíveis localizado no Distrito Agroindustrial de Anápolis (DAIA), Anápolis-GO, especializado no comércio varejista de combustíveis. Atualmente em recuperação judicial'),
(537, 'É uma empresa sediada no Distrito Agroindustrial de Anápolis (DAIA), Goiás, fundada em 18/06/2009. Focada na fabricação de produtos de saúde e desenvolvimento de tecnologias inovadoras, a empresa atua no comércio atacadista de instrumentos e materiais médicos.'),
(539, 'A empresa é referência na produção de medicamentos acessíveis produção e comercialização'),
(544, 'É uma empresa brasileira líder na fabricação de dermocosméticos, medicamentos isentos de prescrição (MIPs), adoçantes e suplementos, sendo uma subsidiária integral da Hypera S.A.. Sediada em Barueri (SP), possui grandes complexos industriais em Goiânia e Anápolis (GO), produzindo marcas conhecidas'),
(546, 'A principal distribuidora de energia elétrica do estado, atendendo 237 municípios (mais de 3,4 milhões de clientes) após assumir a operação da antiga Celg. A empresa, que integra o Grupo Equatorial, foca em melhoria operacional e modernização da rede elétrica em uma área de 337 mil'),
(548, 'A Brainfarma Indústria Química e Farmacêutica S.A. é um dos maiores fabricantes de medicamentos do Brasil, controlada pela Hypera S.A.. Sediada em Anápolis-GO, opera uma das maiores plantas da América Latina, produzindo formas sólidas, líquidas, semissólidos, injetáveis e cosméticos, com um avançado centro de Pesquisa e Desenvolvimento em Barueri-SP'),
(549, 'A Lopes Alves Representações e Serviços Ltda atua no segmento de representação comercial e prestação de serviços, especializada na intermediação de negócios e na promoção de produtos e serviços para empresas de diversos setores da economia. A empresa desenvolve soluções comerciais voltadas à expansão de mercados, fortalecimento de parcerias e geração de oportunidades de negócios.

Entre suas principais atividades estão a representação comercial de indústrias e fornecedores, prospecção e atendimento de clientes, negociação e acompanhamento de vendas, gestão de relacionamento comercial, além da prestação de serviços de apoio administrativo, operacional e consultivo. A empresa atua como elo entre fabricantes, distribuidores e clientes, contribuindo para o desenvolvimento das atividades comerciais de seus parceiros.

A Lopes Alves Representações e Serviços atua com foco em qualidade, ética, eficiência, comprometimento, atendimento personalizado e excelência na prestação de serviços, buscando oferecer soluções que agreguem valor às operações comerciais de seus clientes e parceiros.'),
(553, 'Atua no ramo de Comércio varejista de animais vivos e de artigos e alimentos para animais de estimação, com início das atividades em 10/02/2025 localizada em Iguatama-MG e possui o CNPJ 59.370.520/0001-39. A empresa encontra-se Ativa com a data da última atualização cadastral em 10/02/2025.'),
(559, 'A Agroquímica Catalão Indústria e Comércio de Fertilizantes Ltda é uma empresa goiana especializada na produção e comercialização de fertilizantes e insumos agrícolas.

Localizada em Catalão (GO), a companhia atua no fornecimento de soluções para nutrição vegetal, atendendo produtores rurais e empresas do agronegócio. Seu foco está em contribuir para o aumento da produtividade agrícola por meio de produtos voltados à correção e fertilização do solo.'),
(562, 'A Hebert & Hegert Johanssen Recuperadora de Resíduos Ltda atua no segmento de gestão ambiental e reciclagem, especializada na coleta, recuperação, processamento e destinação adequada de resíduos provenientes de atividades industriais, comerciais e urbanas. A empresa desenvolve soluções voltadas ao reaproveitamento de materiais e à redução dos impactos ambientais, contribuindo para a sustentabilidade e a economia circular.

Entre suas principais atividades estão a coleta e triagem de resíduos, recuperação de materiais recicláveis, processamento de sucatas e resíduos industriais, reciclagem, comercialização de materiais recuperados e destinação ambientalmente adequada de resíduos. A empresa atua com foco em responsabilidade ambiental, conformidade com a legislação vigente, eficiência operacional e desenvolvimento de soluções sustentáveis para seus clientes e parceiros.'),
(563, 'A Foco Fertilizantes Ltda atua no segmento do agronegócio, especializada na fabricação, comercialização e distribuição de fertilizantes, corretivos de solo e insumos destinados à nutrição vegetal. A empresa desenvolve soluções voltadas ao aumento da produtividade agrícola, ao manejo eficiente das culturas e à melhoria da fertilidade do solo, atendendo produtores rurais e empresas do setor agropecuário.

Entre suas principais atividades estão a produção e comercialização de fertilizantes minerais, organominerais e especiais, corretivos agrícolas, condicionadores de solo e produtos para nutrição vegetal, além da distribuição de insumos agrícolas e suporte técnico aos clientes. A empresa atua com foco em inovação, qualidade dos produtos, eficiência agronômica, sustentabilidade e desenvolvimento de soluções que contribuam para a produtividade e rentabilidade das atividades agrícolas.'),
(564, 'A Caramuru Alimentos é uma das maiores empresas brasileiras do agronegócio, especializada no processamento de soja, milho e girassol, além da produção de óleos vegetais, farelos, biodiesel e ingredientes para as indústrias alimentícia e de nutrição animal.

Fundada em Goiás, a companhia atua em toda a cadeia agroindustrial, desde a originação de grãos até a industrialização e comercialização de produtos para os mercados nacional e internacional.

Com forte presença no setor agroindustrial, a Caramuru se destaca pelo investimento em tecnologia, sustentabilidade e produção de biocombustíveis, contribuindo para o desenvolvimento do agronegócio brasileiro.'),
(566, 'A Ataplast Ambiental é uma empresa de consultoria e gestão ambiental localizada em Senador Canedo (GO), atuando desde 2008.

A companhia oferece soluções voltadas à coleta, transporte, tratamento e destinação de resíduos industriais e perigosos, além de atividades de reciclagem e recuperação de materiais metálicos. Também atua no comércio de sucatas e resíduos recicláveis, contribuindo para a sustentabilidade e a gestão ambiental de empresas.

Seu foco está em fornecer serviços ambientais que auxiliem indústrias e organizações no cumprimento das normas ambientais e na destinação adequada de resíduos.'),
(567, 'A Iron Mariano da Silva Catalano ME atua no segmento industrial e metalúrgico, especializada na fabricação, transformação e comercialização de produtos metálicos e na prestação de serviços relacionados à metalurgia e estruturas metálicas. A empresa desenvolve soluções voltadas ao atendimento das demandas dos setores industrial, comercial, agropecuário e da construção civil.

Entre suas principais atividades estão a fabricação de estruturas metálicas, peças sob medida, componentes industriais, serviços de soldagem, corte, montagem, manutenção e demais processos metalúrgicos, além da comercialização de produtos e materiais relacionados ao setor. A empresa atua com foco em qualidade, resistência, eficiência operacional, atendimento personalizado e desenvolvimento de soluções adequadas às necessidades de seus clientes e parceiros.'),
(568, 'Uma empresa sediada no Distrito Minero Industrial de Catalão, em Goiás. Ela atua principalmente na fabricação, comércio atacadista e fornecimento de gêneros alimentícios, atendendo demandas comerciais e contratos de fornecimento com órgãos públicos na região'),
(571, 'A empresa com a razão social Vilage Premium Industria e Comercio Ltda., tem o nome fantasia Cafe Catalao, opera com o CNPJ 33.580.697/0002-57 (33580697000257) e foi fundada em 20/08/2025. O endereço de sua sede está localizada na Rua Eixo 3, 750 - Distrito Minero Industrial de Catalao, Catalao - GO, 75.709-685. Sua atividade principal é de Torrefação e moagem de café, de acordo com o código CNAE C-1081-3/02.'),
(572, 'A empresa com a razão social Renato de Paiva Pereira, tem o nome fantasia Serralheria Aco Art, opera com o CNPJ 10.300.939/0001-25 (10300939000125) e foi fundada em 14/08/2008. O endereço de sua sede está localizada na Via Secundaria 02, Orizona - GO, 75.280-000. Sua atividade principal é de Fabricação de esquadrias de metal, de acordo com o código CNAE C-2512-8/00.'),
(573, 'A Mafra Imp., Ind. e Com. de Produtos Higiênicos EIRELI atua no segmento de higiene e limpeza, especializada na importação, fabricação, industrialização e comercialização de produtos higiênicos destinados aos mercados doméstico, comercial, institucional e industrial. A empresa desenvolve soluções voltadas à promoção da higiene, saúde, bem-estar e segurança dos usuários.

Entre suas principais atividades estão a fabricação, importação e distribuição de produtos de higiene pessoal, higiene institucional, limpeza e descartáveis, além da comercialização de insumos e materiais utilizados em ambientes residenciais, empresariais, hospitalares, educacionais e industriais. A empresa atende distribuidores, atacadistas, varejistas, empresas e órgãos públicos, oferecendo produtos que atendem às normas de qualidade e segurança.

A Mafra atua com foco em qualidade, inovação, eficiência operacional, conformidade regulatória, sustentabilidade e satisfação de seus clientes, buscando fornecer produtos que contribuam para a manutenção da higiene e da saúde em diferentes ambientes.'),
(575, 'Tintas Aquarela (Claudiney de Souza Peres Ltda) é uma empresa sediada em Catalão (GO), especializada na fabricação de tintas, vernizes, esmaltes e lacas para aplicação em diferentes segmentos da construção e manutenção.

Além da produção de tintas, a empresa também atua no comércio varejista de materiais de construção, oferecendo soluções para obras, reformas e acabamentos, com foco em qualidade e atendimento ao mercado regional.'),
(577, 'A LC Bufet atua no segmento de alimentação e eventos, especializada na prestação de serviços de buffet para eventos sociais, corporativos e institucionais. A empresa oferece soluções completas em gastronomia e organização de serviços de alimentação, atendendo diferentes tipos de celebrações e ocasiões com foco em qualidade, variedade e excelência no atendimento.

Entre suas principais atividades estão o preparo e fornecimento de refeições, coquetéis, coffee breaks, almoços, jantares, recepções, festas, casamentos, aniversários, eventos empresariais e institucionais, além da disponibilização de equipes de atendimento, estrutura e serviços de apoio para eventos. A empresa desenvolve cardápios personalizados de acordo com as necessidades e preferências de seus clientes.

A LC Bufet atua com foco em qualidade dos alimentos, segurança alimentar, organização, pontualidade, atendimento personalizado e satisfação dos clientes, oferecendo experiências gastronômicas que agregam valor aos eventos e contribuem para o sucesso de cada ocasião.'),
(578, 'A JN Cortes e Metais EIRELI – ME atua no segmento metalúrgico, especializada no processamento, corte, fabricação e comercialização de metais e componentes metálicos destinados aos setores industrial, comercial, agropecuário e da construção civil. A empresa desenvolve soluções voltadas à transformação de matérias-primas metálicas em produtos e peças que atendem às necessidades específicas de seus clientes.

Entre suas principais atividades estão os serviços de corte, dobra, soldagem e conformação de chapas metálicas, fabricação de estruturas metálicas, peças sob medida, componentes industriais e comercialização de materiais metálicos. A empresa também pode prestar serviços de acabamento e suporte técnico para projetos de diferentes portes.

A JN Cortes e Metais atua com foco em qualidade, precisão nos processos, eficiência produtiva, cumprimento de prazos, inovação e atendimento personalizado, oferecendo soluções que contribuem para a produtividade e o desenvolvimento de seus clientes e parceiros comerciais.'),
(584, 'A IC Transportes Ltda atua no segmento de logística e transporte rodoviário de cargas, especializada na movimentação, distribuição e gerenciamento de mercadorias para diversos setores da economia. A empresa desenvolve soluções logísticas voltadas à eficiência operacional, segurança no transporte e cumprimento de prazos, atendendo clientes dos segmentos industrial, comercial, agropecuário e de serviços.

Entre suas principais atividades estão o transporte rodoviário de cargas, logística de distribuição, armazenagem, movimentação de mercadorias, gestão de frotas, transporte de insumos e produtos acabados, além de serviços de apoio logístico. A empresa atua com foco em qualidade operacional, segurança, rastreabilidade, pontualidade e atendimento às necessidades específicas de seus clientes e parceiros comerciais.'),
(586, 'A Fórmula R Indústria e Comércio de Peças para Automóveis Ltda atua no segmento automotivo, especializada na fabricação, comercialização e distribuição de peças, componentes e acessórios destinados à manutenção e ao funcionamento de veículos. A empresa desenvolve soluções voltadas à qualidade, durabilidade e desempenho, atendendo às demandas do mercado de reposição automotiva e de manutenção veicular.

Entre suas principais atividades estão a produção e comercialização de peças automotivas, componentes mecânicos, acessórios para veículos, itens de reposição e soluções destinadas à manutenção de automóveis, veículos comerciais e utilitários. A empresa atua com foco em qualidade dos produtos, inovação, eficiência produtiva, confiabilidade e atendimento às necessidades de clientes, distribuidores e oficinas do setor automotivo.'),
(587, 'A Embrasatec Indústria e Comércio Têxtil Ltda atua no segmento têxtil, especializada na fabricação e comercialização de produtos têxteis e embalagens industriais. A empresa desenvolve soluções voltadas à produção de tecidos técnicos, embalagens flexíveis e materiais destinados a aplicações industriais, agrícolas, logísticas e comerciais, com foco em qualidade, resistência e eficiência produtiva.

Entre suas principais atividades estão a fabricação de tecidos de polipropileno, sacarias industriais, embalagens têxteis, big bags, fitas, alças e outros produtos voltados ao acondicionamento, transporte e armazenamento de mercadorias, além da comercialização e distribuição de soluções para os setores industrial, agrícola e logístico. A empresa atua com foco em inovação, qualidade dos processos produtivos, sustentabilidade e atendimento às necessidades específicas de seus clientes.'),
(588, 'A BWP Sistemas de Solda e Pintura Ltda é uma empresa especializada em soldagem, pintura industrial, usinagem e fabricação de componentes para a indústria automotiva. Com unidades em Catalão (GO) e São Paulo (SP), a companhia atua na produção de peças, estruturas metálicas, cabines, carrocerias e acessórios para veículos, além de serviços de tratamento e revestimento de metais.

A empresa atende principalmente o setor automotivo e industrial, oferecendo soluções de manufatura, montagem e acabamento de componentes metálicos, com foco em qualidade, eficiência produtiva e suporte às cadeias de produção de veículos e equipamentos.'),
(589, 'Dicebel Comércio e Serviços em Geral Ltda é uma empresa de Catalão (GO) especializada na distribuição atacadista de bebidas, incluindo cervejas, chopes, refrigerantes e outras bebidas, atendendo estabelecimentos comerciais e redes varejistas da região.

Além do setor de bebidas, a companhia atua na distribuição de produtos alimentícios, higiene e limpeza, bem como em serviços de transporte, armazenagem e logística. Com mais de 30 anos de atuação, a Dicebel se destaca como uma importante distribuidora regional, oferecendo soluções integradas para abastecimento e movimentação de mercadorias.'),
(590, 'A empresa Svb Automotores do Brasil LTDA de CNPJ 04.463.193/0001-78, foi fundada em 23/05/2001 na cidade Catalão no estado Goiás. Sua atividade principal, conforme a Receita Federal, é 29.10-7-01 - Fabricação de automóveis, camionetas e utilitários. Sua situação cadastral até o momento é Baixada.'),
(591, 'A Empresa Brasileira do Quartzo Ltda (EBQ) atua no segmento de mineração e beneficiamento de minerais não metálicos, especializada na extração e aproveitamento de quartzo para aplicações industriais. A empresa desenvolve soluções voltadas ao fornecimento de matéria-prima mineral de alta qualidade, atendendo setores como construção civil, indústria de transformação, materiais industriais e aplicações tecnológicas. Sua atividade principal está relacionada à extração e beneficiamento de quartzo em suas diversas variedades.

Entre suas principais atividades estão a extração de quartzo, beneficiamento e processamento mineral, atividades de apoio à mineração, desenvolvimento de projetos de engenharia relacionados às operações minerais e fornecimento de matéria-prima para aplicações industriais. A empresa atua com foco em qualidade, eficiência operacional, aproveitamento sustentável dos recursos minerais e atendimento às demandas dos mercados de mineração e transformação industrial.'),
(592, 'A HPE Automotores do Brasil Ltda atua no segmento automotivo, sendo a empresa responsável pela fabricação, importação, distribuição e comercialização de veículos das marcas Mitsubishi Motors e Suzuki no Brasil. A companhia desenvolve atividades voltadas à produção e comercialização de automóveis, picapes e veículos utilitários, atendendo consumidores, empresas e concessionárias em todo o país.

Entre suas principais atividades estão a montagem e fabricação de veículos automotores, importação de automóveis e peças, distribuição para a rede de concessionárias, comercialização de acessórios e componentes automotivos, além da prestação de suporte técnico, pós-venda e serviços relacionados ao setor automotivo. A empresa também opera unidades industriais no Brasil e participa ativamente do desenvolvimento do mercado nacional de veículos.

A HPE Automotores atua com foco em inovação tecnológica, qualidade, segurança, sustentabilidade, eficiência produtiva e excelência no atendimento aos clientes, contribuindo para o fortalecimento da indústria automotiva brasileira.'),
(593, 'A Fundação Espírita Nova Vida atua no segmento social, educacional e assistencial, desenvolvendo ações voltadas à promoção do bem-estar social, apoio comunitário e desenvolvimento humano. A instituição realiza atividades de caráter beneficente, educativo e solidário, buscando contribuir para a inclusão social e a melhoria da qualidade de vida das pessoas atendidas.

Entre suas principais atividades estão a realização de projetos sociais, ações assistenciais, programas educacionais, atividades de apoio a famílias em situação de vulnerabilidade, promoção de eventos comunitários, desenvolvimento de ações de caráter filantrópico e incentivo à formação humana e cidadã. A fundação atua com foco em responsabilidade social, solidariedade, inclusão, desenvolvimento comunitário e promoção de valores éticos e humanitários.'),
(595, 'A Já Revest atua no segmento de revestimentos e acabamentos para a construção civil, especializada na comercialização, distribuição e fornecimento de materiais destinados ao acabamento de ambientes residenciais, comerciais e industriais. A empresa oferece soluções voltadas à estética, funcionalidade e durabilidade de projetos arquitetônicos e de construção.

Entre suas principais atividades estão a venda de pisos, revestimentos cerâmicos, porcelanatos, pedras, acessórios para acabamento e materiais complementares para obras e reformas, além do atendimento e suporte na escolha de produtos adequados às necessidades de cada projeto. A empresa atua com foco em qualidade, variedade de produtos, inovação, atendimento especializado e satisfação de seus clientes e parceiros.'),
(598, 'INDUSTRIA COMERCIO E DISTRIBUICAO é CNPJ 41.515.566/0001-33. Com sede em CATALAO, GO, possui 5 anos, 2 meses e 15 dias e foi fundada em 09/04/2021. A sua situação cadastral é ATIVA e sua principal atividade econômica é Fabricação de artefatos de material plástico para uso pessoal e doméstico.'),
(601, 'A John Deere Brasil Ltda atua no segmento de máquinas e equipamentos para os setores agrícola, construção e florestal, sendo a subsidiária brasileira da John Deere, uma das maiores fabricantes de equipamentos do mundo. A empresa desenvolve, fabrica, comercializa e presta suporte a soluções tecnológicas voltadas ao aumento da produtividade e eficiência no campo e em operações de infraestrutura.

Entre suas principais atividades estão a fabricação e comercialização de tratores, colheitadeiras, plantadeiras, pulverizadores, equipamentos para construção, máquinas florestais, motores e peças de reposição, além da oferta de tecnologias de agricultura de precisão, conectividade, serviços financeiros e assistência técnica especializada. A empresa atende produtores rurais, empresas do agronegócio, construtoras e operadores florestais em todo o Brasil.

A John Deere Brasil atua com foco em inovação tecnológica, sustentabilidade, digitalização do campo, eficiência operacional e desenvolvimento de soluções que contribuam para o avanço da produtividade agrícola e da infraestrutura. A companhia é reconhecida mundialmente por seus investimentos em tecnologia, automação e agricultura de precisão, fortalecendo sua posição como referência no setor de máquinas e equipamentos.'),
(605, 'A Avícola Orizona Ltda é uma empresa brasileira do setor agroindustrial especializada na produção e comercialização de produtos avícolas, com atuação na criação, processamento e distribuição de aves e derivados.

A companhia atende o mercado alimentício, fornecendo produtos de origem avícola para distribuidores, varejistas e consumidores. Seu foco está na qualidade dos processos produtivos, segurança alimentar e eficiência na cadeia de produção.

Com forte atuação no agronegócio, a empresa contribui para o abastecimento do mercado de proteínas animais e para o desenvolvimento da cadeia avícola regional.'),
(606, 'A Barbosa Renovadora e Auto Center é uma empresa especializada em serviços automotivos e recapagem de pneus, atendendo veículos leves, caminhonetes, caminhões e máquinas agrícolas.

A companhia oferece serviços de alinhamento, balanceamento, manutenção de suspensão, conserto de pneus e outros serviços mecânicos, com foco em segurança, desempenho e durabilidade dos veículos. Atuando desde 1984, a empresa se destaca pela experiência e pela qualidade dos serviços prestados.'),
(609, 'A Engelektro Elétrica Ltda – ME atua no segmento de engenharia elétrica e eletromecânica, especializada na fabricação, instalação e manutenção de sistemas e equipamentos elétricos destinados aos setores industrial, comercial e de infraestrutura. A empresa desenvolve soluções voltadas à distribuição e controle de energia elétrica, buscando garantir segurança, eficiência operacional e confiabilidade em seus projetos.

Entre suas principais atividades estão a fabricação de quadros de comando e distribuição de energia, painéis elétricos, transformadores e equipamentos para controle elétrico, além da instalação e manutenção elétrica, montagem eletromecânica, manutenção de redes de distribuição de energia, serviços de engenharia elétrica, manutenção de máquinas e equipamentos industriais e comercialização de materiais elétricos. A empresa atua com foco em qualidade técnica, inovação, segurança e atendimento às necessidades específicas de seus clientes.'),
(613, 'DMR Estrutural (DMR Indústria, Comércio e Serviços Ltda) é uma empresa de Catalão (GO) especializada na fabricação de artefatos de cimento e fibrocimento para a construção civil, fornecendo soluções estruturais para obras residenciais, comerciais e de infraestrutura.

Além da produção de materiais construtivos, a empresa atua em construção civil, terraplenagem, urbanização, instalações elétricas e hidráulicas, transporte de cargas, locação de equipamentos e comércio de materiais de construção. Com mais de 20 anos de atuação, a DMR Estrutural oferece serviços integrados para projetos de engenharia e desenvolvimento urbano.'),
(614, 'A Caramuru Alimentos é uma das maiores empresas brasileiras do agronegócio, especializada no processamento de soja, milho e girassol, além da produção de óleos vegetais, farelos, biodiesel e ingredientes para as indústrias alimentícia e de nutrição animal.

Fundada em Goiás, a companhia atua em toda a cadeia agroindustrial, desde a originação de grãos até a industrialização e comercialização de produtos para os mercados nacional e internacional.

Com forte presença no setor agroindustrial, a Caramuru se destaca pelo investimento em tecnologia, sustentabilidade e produção de biocombustíveis, contribuindo para o desenvolvimento do agronegócio brasileiro.'),
(615, 'A Garra Indústria de Pré-Moldados EIRELI atua no segmento da construção civil, especializada na fabricação e comercialização de artefatos e estruturas pré-moldadas de concreto destinados a obras residenciais, comerciais, industriais e de infraestrutura. A empresa desenvolve soluções voltadas à agilidade construtiva, resistência estrutural e eficiência na execução de projetos.

Entre suas principais atividades estão a produção de peças pré-moldadas de concreto, blocos, vigas, pilares, lajes, tubos, meios-fios e outros componentes utilizados na construção civil, além da comercialização e fornecimento desses materiais para obras de diferentes portes. A empresa atua com foco em qualidade dos produtos, padronização de processos, inovação, durabilidade e atendimento às necessidades do setor da construção e infraestrutura.'),
(616, 'Com sede em CATALAO, GO, possui 21 anos, 6 meses e 9 dias e foi fundada em 15/12/2004. A sua situação cadastral é ATIVA e sua principal atividade econômica é Tecelagem de fios de algodão.'),
(617, 'Concrecat Premoldados de Concretos Ltda é uma empresa de Catalão (GO) especializada na fabricação de estruturas pré-moldadas de concreto armado, produzidas em série ou sob encomenda para obras da construção civil.

A companhia fornece soluções em concreto pré-moldado para empreendimentos residenciais, comerciais e industriais, além de atuar no transporte de cargas, contribuindo para a execução de projetos com agilidade, resistência e eficiência construtiva.'),
(619, 'A empresa Zamec de CNPJ 10.539.188/0001-02, fundada em 11/12/2008 e com razão social Zanotti Mecanica Industrial Ltda., está localizada na cidade Catalão do estado Goiás. Sua atividade principal, conforme a Receita Federal, é 78.20-5-00 - Locação de mão-de-obra temporária. Sua situação cadastral até o momento é Ativa'),
(620, 'A Marcos Container atua no segmento de fabricação e comercialização de containers e estruturas metálicas, especializada no desenvolvimento de soluções modulares para aplicações residenciais, comerciais, industriais e de infraestrutura. A empresa oferece produtos que aliam resistência, versatilidade e agilidade de instalação, atendendo às necessidades de diferentes tipos de projetos.

Entre suas principais atividades estão a fabricação, adaptação, reforma e comercialização de containers, módulos habitacionais, escritórios, almoxarifados, alojamentos, sanitários, guaritas e demais estruturas modulares, além da personalização de unidades conforme as especificações dos clientes. A empresa também pode prestar serviços de instalação, manutenção e transporte das estruturas.

A Marcos Container atua com foco em qualidade, inovação, eficiência, sustentabilidade, segurança e atendimento personalizado, desenvolvendo soluções modulares que proporcionam praticidade, economia e alto desempenho para diversos segmentos do mercado.'),
(622, 'A Cerâmica Catalão é uma empresa especializada na fabricação de materiais cerâmicos para a construção civil, produzindo itens como tijolos, blocos e outros artefatos utilizados em obras residenciais, comerciais e industriais.

A companhia atende construtoras, revendas de materiais de construção e clientes finais, oferecendo produtos voltados à qualidade, resistência e eficiência construtiva.

Com atuação no setor de construção civil, a Cerâmica Catalão contribui para o fornecimento de insumos essenciais para obras e projetos de infraestrutura na região.'),
(624, 'Com 38 anos de experiência em rotomoldagem técnica, a Resiplastic é referência nacional no desenvolvimento, produção e prestação de serviços de soluções em plásticos rotomoldados. Atendemos diversos segmentos com excelência, inovação e compromisso com a qualidade. Contamos com 5 plantas industriais estrategicamente distribuídas, o que nos permite alta capacidade produtiva, agilidade logística e flexibilidade para atender projetos personalizados, além de garantir contingência operacional, assegurando continuidade e confiabilidade nos atendimentos'),
(625, 'Com depósitos instalados em São Paulo, Betim, Uberlândia, Uberaba, Catalão e Vila Velha; Há mais de 40 anos transformando o meio ambiente através dos serviços de sustentabilidade metalúrgica, a companhia atua fortemente no processamento e destinação correta de materiais ferrosos e não ferrosos'),
(626, 'A Lajes Oliveira atua no segmento da construção civil, especializada na fabricação e comercialização de lajes e artefatos pré-moldados de concreto destinados a obras residenciais, comerciais, industriais e de infraestrutura. A empresa desenvolve soluções construtivas que proporcionam maior agilidade na execução das obras, resistência estrutural e otimização de custos.

Entre suas principais atividades estão a produção de lajes pré-moldadas, vigotas treliçadas, painéis, blocos de enchimento e outros elementos estruturais de concreto, além do fornecimento de materiais e suporte técnico para projetos de construção. A empresa atende construtoras, empreiteiras, profissionais da construção civil e consumidores finais.

A Lajes Oliveira atua com foco em qualidade dos produtos, conformidade técnica, durabilidade, eficiência produtiva, segurança estrutural e atendimento personalizado, oferecendo soluções que contribuem para o desempenho e a qualidade das obras de seus clientes e parceiros comerciais.'),
(627, 'A ATRHOL (A Transhol Equipamentos Hidráulicos) é uma empresa brasileira especializada na fabricação e manutenção de equipamentos hidráulicos, atendendo principalmente os setores industrial, agrícola e de transporte.

A companhia desenvolve soluções em sistemas hidráulicos, cilindros, comandos, bombas e componentes para máquinas e equipamentos, oferecendo também serviços de assistência técnica e manutenção especializada.

Com foco em qualidade e confiabilidade, a ATRHOL atua fornecendo tecnologias que contribuem para a eficiência e o desempenho de operações industriais e agrícolas.'),
(629, 'É uma transportadora brasileira especializada em logística e transporte rodoviário de produtos químicos perigosos à granel (sólidos, líquidos e gasosos). A empresa está há mais de três décadas no mercado e possui uma frota dedicada para esse segmento.'),
(630, 'A Castro Jacoub Construções Ltda é uma empresa brasileira especializada na execução de obras e serviços de construção civil, atuando em projetos residenciais, comerciais e industriais.

A companhia oferece soluções em construção, reforma e infraestrutura, atendendo clientes com foco em qualidade, segurança e cumprimento de prazos.

Com experiência no setor da construção civil, a empresa contribui para o desenvolvimento de empreendimentos e obras por meio de serviços voltados à engenharia e construção.'),
(631, 'Coacal (Cooperativa Agropecuária de Catalão Ltda.) é uma cooperativa agropecuária sediada em Catalão (GO), dedicada ao atendimento de produtores rurais por meio do fornecimento de insumos agrícolas, assistência técnica, armazenagem e comercialização da produção agropecuária.

A cooperativa atua como parceira do agronegócio regional, oferecendo soluções para as cadeias de grãos, pecuária e produção rural, contribuindo para o aumento da produtividade e o desenvolvimento sustentável dos seus cooperados.'),
(633, '(também conhecida como Quality Revestimentos Automotivo) foi uma empresa brasileira focada na fabricação de artefatos de tapeçaria automotiva'),
(634, 'A ADUCAT – Adubos Catalão é uma empresa goiana especializada na fabricação de fertilizantes e micronutrientes agrícolas, atendendo produtores rurais e empresas do agronegócio. Fundada em 1997, possui sede em Catalão (GO) e atua no desenvolvimento de soluções para nutrição vegetal, contando com laboratório próprio para análises de solo, folhas e minerais.

A empresa se destaca pelo foco em qualidade, pesquisa e inovação, fornecendo produtos voltados ao aumento da produtividade agrícola e atendendo diversas regiões do Centro-Oeste e do Brasil.'),
(637, 'Construtora Primarco Ltda é uma empresa do setor da construção civil e infraestrutura, atuando na construção de edifícios, empreendimentos imobiliários e obras de engenharia em geral.

A companhia também realiza serviços de terraplenagem, urbanização, obras de saneamento, alvenaria e administração de obras, atendendo projetos residenciais, comerciais e de infraestrutura pública e privada.'),
(638, 'A Hebert Agro é uma empresa brasileira do agronegócio especializada na comercialização de insumos agrícolas e nutrição vegetal.

A companhia oferece soluções para produtores rurais, incluindo fertilizantes, corretivos de solo e produtos voltados ao aumento da produtividade agrícola. Seu foco está em fornecer suporte técnico e tecnologias que contribuam para o desenvolvimento sustentável das lavouras.

Com atuação no setor agropecuário, a Hebert Agro atende principalmente produtores do Centro-Oeste, auxiliando na melhoria do desempenho e da rentabilidade das atividades agrícolas.'),
(639, 'É uma empresa agroindustrial sediada em Orizona, no estado de Goiás, com mais de 20 anos de tradição no agronegócio. O foco da empresa é a produção e o comércio atacadista de sementes certificadas para lavouras, oferecendo soluções de alta qualidade para produtores rurais'),
(641, 'A Brasmix Engenharia de Concreto S.A. é uma empresa brasileira especializada na produção e fornecimento de concreto usinado, argamassa e soluções para a construção civil.

A companhia atende obras residenciais, comerciais, industriais e de infraestrutura, oferecendo produtos desenvolvidos para garantir qualidade, resistência e eficiência nos processos construtivos.

Com foco em tecnologia, inovação e atendimento especializado, a Brasmix atua como parceira de construtoras e empreendimentos, contribuindo para a execução de projetos de diversos portes.'),
(642, 'A Cerâmica Orizona Ltda é uma empresa especializada na fabricação de produtos cerâmicos para a construção civil, produzindo materiais como tijolos, blocos e outros artefatos utilizados em obras residenciais, comerciais e industriais.

A companhia atende construtoras, revendas de materiais de construção e clientes finais, oferecendo produtos com foco em qualidade, resistência e durabilidade.

Com atuação no setor cerâmico, a Cerâmica Orizona contribui para o desenvolvimento da construção civil por meio do fornecimento de materiais essenciais para obras e projetos de infraestrutura.'),
(644, 'Fundada em 10/01/2011. A sua situação cadastral é BAIXADA e sua principal atividade econômica é Fabricação de móveis com predominância de madeira e serviços de montagem de móveis de qualquer material'),
(646, 'Líder no mercado de alimentos básicos, sendo referência nacional na industrialização e comercialização de arroz, feijão, café, açúcar, óleo de soja e sal refinado. Possui o Parque Industrial mais moderno do setor em todo o Brasil-Central, além de frota própria e centros de distribuição espalhados por todo o país. Uma das únicas do setor com gestão de qualidade reconhecida ISO 9001, também é referência em gestão de talentos e responsabilidade social e ambiental e foi fundada em 1985'),
(652, 'A Inovecar Indústria e Comércio atua no segmento industrial e automotivo, especializada na fabricação, montagem e comercialização de produtos, componentes e equipamentos destinados ao setor automotivo e a outras aplicações industriais. A empresa desenvolve soluções voltadas à eficiência, qualidade e inovação, atendendo às necessidades de fabricantes, distribuidores e consumidores.

Entre suas principais atividades estão a produção de peças, componentes, acessórios e equipamentos automotivos, além da comercialização e distribuição de produtos para manutenção, adaptação e operação de veículos e equipamentos industriais. A empresa também pode atuar no desenvolvimento de soluções sob medida, suporte técnico e fornecimento para diferentes segmentos do mercado.

A empresa atua com foco em qualidade, inovação tecnológica, eficiência produtiva, confiabilidade, atendimento especializado e satisfação de seus clientes e parceiros comerciais.'),
(653, '(CNPJ: 04.744.814/0001-91) é uma empresa brasileira sediada em Catalão, Goiás. Fundada em outubro de 2001, atua principalmente nos setores de produção de mudas e serviços paisagísticos.'),
(655, 'A Equipamentos Alimentícios Centro Oeste Ltda atua no segmento de fabricação e comercialização de máquinas e equipamentos para a indústria alimentícia, oferecendo soluções destinadas ao processamento, preparo, acondicionamento e beneficiamento de alimentos. A empresa atende frigoríficos, açougues, laticínios, panificadoras, agroindústrias e demais estabelecimentos do setor alimentício, com foco em eficiência, produtividade e qualidade operacional.

Entre suas principais atividades estão a fabricação e comercialização de masseiras, cilindros, cortadeiras, prensas, serras para ossos, moinhos de carne, máquinas para embutidos, equipamentos para abate animal, depenadeiras, depiladores, pasteurizadores, batedores industriais, descascadores, picadores, filtros e outros equipamentos destinados ao processamento de alimentos. A empresa atua com foco em inovação, durabilidade dos equipamentos, segurança operacional e atendimento às necessidades específicas da indústria alimentícia.'),
(657, 'A Evolução Serviços EIRELI atua no segmento de prestação de serviços, oferecendo soluções operacionais e de suporte para empresas, indústrias, órgãos públicos e empreendimentos de diversos setores. A empresa desenvolve atividades voltadas à execução de serviços especializados, contribuindo para a eficiência, organização e continuidade das operações de seus clientes.

Entre suas principais atividades estão a prestação de serviços de apoio administrativo, manutenção, conservação, limpeza, logística, apoio operacional, terceirização de mão de obra e execução de serviços especializados conforme as necessidades de cada contrato. A empresa atua com foco em qualidade, eficiência operacional, cumprimento de prazos, segurança e excelência no atendimento aos seus clientes.'),
(658, 'A Catalão Indústria, Serviços e Locações Ltda é uma empresa brasileira que atua nos segmentos de serviços industriais, locação de equipamentos e suporte operacional para indústrias e obras.

A companhia oferece soluções voltadas à manutenção, montagem, locação de máquinas e apoio a projetos industriais, atendendo principalmente os setores de construção, mineração e manufatura.

Com foco em eficiência e atendimento especializado, a empresa contribui para a execução de atividades industriais e de infraestrutura por meio de serviços técnicos e locação de equipamentos.'),
(659, 'A Evolução Metalúrgica Ltda atua no segmento metalúrgico, especializada na fabricação de estruturas, peças, equipamentos e implementos metálicos para aplicações industriais, agrícolas, automotivas e da construção civil. A empresa desenvolve soluções personalizadas voltadas à produtividade, qualidade e eficiência operacional, atendendo clientes de diversos setores com foco em inovação e precisão técnica.

Entre suas principais atividades estão a fabricação de peças e componentes metálicos, caldeiraria pesada, usinagem, tornearia, soldagem, tratamento e revestimento de metais, montagem industrial, fabricação de máquinas e implementos, desenvolvimento de projetos em 3D e manutenção industrial. A empresa atua com foco em qualidade dos processos produtivos, tecnologia, segurança, cumprimento de prazos e desenvolvimento de soluções sob medida para as necessidades de seus clientes.'),
(660, 'A Lactalis do Brasil – Comércio, Importação e Exportação de Laticínios Ltda atua no segmento alimentício, especializada na produção, industrialização, comercialização, importação e exportação de leite e derivados. Integrante do grupo Lactalis, a empresa está entre as maiores indústrias de laticínios do Brasil, atendendo o mercado nacional e internacional com um amplo portfólio de produtos.

Entre suas principais atividades estão a captação e processamento de leite, fabricação de queijos, leite UHT, leite em pó, manteiga, creme de leite, iogurtes, bebidas lácteas, requeijão, doce de leite e outros derivados, além da importação, exportação e distribuição de produtos alimentícios. A empresa abastece supermercados, atacadistas, distribuidores, estabelecimentos de alimentação e consumidores em todo o país.

A Lactalis do Brasil atua com foco em qualidade, segurança dos alimentos, inovação, sustentabilidade, eficiência operacional e desenvolvimento da cadeia leiteira, mantendo rigorosos padrões de controle de qualidade e contribuindo para o fortalecimento do setor de laticínios no Brasil.'),
(662, 'O CNPJ da empresa TRANSPORTE & COMERCIO QUINTA DO VALE LTDA - ME QUINTA DO VALE é 10.918.532/0001-66. Com sede em CATALAO, GO, possui 17 anos, 0 meses e 7 dias e foi fundada em 17/06/2009. A sua situação cadastral é ATIVA e sua principal atividade econômica é Transporte rodoviário de carga, exceto produtos perigosos e mudanças, intermunicipal, interestadual e internacional.'),
(663, 'A Jacinto Engenharia Indústria e Comércio Ltda – ME atua nos segmentos de engenharia, construção e fabricação industrial, especializada no desenvolvimento, execução e fornecimento de soluções para obras, estruturas e projetos técnicos. A empresa atende clientes dos setores industrial, comercial, agropecuário e da construção civil, oferecendo serviços e produtos voltados à eficiência, segurança e qualidade.

Entre suas principais atividades estão a execução de obras de engenharia, fabricação e montagem de estruturas metálicas, desenvolvimento de projetos técnicos, serviços de construção civil, manutenção industrial, fabricação de componentes e comercialização de materiais e equipamentos relacionados às suas áreas de atuação. A empresa atua com foco em qualidade técnica, cumprimento de prazos, inovação, segurança operacional e atendimento às necessidades específicas de seus clientes e parceiros.

Seu trabalho é direcionado para a entrega de soluções de engenharia e construção que contribuam para o desenvolvimento de empreendimentos e da infraestrutura, sempre observando padrões de qualidade, eficiência e responsabilidade profissional.'),
(667, 'A Cargill é uma das maiores empresas do agronegócio e da indústria de alimentos do mundo, atuando na originação, processamento e comercialização de grãos, ingredientes alimentícios, nutrição animal e produtos industriais. No Brasil, está presente desde 1965 e possui operações em diversos estados, incluindo unidades industriais, armazéns e terminais logísticos.

A companhia trabalha em toda a cadeia agroindustrial, fornecendo soluções para agricultores, indústrias alimentícias, produtores rurais e consumidores. Seu portfólio inclui óleos vegetais, ingredientes para alimentos, nutrição animal, biocombustíveis e serviços ligados ao comércio de commodities agrícolas.

Com forte atuação global, a Cargill se destaca pelo foco em inovação, sustentabilidade e eficiência logística, contribuindo para a produção e distribuição de alimentos e insumos agrícolas em larga escala.'),
(668, 'A Evolução Serviços EIRELI atua no segmento de prestação de serviços, oferecendo soluções operacionais e de suporte para empresas, indústrias, órgãos públicos e empreendimentos de diversos setores. A empresa desenvolve atividades voltadas à execução de serviços especializados, contribuindo para a eficiência, organização e continuidade das operações de seus clientes.

Entre suas principais atividades estão a prestação de serviços de apoio administrativo, manutenção, conservação, limpeza, logística, apoio operacional, terceirização de mão de obra e execução de serviços especializados conforme as necessidades de cada contrato. A empresa atua com foco em qualidade, eficiência operacional, cumprimento de prazos, segurança e excelência no atendimento aos seus clientes.'),
(669, 'A Terra Alta Empreendimentos e Serviços Ltda (CNPJ: 18.812.346/0001-50) é uma empresa sediada em Itumbiara, Goiás, fundada em setembro de 2013. Com situação cadastral ativa, ela atua principalmente no ramo de serviços agrícolas (preparação de terreno, cultivo e colheita)'),
(670, 'A AGIS Indústria e Comércio de Implementos Agrícolas é uma empresa brasileira especializada no desenvolvimento e fabricação de implementos e equipamentos para o agronegócio.

A companhia oferece soluções voltadas para o preparo do solo, plantio, cultivo e manejo agrícola, atendendo produtores rurais com foco em produtividade, eficiência operacional e inovação tecnológica.

Com atuação no setor agroindustrial, a AGIS se destaca pela fabricação de equipamentos robustos e adaptados às necessidades do campo, contribuindo para a modernização das operações agrícolas.'),
(672, 'A LCP Comércio Exterior Ltda atua no segmento de comércio exterior, especializada na importação, exportação e intermediação comercial de produtos destinados aos mercados nacional e internacional. A empresa oferece soluções voltadas à gestão de operações internacionais, contribuindo para a integração de empresas com fornecedores e clientes em diferentes países.

Entre suas principais atividades estão a importação e exportação de mercadorias, assessoria em operações de comércio exterior, gestão de processos aduaneiros, logística internacional, negociação com fornecedores e clientes, além da coordenação de embarques e do cumprimento das exigências regulatórias aplicáveis às operações internacionais. A empresa atende clientes de diversos segmentos econômicos, oferecendo suporte para a expansão de negócios no mercado global.

A LCP Comércio Exterior atua com foco em eficiência operacional, conformidade legal, qualidade dos serviços, agilidade nos processos, segurança nas operações e atendimento personalizado, contribuindo para o desenvolvimento das atividades de comércio internacional de seus clientes e parceiros comerciais.'),
(673, 'A Mamão Transportes Ltda atua no segmento de logística e transporte rodoviário de cargas, especializada na movimentação, coleta, distribuição e entrega de mercadorias para diversos setores da economia. A empresa oferece soluções logísticas voltadas à eficiência operacional, segurança das cargas e cumprimento de prazos, atendendo clientes dos segmentos industrial, comercial, agropecuário e de serviços.

Entre suas principais atividades estão o transporte rodoviário de cargas, logística de distribuição, coleta e entrega, armazenagem, gestão de frotas e operações logísticas, além do suporte às cadeias de suprimentos de seus clientes. A empresa busca desenvolver soluções adaptadas às características de cada operação, garantindo agilidade e confiabilidade no transporte.

A Mamão Transportes atua com foco em qualidade, pontualidade, segurança, eficiência operacional, rastreabilidade e atendimento personalizado, contribuindo para a otimização dos processos logísticos e para o fortalecimento das operações de seus clientes e parceiros comerciais.'),
(674, 'O CNPJ da empresa VIACAO VERONESE LTDA VIACAO VERONESE é 26.984.605/0008-24. Com sede em QUIRINOPOLIS, GO, possui 2 anos, 9 meses e 24 dias e foi fundada em 01/09/2023. A sua situação cadastral é ATIVA e sua principal atividade econômica é Transporte rodoviário coletivo de passageiros, sob regime de fretamento, municipal.'),
(675, 'Especializada na reforma, recapagem e manutenção de pneus agrícolas e de máquinas de terraplenagem. Voltada para grandes operações do agronegócio e usinas, ela atua estendendo a vida útil de pneus pesados, proporcionando economia direta ao produtor rural'),
(676, 'A Fortelha Indústria e Comércio de Telhas Ltda atua no segmento da construção civil, especializada na fabricação e comercialização de telhas destinadas a obras residenciais, comerciais e industriais. A empresa desenvolve soluções voltadas à qualidade, resistência e eficiência produtiva, atendendo às necessidades do mercado de coberturas e construção.

Entre suas principais atividades estão a produção, distribuição e comercialização de telhas e acessórios para coberturas, além do fornecimento de soluções para projetos construtivos e obras em geral. A empresa atua com foco em durabilidade dos produtos, padronização de processos, atendimento de qualidade e compromisso com a satisfação de seus clientes e parceiros comerciais.'),
(681, 'A Laticínios Centenários Ltda atua no segmento de laticínios, especializada na captação, processamento, industrialização e comercialização de leite e derivados, atendendo aos mercados varejista, atacadista e institucional. A empresa desenvolve produtos alimentícios com foco em qualidade, segurança dos alimentos e valorização da cadeia produtiva do leite.

Entre suas principais atividades estão o beneficiamento de leite, fabricação de queijos, manteiga, requeijão, creme de leite, leite pasteurizado, bebidas lácteas, iogurtes e outros derivados, além da embalagem, armazenamento, distribuição e comercialização de seus produtos. A empresa atende supermercados, distribuidores, estabelecimentos de alimentação e consumidores finais, seguindo rigorosos padrões de qualidade e controle sanitário.

A Laticínios Centenários atua com foco em boas práticas de fabricação, inovação, eficiência operacional, sustentabilidade, qualidade dos produtos e satisfação de seus clientes, contribuindo para o fortalecimento da indústria de laticínios e para o fornecimento de alimentos seguros e de elevado padrão ao mercado.'),
(690, 'A Indústria de Móveis Kers Ltda atua no segmento moveleiro, especializada na fabricação, industrialização e comercialização de móveis destinados aos mercados residencial, corporativo e comercial. A empresa desenvolve soluções que aliam funcionalidade, conforto, durabilidade e design, atendendo às necessidades de diferentes perfis de clientes e ambientes.

Entre suas principais atividades estão a fabricação de móveis em madeira, MDF e materiais derivados, produção de móveis planejados ou seriados, desenvolvimento de projetos de mobiliário, acabamento, montagem e comercialização de peças para residências, escritórios, lojas e demais espaços. A empresa atua com foco em qualidade dos materiais, inovação, eficiência produtiva, excelência nos acabamentos e satisfação de seus clientes e parceiros comerciais.'),
(695, 'A LCP Indústria e Comércio Ltda atua no segmento industrial, especializada na fabricação, industrialização e comercialização de produtos destinados aos setores industrial, comercial e de infraestrutura. A empresa desenvolve soluções voltadas à eficiência produtiva, qualidade e atendimento às necessidades específicas de seus clientes, oferecendo produtos que atendem aos padrões técnicos e de desempenho exigidos pelo mercado.

Entre suas principais atividades estão a fabricação de produtos e componentes industriais, processamento de matérias-primas, montagem, comercialização e distribuição de seus produtos, além da prestação de suporte técnico e desenvolvimento de soluções personalizadas para diferentes aplicações. A empresa atende clientes de diversos segmentos, contribuindo para o fortalecimento de cadeias produtivas e operações industriais.

A LCP Indústria e Comércio atua com foco em qualidade, inovação, eficiência operacional, melhoria contínua, conformidade técnica e satisfação de seus clientes e parceiros comerciais, buscando oferecer soluções confiáveis e competitivas para o mercado.'),
(698, 'A Jardinox Tanques Isotérmicos Ltda atua no segmento metalúrgico e de equipamentos industriais, especializada na fabricação, montagem e comercialização de tanques isotérmicos e equipamentos em aço inoxidável destinados ao armazenamento e transporte de líquidos e produtos que exigem controle de temperatura. A empresa atende principalmente os setores alimentício, agroindustrial, químico, de laticínios e transporte especializado.

Entre suas principais atividades estão a fabricação de tanques isotérmicos, reservatórios, silos, equipamentos em aço inox, carrocerias especiais, sistemas de armazenamento e transporte de produtos líquidos, além da manutenção e adaptação de equipamentos industriais. A empresa desenvolve soluções voltadas à conservação de produtos, segurança operacional, higiene e eficiência logística.

A Jardinox atua com foco em qualidade dos materiais, tecnologia de fabricação, conformidade técnica, durabilidade, inovação e atendimento às necessidades específicas de seus clientes e parceiros dos setores industrial e agropecuário.'),
(702, 'Fundada em 1986, a Usicamp possui 02 unidades industriais. A sede fica em Sarandi-PR, com mais de 100.000,00m² de área de terreno e aproximadamente 40.000m² de área construída, e filial em Itumbiara-GO, com mais de 75.000,00m² de área de terreno e aproximadamente 15.000m² de área construída. Atua na fabricação e fornecimento de diversos tipos de implementos rodoviários, com destaque nas linhas de equipamentos Canavieiros, Carrega Tudo, Basculante, Piso Móvel e Florestal'),
(710, 'A FR Adubos e Fertilizantes Ltda – ME atua no segmento do agronegócio, especializada na produção, comercialização e distribuição de fertilizantes, adubos e insumos destinados à nutrição vegetal e ao aumento da produtividade agrícola. A empresa desenvolve soluções voltadas ao manejo eficiente das culturas, à melhoria da fertilidade do solo e ao fortalecimento das atividades agrícolas.

Entre suas principais atividades estão a fabricação e comercialização de fertilizantes minerais e organominerais, adubos, corretivos de solo, condicionadores e produtos para nutrição vegetal, além da distribuição de insumos agrícolas e suporte às operações do setor agropecuário. A empresa atua com foco em qualidade dos produtos, eficiência agronômica, inovação, sustentabilidade e desenvolvimento de soluções que contribuam para a produtividade e rentabilidade no campo.'),
(713, 'A Camargo Química é uma empresa brasileira especializada na fabricação e comercialização de produtos químicos para limpeza, higienização e uso industrial.

A companhia desenvolve soluções para diversos segmentos, incluindo indústrias, empresas de serviços, comércios e instituições, oferecendo produtos voltados à limpeza profissional, saneantes e tratamento de superfícies.

Com foco em qualidade, inovação e eficiência, a Camargo Química atua fornecendo soluções que auxiliam na higiene, conservação e segurança de ambientes e processos produtivos.'),
(715, 'Com a razão social R.r Industria e Comercio de Paletes e Madeira Ltda, tem o nome fantasia R.r Industria de Paletes de Madeira, opera com o CNPJ 11.380.519/0001-69 (11380519000169) e foi fundada em 19/11/2009. O endereço de sua sede está localizada na Rua 1, 20 - Distrito Agroindustrial de Senador Canedo, Senador Canedo - GO, 75.252-300. Sua atividade principal é de Fabricação de artefatos de tanoaria e de embalagens de madeira, de acordo com o código CNAE C-1623-4/00.'),
(716, 'A Central de Tratamento de Resíduos Sólidos, Industriais e Comerciais de Chapecó Ltda (CTR Chapecó) é uma empresa especializada na gestão, tratamento e destinação de resíduos sólidos urbanos, industriais e comerciais.

A companhia atua na coleta, triagem, tratamento e disposição ambientalmente adequada de resíduos, oferecendo soluções para empresas e órgãos públicos. Seu foco está na sustentabilidade, conformidade ambiental e redução dos impactos causados pelos resíduos.

Com atuação no setor ambiental, a CTR Chapecó contribui para a gestão responsável de resíduos e para a preservação do meio ambiente por meio de serviços especializados de tratamento e destinação final.'),
(720, 'Fundada em 26/01/2005 e com razão social Real Telhas Brasil LTDA, está localizada na cidade Itumbiara do estado Goiás. Sua atividade principal, conforme a Receita Federal, é 41.20-4-00 - Construção de edifícios. Sua situação cadastral até o momento é Ativa'),
(725, 'A FR Nutran Animal Ltda atua no segmento de nutrição animal, especializada na fabricação, comercialização e distribuição de produtos destinados à alimentação e suplementação de animais. A empresa desenvolve soluções nutricionais voltadas ao desempenho produtivo, à saúde e ao bem-estar animal, atendendo às demandas da pecuária e de diferentes segmentos do setor agropecuário.

Entre suas principais atividades estão a produção de rações, suplementos minerais, concentrados, núcleos nutricionais e outros produtos para alimentação animal, além da distribuição e comercialização de insumos destinados à nutrição animal. A empresa atua com foco em qualidade nutricional, eficiência produtiva, inovação, sustentabilidade e desenvolvimento de soluções que contribuam para o aumento da produtividade e do desempenho dos rebanhos.'),
(733, 'A Globo Soluções Ambientais atua no segmento de gestão ambiental e sustentabilidade, especializada na prestação de serviços voltados ao gerenciamento de resíduos, controle ambiental e atendimento às exigências legais e operacionais de empresas e indústrias. A empresa desenvolve soluções que auxiliam na redução dos impactos ambientais e na adoção de práticas sustentáveis.

Entre suas principais atividades estão a coleta, transporte, tratamento e destinação final de resíduos, reciclagem e reaproveitamento de materiais, gerenciamento de efluentes, consultoria ambiental, elaboração de relatórios e projetos ambientais, além de serviços de apoio à regularização e conformidade ambiental. A empresa atua com foco em responsabilidade socioambiental, eficiência operacional, sustentabilidade, inovação e atendimento às necessidades de seus clientes em diferentes setores econômicos.'),
(734, 'Daniel Indústria e Comércio de Metais Ltda é uma empresa de Itumbiara (GO) especializada na recuperação, processamento e comercialização de materiais metálicos e sucatas, contribuindo para a reciclagem e reaproveitamento de metais na indústria.

A companhia também atua em atividades de metalurgia, fundição de ferro e aço, transporte de cargas e comércio atacadista de resíduos metálicos, oferecendo soluções para a cadeia de reciclagem e transformação de metais.'),
(737, 'Concretela Premoldados e Telas Ltda é uma empresa de Itumbiara (GO) que atua na fabricação de artefatos de cimento e produtos metálicos para a construção civil, oferecendo soluções em pré-moldados e telas para obras e instalações.

A companhia desenvolve atividades ligadas à construção e infraestrutura, atendendo demandas de projetos residenciais, comerciais e industriais com produtos voltados à resistência e praticidade construtiva.'),
(745, 'DRG Areias Formosa Ltda (DRG Areal) é uma empresa do setor de mineração especializada na extração e beneficiamento de areia, cascalho, pedregulho e argila, fornecendo matérias-primas essenciais para a construção civil e obras de infraestrutura.

Além das atividades de mineração, a empresa atua no transporte de cargas e na comercialização de materiais de construção, oferecendo suporte à cadeia produtiva da construção com foco no fornecimento de agregados minerais para diferentes tipos de projetos.'),
(750, 'Com sede em FRANCA, SP, possui 29 anos, 8 meses e 0 dias e foi fundada em 24/10/1996. A sua situação cadastral é inapta e sua principal atividade econômica é Serviços combinados de escritório e apoio administrativo'),
(753, 'A Maia Agrobusiness Ltda atua no segmento do agronegócio, oferecendo soluções integradas para atender às demandas dos setores agrícola e pecuário. A empresa é especializada na comercialização de insumos, no suporte técnico e no desenvolvimento de soluções que contribuem para o aumento da produtividade, da eficiência e da sustentabilidade das atividades rurais.

Entre suas principais atividades estão a comercialização de fertilizantes, sementes, defensivos agrícolas, corretivos de solo, produtos para nutrição vegetal e animal, além da prestação de assistência técnica e consultoria especializada. A empresa também pode atuar na comercialização de produtos agropecuários e no apoio às operações de produtores rurais e empresas do agronegócio.

A Maia Agrobusiness atua com foco em inovação, qualidade, sustentabilidade, eficiência operacional e atendimento personalizado, desenvolvendo parcerias com produtores e empresas para promover o fortalecimento da cadeia do agronegócio e o crescimento sustentável do setor.'),
(763, 'A BSA Bioenergia é uma empresa brasileira do setor sucroenergético especializada na produção de etanol, energia elétrica e subprodutos da cana-de-açúcar.

A companhia atua em toda a cadeia produtiva, desde o cultivo da cana até a industrialização, contribuindo para a geração de biocombustíveis e energia renovável. Além disso, aproveita os resíduos do processo produtivo para cogeração de energia, reforçando seu compromisso com a sustentabilidade.

Com foco em inovação e eficiência, a BSA Bioenergia desempenha um papel importante no agronegócio e no mercado de energias renováveis do Brasil.'),
(769, 'A empresa Udimix de CNPJ 40.674.404/0001-85, fundada em 02/02/2021 e com razão social Udimix Concreto LTDA, está localizada na cidade Itumbiara do estado Goiás. Sua atividade principal, conforme a Receita Federal, é 23.30-3-05 - Preparação de massa de concreto e argamassa para construção. Sua situação cadastral até o momento é Ativa.'),
(773, 'Empresa Solucao Agro-rural atua no ramo de Fabricação de outros produtos químicos não especificados anteriormente, com início das atividades em 06/05/2011 localizada em Itumbiara-GO e possui o CNPJ 13.602.795/0001-50. A empresa encontra-se Ativa com a data da última atualização cadastral em 06/05/2011.'),
(788, 'Foi fundada em 02/04/1992 na cidade Goiatuba no estado Goiás. Sua atividade principal, conforme a Receita Federal, é 20.13-4-02 - Fabricação de adubos e fertilizantes (exceto organo-minerais), transporte rodoviário de carga em geral, exceto de produtos perigosos e mudanças, dentro do município,  atividades de armazenamento e depósito, inclusive em câmaras frigoríficas e silos, de todo tipo de produto (sólidos, líquidos e gasosos), Sua situação cadastral até o momento é Ativa'),
(789, 'A Gersanti e Carvalho Indústria e Comércio Ltda – G&C Estruturas atua no segmento metalúrgico e da construção civil, especializada na fabricação, montagem e comercialização de estruturas metálicas destinadas a obras residenciais, comerciais, industriais e de infraestrutura. A empresa desenvolve soluções voltadas à resistência, segurança e eficiência construtiva, atendendo projetos de diferentes portes e complexidades.

Entre suas principais atividades estão a fabricação de estruturas metálicas, galpões, coberturas, mezaninos, suportes, peças metálicas sob medida e serviços de montagem e instalação, além do fornecimento de soluções estruturais para empreendimentos diversos. A empresa atua com foco em qualidade dos materiais, precisão técnica, inovação, cumprimento de prazos e excelência na execução de seus projetos e serviços.'),
(794, 'A Durini Indústria e Comércio de Móveis Ltda atua no segmento moveleiro, especializada na fabricação, comercialização e distribuição de móveis destinados a ambientes residenciais, comerciais e corporativos. A empresa desenvolve soluções que combinam funcionalidade, conforto e design, atendendo às necessidades de diferentes perfis de clientes e projetos de mobiliário.

Entre suas principais atividades estão a produção de móveis para dormitórios, salas, cozinhas, escritórios e demais ambientes, além da comercialização, distribuição e fornecimento de soluções em mobiliário para o mercado varejista e corporativo. A empresa atua com foco em qualidade dos materiais, eficiência produtiva, inovação, acabamento e satisfação de seus clientes e parceiros comerciais.'),
(797, 'É uma empresa brasileira líder na fabricação de dermocosméticos, medicamentos isentos de prescrição (MIPs), adoçantes e suplementos, sendo uma subsidiária integral da Hypera S.A.. Sediada em Barueri (SP), possui grandes complexos industriais em Goiânia e Anápolis (GO), produzindo marcas conhecidas'),
(799, 'A Fertilizantes Motta Ltda atua no segmento do agronegócio, especializada na produção, comercialização e distribuição de fertilizantes, corretivos de solo e insumos agrícolas destinados ao aumento da produtividade e ao desenvolvimento sustentável das lavouras. A empresa atende produtores rurais e empresas do setor agrícola, oferecendo soluções voltadas à nutrição vegetal e ao manejo eficiente das culturas.

Entre suas principais atividades estão a fabricação e comercialização de fertilizantes, adubos e corretivos de solo, o comércio atacadista de insumos agrícolas, matérias-primas para produção agrícola e soluções para nutrição vegetal, além do suporte às operações do agronegócio. A empresa atua com foco em inovação, qualidade dos produtos, eficiência agronômica, sustentabilidade e desenvolvimento de soluções que contribuam para o aumento da produtividade no campo.'),
(800, 'A Livié Produtos Farmacêuticos e Nutricionais Ltda atua no segmento farmacêutico e de nutrição, especializada no desenvolvimento, fabricação, comercialização e distribuição de produtos farmacêuticos, nutracêuticos e suplementos nutricionais. A empresa oferece soluções voltadas à promoção da saúde, bem-estar e qualidade de vida, atendendo às necessidades de profissionais da saúde, distribuidores e consumidores.

Entre suas principais atividades estão a produção e comercialização de medicamentos, suplementos alimentares, vitaminas, minerais, compostos nutricionais, produtos para nutrição especializada e outros itens destinados ao cuidado da saúde, além da pesquisa, desenvolvimento e inovação de formulações que atendam aos padrões regulatórios e às demandas do mercado.

A Livié Produtos Farmacêuticos e Nutricionais atua com foco em qualidade, segurança, inovação, conformidade com as normas sanitárias, boas práticas de fabricação e excelência operacional, buscando oferecer produtos eficazes e confiáveis que contribuam para a saúde e o bem-estar de seus clientes e consumidores.'),
(802, 'A Boa Safra Fertilizantes é uma empresa brasileira especializada na produção e comercialização de fertilizantes e insumos agrícolas, atendendo produtores rurais de diferentes culturas.

A companhia oferece soluções para nutrição vegetal e manejo do solo, contribuindo para o aumento da produtividade e da eficiência das lavouras. Seu foco está em fornecer produtos de qualidade e suporte técnico para o agronegócio.

Com atuação voltada ao setor agrícola, a Boa Safra Fertilizantes busca apoiar o desenvolvimento sustentável da produção rural por meio de tecnologias e insumos para o campo.'),
(804, 'Pront Loc (Construloc Ltda) é uma empresa especializada na locação de máquinas e equipamentos para construção civil, atendendo obras de pequeno, médio e grande porte em Goiânia e região.

Além do aluguel de equipamentos, a companhia atua em serviços de terraplenagem, fundações, manutenção de máquinas e logística, oferecendo soluções de apoio para os setores da construção civil e infraestrutura.'),
(808, 'Empresa que está localizada no município de Senador Canedo/GO e cuja data de abertura é 20/03/2012, estando atualmente com sua situação cadastral Ativa na Receita Federal. Sua atividade econômica principal é "fornecimento de alimentos preparados preponderantemente para empresas", a qual corresponde ao código de Classificação Nacional de Atividades Econômicas (CNAE) nº 5620-1/01'),
(812, 'A FR Reis Empreendimentos Indústria e Comércio Unipessoal Ltda atua no segmento industrial e comercial, especializada no desenvolvimento, fabricação, comercialização e distribuição de produtos destinados a diferentes setores do mercado. A empresa desenvolve soluções voltadas à eficiência operacional, qualidade dos processos e atendimento às necessidades de clientes comerciais, industriais e corporativos.

Entre suas principais atividades estão a industrialização, beneficiamento, comercialização e distribuição de produtos, além da gestão de empreendimentos, desenvolvimento de soluções empresariais e suporte às operações de seus clientes. A empresa atua com foco em inovação, qualidade, organização operacional, crescimento sustentável e excelência no fornecimento de produtos e serviços.'),
(813, 'Fundada em 11/12/1996 e com razão social Versatil Banheiras LTDA, está localizada na cidade Senador Canedo do estado Goiás. Sua atividade principal, conforme a Receita Federal, é 31.03-9-00 - Fabricação de móveis de outros materiais, exceto madeira e metal. Sua situação cadastral até o momento é Ativa.'),
(814, 'Sede em SENADOR CANEDO, GO, possui 11 anos, 8 meses e 22 dias e foi fundada em 26/09/2014. A sua situação cadastral é ATIVA e sua principal atividade econômica é Tratamento e Disposição de Resíduos Não-Perigosos.'),
(817, '(frequentemente listada como Qvida Industrial Eireli ou Qvida Industrial - ME) é uma indústria química localizada na região metropolitana de Goiânia, no município de Senador Canedo (GO). A empresa atua principalmente no segmento de fabricação de sabões e detergentes sintéticos.'),
(819, 'A Rodocon Construções Rodoviárias é uma empresa familiar brasileira, privada, que atua há mais de 60 anos em âmbito nacional, nos segmentos de construção, manutenção e restauração de rodovias; de conservação de áreas verdes, e de coleta, transporte e tratamento de resíduos.'),
(830, 'A Indústria de Postes Wilian atua no segmento de artefatos de concreto e infraestrutura, especializada na fabricação e comercialização de postes e estruturas destinadas aos setores de energia elétrica, telecomunicações, iluminação pública e construção civil. A empresa desenvolve produtos voltados à segurança, durabilidade e atendimento às especificações técnicas exigidas pelo mercado.

Entre suas principais atividades estão a fabricação de postes de concreto, estruturas pré-moldadas, peças para redes de distribuição elétrica, suportes para telecomunicações e outros artefatos de concreto utilizados em obras de infraestrutura. A empresa atua com foco em qualidade, resistência estrutural, conformidade técnica, eficiência produtiva e atendimento às necessidades de concessionárias, empresas de engenharia, construtoras e órgãos públicos.'),
(832, 'Com sede em SENADOR CANEDO, GO, possui 14 anos, 9 meses e 23 dias e foi fundada em 02/09/2011. A sua situação cadastral é ATIVA e sua principal atividade econômica é Fabricação de aparelhos eletromédicos e eletroterapêuticos e equipamentos de irradiação,  Manutenção e reparação de máquinas e equipamentos para uso geral não especificados anteriormente,  Transporte rodoviário de carga, exceto produtos perigosos e mudanças, municipal.'),
(833, 'Desde sua fundação, Martins e Teixeira ergueu-se como um gigante, enfrentando os desafios dos temas mais intrincados do Direito Público com destemor e alcançando o sucesso com uma determinação inabalável. Sua meta e tornar-se o maior escritório de direito público do país, sua atividade princital e  um escritório jurídico brasileiro de destaque com sede em São Paulo'),
(836, 'Demazon Cosméticos da Amazônia Ltda é uma empresa de Senador Canedo (GO) especializada na fabricação de cosméticos, produtos de perfumaria e itens de higiene pessoal, atendendo tanto o mercado consumidor quanto canais de distribuição e revenda.

Além da produção industrial, a companhia atua no comércio atacadista e varejista de cosméticos e produtos de higiene, oferecendo soluções para marcas, distribuidores e varejistas. Também realiza serviços de envase e empacotamento sob contrato, ampliando sua atuação na cadeia de produção do setor de cosméticos.'),
(854, 'Complem (Cooperativa Mista dos Produtores de Leite de Morrinhos) é uma cooperativa agroindustrial goiana com forte atuação na captação e industrialização de leite, produzindo derivados lácteos como leite UHT, leite em pó, manteiga, queijos e bebidas lácteas.

A cooperativa reúne produtores rurais e oferece soluções para toda a cadeia leiteira, desde assistência ao campo até a industrialização e distribuição dos produtos. Com décadas de atuação, a Complem é uma das principais referências do setor lácteo em Goiás, contribuindo para o desenvolvimento do agronegócio e da indústria alimentícia da região.'),
(892, 'A empresa Velgo de CNPJ 26.651.018/0001-47, fundada em 06/06/1990 e com razão social Velgo Industria e Comercio de Moveis LTDA, está localizada na cidade Aparecida de Goiânia do estado Goiás. Sua atividade principal, conforme a Receita Federal, é 31.02-1-00 - Fabricação de móveis com predominância de metal. Sua situação cadastral até o momento é Suspensa.'),
(897, 'Uma empresa com CNPJ 10.847.534/0001-01 sediada em Aparecida de Goiânia/GO, no bairro Distrito Agroindustrial de Aparecida de Goiania, em atividade desde 08/05/2009. Atua no ramo de 38.21-1-00 - Tratamento e disposição de resíduos não-perigosos, que compreende: - a operação de depósitos de lixo e aterros sanitários para a disposição de resíduos não-perigosos - a eliminação de resíduos não-perigosos pela combustão ou incineração, com ou sem o objetivo de geração de eletricidade .... Situação cadastral: Ativa.'),
(898, 'A Alpfilm é uma empresa brasileira especializada na fabricação de embalagens plásticas flexíveis, atendendo setores como alimentos, agronegócio, indústria e comércio.

A companhia desenvolve soluções em filmes plásticos e embalagens personalizadas, com foco em qualidade, inovação e proteção de produtos durante armazenamento e transporte.

Com atuação no mercado nacional, a Alpfilm se destaca pelo investimento em tecnologia e processos produtivos voltados à eficiência e sustentabilidade, fornecendo embalagens para diversos segmentos industriais.'),
(915, 'O CNPJ da empresa TALISMA TRANSPORTES E LOGISTICA LTDA - ME TALISMA TRANSPORTES é 19.781.645/0002-18. Com sede em RONDONOPOLIS, MT, possui 7 anos, 0 meses e 12 dias e foi fundada em 12/06/2019. A sua situação cadastral é ATIVA e sua principal atividade econômica é Transporte rodoviário de produtos perigosos')
ON DUPLICATE KEY UPDATE descricao = VALUES(descricao);
