SET NAMES utf8mb4;
-- Descricoes das empresas extraidas das planilhas.
-- Atualiza descricao sem sobrescrever imagens existentes.
INSERT INTO empresa_infos (empresa_id, descricao, caminho_imagem) VALUES
(5, 'A empresa Sun Foods Agroindustrial Centro Oeste LTDA de CNPJ 03.620.558/0001-68, foi fundada em 28/01/2000 na cidade Inhumas no estado Goiás. Sua atividade principal, conforme a Receita Federal, é 10.95-3-00 - Fabricação de especiarias, molhos, temperos e condimentos, atividades relacionadas com a pecuária realizadas sob contrato, não especificadas anteriormente. Sua situação cadastral até o momento é Ativa.', NULL),
(7, 'A Indústria e Comércio Café Goianésia Ltda atua no segmento alimentício, especializada no beneficiamento, industrialização, torrefação, moagem e comercialização de café e produtos relacionados. A empresa desenvolve atividades voltadas à produção de cafés de qualidade para abastecimento do mercado varejista, atacadista e institucional.

Entre suas principais atividades estão a seleção e processamento de grãos de café, torrefação, moagem, empacotamento, comercialização e distribuição de café torrado e moído, além do fornecimento de produtos destinados ao consumo doméstico e comercial. A empresa atua com foco em qualidade, padronização dos processos, sabor, segurança alimentar, eficiência produtiva e satisfação de seus clientes e consumidores.', NULL),
(9, 'A GSV Montagens Indústria Ltda atua no segmento industrial, especializada na fabricação, montagem e instalação de estruturas, equipamentos e sistemas destinados a aplicações industriais. A empresa desenvolve soluções voltadas à implantação, manutenção e modernização de unidades produtivas, atendendo diversos setores com foco em eficiência operacional, segurança e qualidade técnica.

Entre suas principais atividades estão a montagem eletromecânica, fabricação e montagem de estruturas metálicas, instalação de equipamentos industriais, tubulações, caldeiraria, soldagem, manutenção industrial e apoio à execução de projetos de engenharia. A empresa atua com foco em qualidade dos serviços, cumprimento de prazos, segurança do trabalho, inovação e atendimento às necessidades específicas de seus clientes e parceiros.', NULL),
(11, 'Sua atividade principal é a fabricação de sisdemas de despoiramento, silos de armazenamento de farinha e cauderaria industrial pesada. Aplicáveis em diversas obras de engenharia possui 21 anos, 8 meses e 28 dias e foi fundada em 14/09/2004', NULL),
(12, 'A Greca Distribuidora de Asfaltos Ltda. atua no segmento de infraestrutura e pavimentação, especializada na produção, distribuição e comercialização de produtos asfálticos destinados à construção, conservação e recuperação de rodovias, vias urbanas e obras de infraestrutura. A empresa integra o grupo Greca Asfaltos e é referência nacional no fornecimento de soluções para pavimentação e engenharia rodoviária.

Entre suas principais atividades estão a produção e distribuição de cimento asfáltico de petróleo (CAP), emulsões asfálticas, asfaltos modificados por polímeros, ligantes especiais, produtos para impermeabilização e insumos destinados à pavimentação. A empresa também oferece suporte técnico para aplicação de seus produtos e desenvolvimento de soluções voltadas à durabilidade e ao desempenho das obras viárias.

A Greca atua com foco em inovação tecnológica, qualidade, sustentabilidade, eficiência logística e desenvolvimento de soluções que contribuam para a segurança, a mobilidade e a modernização da infraestrutura de transportes no Brasil.', NULL),
(14, 'A Solve Engenharia e Soluções Ltda é uma empresa comprometida com a transparência e a honestidade em suas relações com clientes e fornecedores. Ela atua na fabricação de obras de caldeiraria pesada e busca constantemente melhorar seus produtos e serviços para atender às necessidades dos clientes. A empresa valoriza a satisfação do cliente e oferece serviços personalizados, garantindo altos padrões de qualidade e inovação. Além disso, a Solve é reconhecida por sua dedicação à excelência e pela qualidade em todos os projetos que empreende', NULL),
(18, 'A JM Paletes Empreendimentos de Madeira Ltda atua no segmento madeireiro e de logística, especializada na fabricação, recuperação e comercialização de paletes, embalagens de madeira e estruturas utilizadas para armazenamento, movimentação e transporte de mercadorias. A empresa atende clientes dos setores industrial, comercial, agrícola e de distribuição, oferecendo soluções voltadas à eficiência logística e à proteção de cargas.

Entre suas principais atividades estão a produção de paletes de madeira, caixas, engradados, estrados e embalagens industriais, além da recuperação, manutenção e reutilização de paletes. A empresa também pode fornecer soluções personalizadas para acondicionamento e transporte de produtos, adequadas às necessidades específicas de cada cliente.

A JM Paletes atua com foco em qualidade dos materiais, resistência, sustentabilidade, eficiência operacional, aproveitamento de recursos e atendimento às demandas logísticas de seus clientes e parceiros comerciais.', NULL),
(19, 'Talisma Colors Ltda é uma empresa de Goianésia (GO) especializada em montagem industrial, serviços de engenharia e manutenção para os setores industrial e da construção civil.

A companhia também atua em instalações elétricas e hidráulicas, pintura industrial, tratamento e revestimento de metais, locação de equipamentos e administração de obras, oferecendo soluções integradas para projetos industriais e de infraestrutura.', NULL),
(36, 'Fundada em 16/02/2004 e com razão social Sc Industria de Bolsas LTDA, está localizada na cidade Goianira do estado Goiás. Sua atividade principal, conforme a Receita Federal, é 15.21-1-00 - Fabricação de artigos para viagem, bolsas e semelhantes de qualquer material. Sua situação cadastral até o momento é Ativa', NULL),
(37, 'A Alumínios Kelly é uma empresa goiana especializada na fabricação de utensílios e artigos de alumínio para uso doméstico, com atuação desde 1998. Localizada em Goianira (GO), a empresa produz itens metálicos voltados para cozinha e uso residencial, atendendo o mercado regional com foco em qualidade e durabilidade.

Com mais de duas décadas de atuação, a Alumínios Kelly se destaca no segmento de transformação de alumínio e fabricação de produtos metálicos para o dia a dia.', NULL),
(39, 'Fundada em 17/05/2021 e com razão social Prosorvt Industria e Comercio LTDA, Sua situação cadastral até o momento é Ativa e  Sua atividade principal é de Fabricação de pós-alimentícios, de acordo com o código CNAE C-1099-6/02', NULL),
(41, 'A Líder Botas Ltda atua no segmento calçadista, especializada na fabricação, industrialização e comercialização de botas e calçados destinados aos setores de segurança, trabalho, agronegócio, indústria, construção civil e uso cotidiano. A empresa desenvolve produtos que aliam conforto, resistência, durabilidade e proteção, atendendo às exigências de diferentes atividades profissionais e condições de uso.

Entre suas principais atividades estão a fabricação de botas de segurança, botas de PVC, calçados ocupacionais, calçados impermeáveis e outros equipamentos de proteção para os pés, além da comercialização e distribuição de seus produtos para revendedores, distribuidores, empresas e consumidores finais. A empresa atua em conformidade com normas técnicas e de segurança aplicáveis ao setor.

A Líder Botas atua com foco em qualidade, inovação, segurança, eficiência produtiva, conforto e satisfação de seus clientes, oferecendo soluções que contribuem para a proteção dos trabalhadores e o desempenho das atividades profissionais em diversos segmentos da economia.', NULL),
(44, 'A Selecta Plasticos, cuja razão social é Selecta Plasticos Industria e Comercio LTDA, é uma empresa de CNPJ 09.153.157/0001-21 com sede na cidade de Goianira no estado Goiás, constituída em 22/10/2007. Atua principalmente em 22.29-3-01 - Fabricação de artefatos de material plástico para uso pessoal e doméstico. Enquadrada como Micro Empresa, natureza jurídica Sociedade Empresária Limitada. Encontra-se atualmente com situação Ativa na Receita Federal.', NULL),
(45, 'Tamben conhecida comercialmente como Sacarias Jotaplastico é uma indústria sediada na região de Goianira/Goiânia especializada na fabricação e comercialização de embalagens e sacarias de ráfia', NULL),
(47, 'A Jairo Xavier da Costa – JM Alumínios EIRELI atua no segmento de esquadrias e produtos de alumínio, especializada na fabricação, montagem e comercialização de estruturas e componentes destinados à construção civil. A empresa desenvolve soluções que combinam resistência, durabilidade, funcionalidade e acabamento, atendendo obras residenciais, comerciais e industriais.

Entre suas principais atividades estão a fabricação e instalação de portas, janelas, fachadas, divisórias, portões, guarda-corpos, esquadrias e demais estruturas em alumínio, além da comercialização de acessórios e componentes relacionados ao setor. A empresa também presta serviços de medição, montagem e acabamento para projetos sob medida.

A JM Alumínios atua com foco em qualidade dos materiais, precisão na execução, inovação, atendimento personalizado e satisfação de seus clientes, oferecendo soluções que contribuem para a valorização e funcionalidade dos empreendimentos.', NULL),
(48, 'Também conhecida pelo nome fantasia Incinera Tratamento de Resíduo é uma empresa especializada em gestão integrada e incineração de resíduos (Classe I e II): Segregação, armazenamento temporário e logística, garantindo rastreabilidade e compliance ambiental , A sua planta industrial está localizada no Distrito Agroindustrial de Senador Canedo, na Região Metropolitana de Goiânia, GO', NULL),
(49, 'A Indústria de Alumínios Progresso Ltda atua no segmento metalúrgico, especializada na fabricação, industrialização e comercialização de produtos e artefatos em alumínio destinados aos setores da construção civil, industrial, comercial e residencial. A empresa desenvolve soluções que combinam resistência, leveza, durabilidade e acabamento de qualidade.

Entre suas principais atividades estão a produção de esquadrias de alumínio, portas, janelas, perfis, estruturas metálicas leves, componentes para construção civil e outros artefatos fabricados em alumínio, além da comercialização e distribuição desses produtos. A empresa atua com foco em qualidade dos materiais, inovação, eficiência produtiva, precisão nos acabamentos e atendimento às necessidades específicas de seus clientes e parceiros comerciais.', NULL),
(50, 'A Carboquima é uma empresa brasileira especializada na produção e comercialização de carvão vegetal, biomassa e soluções energéticas para a indústria.

A companhia atua no fornecimento de insumos energéticos para setores como siderurgia, metalurgia e indústrias em geral, com foco em eficiência produtiva e sustentabilidade. Seus processos buscam aliar desempenho energético à responsabilidade ambiental.

Com experiência no setor, a Carboquima contribui para a cadeia industrial por meio de produtos voltados à geração de energia térmica e redução de impactos ambientais.', NULL),
(51, 'A Alumínio W. Nissei Ltda é uma empresa brasileira localizada em Senador Canedo (GO), especializada na fabricação e comercialização de esquadrias, estruturas e produtos de alumínio.

A companhia atende os setores da construção civil e industrial, oferecendo soluções em alumínio para projetos residenciais, comerciais e corporativos. Seu foco está na qualidade dos produtos, durabilidade e atendimento às necessidades de cada projeto.', NULL),
(53, 'A Calçados Aryetta Ltda é uma empresa brasileira especializada na fabricação de calçados femininos, atuando no desenvolvimento e produção de produtos voltados para moda, conforto e estilo.

A companhia atende o mercado de vestuário e acessórios, produzindo calçados para diferentes perfis de consumidoras e acompanhando tendências do setor. Seu foco está na qualidade dos materiais, acabamento e design dos produtos.

Com atuação no segmento calçadista, a Aryetta contribui para a indústria da moda nacional por meio da fabricação e comercialização de calçados.', NULL),
(54, 'A Goyazes Indústria e Comércio de Calçados EIRELI atua no segmento calçadista, especializada na fabricação e comercialização de botas, calçados e acessórios voltados principalmente para os setores agropecuário, country e de moda. A empresa desenvolve produtos que combinam conforto, durabilidade, qualidade artesanal e design, atendendo consumidores em todo o território nacional.

Entre suas principais atividades estão a produção de botas de couro, calçados masculinos e femininos, acessórios e artigos relacionados ao vestuário country, além da comercialização e distribuição de seus produtos para lojas, revendedores e consumidores finais. A empresa atua com foco em qualidade dos materiais, acabamento, inovação, tradição artesanal e satisfação de seus clientes, consolidando sua presença no mercado de calçados e artigos country.', NULL),
(55, 'A Alta Cosmética Indústria, Comércio, Importação e Exportação Ltda é uma empresa brasileira especializada na fabricação de cosméticos, produtos de higiene pessoal e perfumaria.

Localizada em Goiás, a companhia atua no desenvolvimento, produção e comercialização de produtos voltados aos cuidados pessoais, beleza e bem-estar, atendendo o mercado nacional com soluções para diferentes segmentos do setor cosmético.

A empresa também realiza atividades de importação e exportação, ampliando sua atuação no mercado de cosméticos e produtos de higiene.', NULL),
(56, 'A Maqna Misturadores Ltda atua no segmento de máquinas e equipamentos industriais, especializada no desenvolvimento, fabricação e comercialização de misturadores e equipamentos para processos produtivos. A empresa atende indústrias de diversos segmentos, oferecendo soluções voltadas à mistura, homogeneização e processamento de matérias-primas com eficiência, precisão e confiabilidade.

Entre suas principais atividades estão a fabricação de misturadores industriais, agitadores, sistemas de dosagem, tanques de processamento e outros equipamentos destinados às indústrias alimentícia, química, farmacêutica, cosmética, de mineração, de fertilizantes e de outros setores produtivos. A empresa também desenvolve projetos personalizados, presta assistência técnica, manutenção e suporte aos seus clientes.

A Maqna Misturadores atua com foco em inovação, qualidade, tecnologia, eficiência operacional, segurança e atendimento especializado, desenvolvendo equipamentos que contribuem para a produtividade, a padronização dos processos industriais e a competitividade de seus clientes.', NULL),
(57, 'Fundada em 12/11/2007 e com razão social Stampo Metalurgica LTDA, está localizada na cidade Goianira do estado Goiás. Sua atividade principal, conforme a Receita Federal, é 25.32-2-01 - Produção de artefatos estampados de metal,fabricação de máquinas para agricultura e fabricação de máquinas e equipamentos para a indústria da madeira', NULL),
(58, 'A Eletro Quadros Metalúrgica Ltda atua no segmento metalúrgico, especializada na fabricação de artefatos metálicos, estruturas metálicas e equipamentos destinados a aplicações industriais. A empresa desenvolve soluções voltadas à produção de componentes metálicos e equipamentos sob medida, atendendo às necessidades de diferentes setores produtivos com foco em qualidade, resistência e eficiência operacional. Sua atividade principal é a produção de artefatos estampados de metal.

Entre suas principais atividades estão a fabricação de artefatos estampados de metal, estruturas metálicas para uso industrial e construtivo, peças e componentes metálicos, máquinas e equipamentos para aplicações específicas, além da montagem de estruturas e fornecimento de soluções industriais personalizadas. A empresa atua com foco em inovação, precisão técnica, qualidade dos processos produtivos e atendimento às demandas do setor industrial.', NULL),
(59, 'D & R Indústria de Produtos de Limpeza Ltda é uma empresa de Goianira (GO) especializada na fabricação de sabões, detergentes sintéticos e produtos de limpeza destinados aos mercados doméstico e institucional.

A companhia também produz desinfetantes e aditivos industriais, além de atuar na distribuição atacadista de produtos de higiene e conservação, oferecendo soluções para limpeza e manutenção em diversos segmentos.', NULL),
(60, 'A JR. Fox Tendas Ltda atua no segmento de fabricação e comercialização de estruturas para eventos e coberturas, especializada no desenvolvimento de tendas, galpões, coberturas e estruturas metálicas para aplicações temporárias e permanentes. A empresa atende clientes dos setores de eventos, agronegócio, indústria, comércio e construção civil, oferecendo soluções que aliam praticidade, resistência e versatilidade.
Entre suas principais atividades estão a fabricação, venda, locação, montagem e manutenção de tendas, galpões lonados, coberturas, estruturas metálicas e acessórios, além do desenvolvimento de projetos personalizados para eventos, armazenagem, feiras, exposições e instalações industriais. A empresa atua com foco em qualidade dos materiais, segurança estrutural, inovação, agilidade na execução e atendimento às necessidades específicas de seus clientes e parceiros comerciais.', NULL),
(61, 'A Asa do Brasil é uma empresa brasileira especializada na fabricação de suplementos minerais, núcleos nutricionais e soluções para nutrição animal.

A companhia atende principalmente os setores de pecuária de corte e leite, oferecendo produtos voltados à suplementação e ao aumento da produtividade dos rebanhos. Seu foco está em desenvolver tecnologias e soluções nutricionais que contribuam para o desempenho e a saúde animal.

Com atuação no agronegócio, a Asa do Brasil se destaca pelo suporte técnico aos produtores rurais e pela oferta de produtos destinados à eficiência da produção pecuária.', NULL),
(62, 'A Imprensa Bíblica Cristã Ltda atua no segmento editorial e gráfico, especializada na produção, publicação, impressão e comercialização de materiais religiosos, educacionais e de conteúdo cristão. A empresa desenvolve produtos voltados à divulgação de ensinamentos bíblicos, formação espiritual e apoio às atividades de igrejas, instituições religiosas e leitores em geral.

Entre suas principais atividades estão a edição e publicação de livros, bíblias, revistas, estudos, materiais didáticos, devocionais e demais conteúdos impressos ou digitais de temática cristã, além da impressão, distribuição e comercialização dessas publicações. A empresa atua com foco em qualidade editorial, disseminação do conhecimento bíblico, excelência gráfica e atendimento às necessidades de instituições religiosas, educadores e leitores.', NULL),
(63, 'A Laticínio Asahi Ltda atua no segmento de laticínios, especializada na captação, processamento, industrialização e comercialização de leite e seus derivados. A empresa atende o mercado alimentício com produtos voltados ao consumo doméstico e comercial, priorizando qualidade, segurança dos alimentos e eficiência em seus processos produtivos.

Entre suas principais atividades estão o beneficiamento de leite, fabricação de queijos, manteiga, requeijão, creme de leite, bebidas lácteas, leite pasteurizado e outros derivados, além da embalagem, distribuição e comercialização desses produtos para supermercados, atacadistas, varejistas, estabelecimentos de alimentação e distribuidores.

A Laticínio Asahi atua com foco em qualidade, boas práticas de fabricação, conformidade com as normas sanitárias, inovação, sustentabilidade e satisfação de seus clientes, contribuindo para o fortalecimento da cadeia produtiva do leite e o fornecimento de alimentos seguros e de alto padrão ao mercado.', NULL),
(64, 'Eletrometa (Danfer Metalúrgica Ltda) é uma empresa de Goianira (GO) especializada na produção de artefatos estampados de metal, atendendo demandas dos setores industrial, elétrico e da construção civil.

